document.getElementById("active-data").textContent=JSON.stringify({"version":1,"dictation":{"2015-06-set3":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"As a Chinese woman working in China, and using traditional Chinese medical records, she rediscovered an ancient plant-based treatment for malaria that worked where modern therapies failed.","start":200.27,"end":213.12,"wordCount":28},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"“These discoveries are very important, but they were only part of the hydrological cycle on Mars that we are just now beginning to understand.","start":313.6,"end":325.68,"wordCount":24},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"What we are going to announce today is that Mars is not that dry planet we thought of in the past.”","start":325.68,"end":334.31,"wordCount":21},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"So what does this tell us about potential life on Mars?","start":334.4,"end":339.56,"wordCount":11},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"But could the planet support life today?","start":349.22,"end":352.35,"wordCount":7},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"Scientists say, technologically, we will now be able to answer those questions.","start":352.5,"end":359.57,"wordCount":12},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"It's my right to protect my life.\"","start":438.39,"end":441.11,"wordCount":7},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"The pro-gun rights Facebook page has been taken down.","start":441.28,"end":445.28,"wordCount":10},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The sheriff's department said it is investigating how the mother stored the gun.","start":445.39,"end":450.22,"wordCount":13},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"Florida law makes it a crime to store a loaded weapon in such a way that it can be taken or used by a child, according to the sheriff's department.","start":450.44,"end":458.95,"wordCount":30},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"\"Detectives have not been able to interview the victim and any decision on the filing of criminal charges will not come until after we speak with the victim,\" the sheriff's department said.","start":459.07,"end":469.82,"wordCount":32},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, it is cold, very cold in winter, sometimes as cold as 26 degrees below centigrade.","start":604.3,"end":611.4,"wordCount":16},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"And of course when you go out, you wrap up warm.","start":611.71,"end":615.19,"wordCount":11},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"But inside, in the houses it's always very warm, much warmer than at home.","start":615.4,"end":621.85,"wordCount":14},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"Swedish people always complain that when they visit England, the houses are cold even in a good winter.","start":622.14,"end":629.08,"wordCount":18},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"From May to July in the North of Sweden, the sun never sets.","start":642.87,"end":647.31,"wordCount":13},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"You can walk in the mountains and read a newspaper.","start":649.32,"end":652.3,"wordCount":10},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"Oh, yeah, \"the land of the midnight sun\".","start":652.3,"end":656.2,"wordCount":8},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"They'd like to work hard, but play hard, too.","start":671.38,"end":674.63,"wordCount":9},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"I think Londoners work longer hours, but I'm not sure this is a good thing.","start":674.69,"end":679.31,"wordCount":15},{"id":"g5-s4","groupIndex":4,"groupLabel":"Conversation 2","answer":"For example, in your case, what was your educational background?","start":783.12,"end":787.98,"wordCount":10},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, I did a degree in French at Nottingham.","start":787.98,"end":791.13,"wordCount":9},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"Then I went into local government because I found I was more interested in the administrative side, then progressed on to universities.","start":798.22,"end":806.38,"wordCount":22},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"So there wasn't any plan and there was no specific training.","start":806.47,"end":810.47,"wordCount":11},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"But in the first place, you did a French degree.","start":817.17,"end":820.31,"wordCount":10},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"In my time, there wasn't a degree you could do for administration.","start":820.5,"end":824.93,"wordCount":12},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"I think most of the administrators I've come across have degrees in all sorts of things.","start":825.24,"end":830.62,"wordCount":16},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, I know in my case, I did an English literature degree and I didn't really expect to end up doing what I'm doing now.","start":830.62,"end":838.64,"wordCount":25},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"Were you local to Nottingham, actually?","start":839.28,"end":841.74,"wordCount":6},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"Is there any reason why you went to Nottingham University?","start":841.89,"end":845.1,"wordCount":10},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"No, no, I come from the north of England, from West Yorkshire.","start":845.1,"end":849.07,"wordCount":12},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"Nottingham was one of the universities I put on my list.","start":849.27,"end":852.85,"wordCount":11},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"And I like the look of it.","start":852.85,"end":854.32,"wordCount":7},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"Were you from the industrial part of Yorkshire?","start":859.08,"end":861.84,"wordCount":8},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"Were they turned off because an American had the nerve to instruct Japanese in their own art form?","start":1005.86,"end":1012.12,"wordCount":18},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"Were they deliberately trying to signal their rejection of her?","start":1012.84,"end":1016.57,"wordCount":10},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"Japanese listeners sometimes close their eyes to enhance concentration.","start":1022.6,"end":1027.52,"wordCount":9},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Her listeners were showing their respect for her by chewing on her words.","start":1027.94,"end":1033.75,"wordCount":13},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Learning how different cultures signal respect can help you avoid misunderstandings.","start":1046.11,"end":1051.96,"wordCount":11},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"In the deaf culture of North America, many listeners show applause not by clapping their hands but by waving them in the air.","start":1054.74,"end":1063.8,"wordCount":23},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"In some cultures, both overseas and in some minority groups in North America, listeners are considered disrespectful if they look directly at the speaker.","start":1064.3,"end":1075.46,"wordCount":24},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"Along with improving the equipment, Chris began a program to train employees to use equipment better and do simple maintenance themselves.","start":1204.67,"end":1214.32,"wordCount":21},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"The training saved time for the employees and money for the company.","start":1214.75,"end":1219.09,"wordCount":12},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"Unfortunately, one serious problem developed during the year.","start":1219.36,"end":1223.81,"wordCount":8},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"Two employees that Chris hired were stealing, and he had to fire them.","start":1224.15,"end":1228.91,"wordCount":13},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"Chris knows, however, that someone else wants the new job, too.","start":1238.96,"end":1242.78,"wordCount":11},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Kim is in charge of purchasing and maintenance in another division of the company.","start":1243.1,"end":1247.79,"wordCount":14},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"She has also made several changes over the year.","start":1248.09,"end":1250.92,"wordCount":9},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"Chris knows that his boss likes Kim's work, and he expects that his work will be compared with hers.","start":1251.18,"end":1257.19,"wordCount":19},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"If you can accept that people from other cultures act according to their values, not yours, getting along with them will be much easier.","start":1392.93,"end":1402.06,"wordCount":24},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"So some of the values they teach may not be as important in the culture as they once were.","start":1405.81,"end":1412.08,"wordCount":19},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"But if you know about past values, it helps you to understand the present and many of the older values are still strong today.","start":1423.6,"end":1432.97,"wordCount":24},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Benjamin Franklin, a famous American diplomat, writer and scientist, died in 1790, but his proverb \"Time is money\" is taken more seriously by Americans of today than ever before.","start":1433.49,"end":1449.36,"wordCount":29},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"A study of proverbs from around the world shows that some values are shared by many cultures.","start":1449.8,"end":1457.16,"wordCount":17},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"In many cases though, the same idea is expressed differently.","start":1457.35,"end":1462.73,"wordCount":10}],"manualOnly":false},"2015-12-set1":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"An abnormally warm winter has brought flowers into bloom.","start":187.52,"end":191.85,"wordCount":9},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Several types of plants that usually wake up in the spring have already bloomed.","start":192.16,"end":196.89,"wordCount":14},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"While hazardous smoke choked Beijing on Friday with pollution levels exceeding the index.","start":197.06,"end":203.09,"wordCount":13},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"Weather forecasts say the pollution should ease from Saturday afternoon when as hoped a cold front in Beijing will disperse the smog.","start":207.12,"end":216.9,"wordCount":22},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"Google has predicted the cars will be ready for the road by 2020.","start":493.36,"end":498.14,"wordCount":13},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"I wonder if you can help me.","start":608.42,"end":610.53,"wordCount":7},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'll see what we can do.","start":612.2,"end":613.76,"wordCount":6},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"First of all, could you give me your full name?","start":624.53,"end":627.42,"wordCount":10},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"Fine, and your date of birth please?","start":638.38,"end":641.37,"wordCount":7},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"Which school did you go to?","start":646.72,"end":648.66,"wordCount":6},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"Now, where are you working at the moment?","start":666.32,"end":669.09,"wordCount":8},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, I've got a job as a shorthand-typist, but I'm not enjoying it very much and it doesn't pay very well.","start":669.09,"end":676.83,"wordCount":22},{"id":"g4-s33","groupIndex":3,"groupLabel":"Conversation 1","answer":"What would you like to do now then?","start":686.47,"end":688.49,"wordCount":8},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"But the idea is if you generate it from your side, it's got to affect the other side if you're getting the right customers in.","start":845.81,"end":854.65,"wordCount":25},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yeah, I must say that's one thing that's always struck me about being a pub owner.","start":854.65,"end":860.41,"wordCount":16},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"\" But it seems to me that it's actually very hard work.","start":869.82,"end":873.88,"wordCount":11},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"A drug user is the person who takes the drug.","start":1032.44,"end":1036.06,"wordCount":10},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"There are many kinds of drug users.","start":1036.72,"end":1039.68,"wordCount":7},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Experimental users may try drugs once or twice.","start":1039.73,"end":1043.95,"wordCount":8},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"They want to see what the effects will be.","start":1044.07,"end":1046.74,"wordCount":9},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"Recreational users take drugs to get high.","start":1047.06,"end":1050.63,"wordCount":7},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"They use drugs with friends or at parties to get into the mood of things.","start":1050.74,"end":1056.09,"wordCount":15},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"Regular users take drugs all the time.","start":1056.36,"end":1059.61,"wordCount":7},{"id":"g6-s16","groupIndex":5,"groupLabel":"Passage 1","answer":"Their whole life centers around drugs.","start":1069.01,"end":1071.91,"wordCount":6},{"id":"g6-s17","groupIndex":5,"groupLabel":"Passage 1","answer":"They feel extreme mental or physical pain without drugs.","start":1072.05,"end":1076.9,"wordCount":9},{"id":"g6-s18","groupIndex":5,"groupLabel":"Passage 1","answer":"It's not always easy to tell if someone is using drugs.","start":1077.1,"end":1081.43,"wordCount":11},{"id":"g6-s19","groupIndex":5,"groupLabel":"Passage 1","answer":"In the early stages, drug use is often hard to see.","start":1081.58,"end":1086.1,"wordCount":11},{"id":"g6-s22","groupIndex":5,"groupLabel":"Passage 1","answer":"Only a few kinds of drugs can cause physical dependence.","start":1095.36,"end":1099.66,"wordCount":10},{"id":"g6-s23","groupIndex":5,"groupLabel":"Passage 1","answer":"But almost any drug, when it's misused, can make a person think he needs it all the time.","start":1099.68,"end":1106.55,"wordCount":18},{"id":"g6-s24","groupIndex":5,"groupLabel":"Passage 1","answer":"By this time it's too late and the person is \"hooked\".","start":1106.69,"end":1111.05,"wordCount":11},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"The Healthy Choice product line was carefully tested with consumers before being introduced to the general public.","start":1202.22,"end":1209.55,"wordCount":17},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"The low sodium, low fat frozen dinners sold much better than expected.","start":1225.24,"end":1230.57,"wordCount":12},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"According to the firm's vice-president of marketing and sales, \"We benefited from low expectations.","start":1231.25,"end":1238.12,"wordCount":15},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"The products were much better than people thought they would be.\"","start":1238.28,"end":1241.71,"wordCount":11},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"The name \"Healthy Choice\" was chosen for the positive implication it held for consumers.","start":1260.67,"end":1266.51,"wordCount":14},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"This was accomplished through the dark green packaging that not only differed from the competitors but also suggested freshness and richness in vitamins.","start":1276.65,"end":1286.77,"wordCount":23},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"The lawyer argued that it is wrong to execute a person for a crime he committed while he was a minor.","start":1464.43,"end":1472.05,"wordCount":21},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"In the United States, the governor of a state has the power to change a sentence from the death penalty to life in prison.","start":1472.11,"end":1480.9,"wordCount":24},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Nonetheless, the governor of South Carolina refused to stop the execution.","start":1481.28,"end":1487.18,"wordCount":11},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"Roach was finally executed in 1986.","start":1487.36,"end":1491.93,"wordCount":6}],"manualOnly":false},"2016-06-set1":{"clips":[{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"However, he points out that many countries have not done so.","start":91.1,"end":95.89,"wordCount":11},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"Almost all companies recognize the importance of innovation today, but not many are able to integrate innovation into their business.","start":315.81,"end":325.45,"wordCount":20},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"A commentary in the Shanghai Daily points out that innovation doesn’t mean piles of documents.","start":325.87,"end":332.38,"wordCount":15},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"The article says many people tend to assume that innovation just means creating something new, but actually it’s more than that.","start":335.16,"end":343.78,"wordCount":21},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"It’s an attitude of doing things.","start":344.2,"end":346.64,"wordCount":6},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"A company should find ways to innovate not just in products but also in functions, business models and processes.","start":346.81,"end":355.28,"wordCount":19},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"It also has a special innovation facility for its employees.","start":378.76,"end":383.68,"wordCount":10},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"Sometimes its employees are released from their daily jobs for weeks and spend their time interacting in the innovation facility instead.","start":384.21,"end":393.52,"wordCount":21},{"id":"g3-s12","groupIndex":2,"groupLabel":"News Report 3","answer":"In conclusion, the article says innovative ideas alone do not ensure success.","start":394.19,"end":400.28,"wordCount":12},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yeah, I text message a lot.","start":518.74,"end":521.14,"wordCount":6},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"I don’t do it so much.","start":521.14,"end":522.9,"wordCount":6},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"I prefer to make a call if I’m in a hurry.","start":523.04,"end":525.61,"wordCount":11},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"Sometimes I don’t really want to talk to the person.","start":527.98,"end":530.97,"wordCount":10},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"I just want to ask them one question, so it’s much easier for me just to text message.","start":531.34,"end":537.34,"wordCount":18},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"If I call them, I’ll have to have a long conversation.","start":537.38,"end":541.05,"wordCount":11},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yeah, I can see what you mean.","start":541.05,"end":543.26,"wordCount":7},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"But I get off the phone pretty quickly when I call.","start":543.44,"end":546.36,"wordCount":11},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"So are you fast at writing the messages with your thumb?","start":551.12,"end":554.69,"wordCount":11},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, when I first got a cell phone, I was so slow.","start":554.93,"end":558.95,"wordCount":12},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"I thought I would never text message.","start":558.98,"end":561.29,"wordCount":7},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"But then people kept text messaging me, so I felt obliged to learn how to text message.","start":561.29,"end":567.22,"wordCount":17},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"Actually I have the opposite problem.","start":570.3,"end":572.91,"wordCount":6},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yeah, I think text-messaging actually sort of has to do with your age.","start":587.13,"end":592.47,"wordCount":14},{"id":"g4-s26","groupIndex":3,"groupLabel":"Conversation 1","answer":"For example, people in high school, they text message a lot.","start":592.47,"end":597.44,"wordCount":11},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"He said he’d never text message.","start":602.85,"end":605.77,"wordCount":6},{"id":"g4-s30","groupIndex":3,"groupLabel":"Conversation 1","answer":"He thinks it’s very childish and unprofessional to text message.","start":605.77,"end":610.31,"wordCount":10},{"id":"g4-s31","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yeah, I can see what he means.","start":610.31,"end":612.72,"wordCount":7},{"id":"g4-s32","groupIndex":3,"groupLabel":"Conversation 1","answer":"It’s considered pretty informal to text message someone.","start":612.77,"end":616.23,"wordCount":8},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"What seems to be the problem?","start":720.0,"end":722.0,"wordCount":6},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, ever since Sandra left the department, I feel like I’ve been targeted to do all her work as well as mine.","start":722.09,"end":730.31,"wordCount":22},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’m expected to attend too many meetings and I seem to be spending a lot of my time doing unnecessary paperwork.","start":730.62,"end":738.0,"wordCount":21},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"But that afternoon, even though I’d finished my assigned work, I was told to help other colleagues finish their work, too.","start":748.92,"end":756.46,"wordCount":21},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yes, but other colleagues get to leave early, and they don’t have such a lot of work to do.","start":762.72,"end":768.54,"wordCount":19},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"So you feel he’s been making unrealistic demands on you?","start":768.54,"end":772.67,"wordCount":10},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’ve tried, but it seems like he just has no time for me.","start":778.26,"end":782.21,"wordCount":13},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, at this stage, it would be better if you approached him directly.","start":782.46,"end":786.93,"wordCount":13},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"If nothing else, showing that you’ve tried to solve the problem yourself, before you take it further, makes it clear that you’re not just a complainer.","start":786.93,"end":795.84,"wordCount":26},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"Why don’t you send an email requesting a meeting with him in private?","start":795.97,"end":800.36,"wordCount":13},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"“The link between sleep and health, and bad sleep and disease is becoming clearer and clearer,” says Lawrence Epstein, a sleep expert at Harvard University.","start":970.08,"end":981.11,"wordCount":25},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"At the same time, high blood pressure has become an increasing problem.","start":990.89,"end":995.32,"wordCount":12},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"Blood pressure and heart rate are typically at their lowest levels during sleep.","start":996.04,"end":1001.42,"wordCount":13},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"People who sleep less tend to have higher blood pressure, heart attack, diabetes, weight gain and other problems.","start":1002.62,"end":1010.69,"wordCount":18},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"Sleeping better may help fight off illness.","start":1011.5,"end":1014.49,"wordCount":7},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"A university of Chicago study shows people who sleep well live longer.","start":1028.1,"end":1033.5,"wordCount":12},{"id":"g6-s16","groupIndex":5,"groupLabel":"Passage 1","answer":"So say good night sooner and it may help you stay active and vital to a ripe old age.","start":1034.17,"end":1040.4,"wordCount":19},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"Do you have the right combination of subjects and are your expected grades likely to meet entry requirements?","start":1142.92,"end":1149.9,"wordCount":18},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"But it is best to submit your application early because universities begin work as soon as forms start rolling in.","start":1153.18,"end":1160.55,"wordCount":20},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"The most important part of the application is the much feared personal statement.","start":1161.59,"end":1166.85,"wordCount":13},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"This is your chance to convey boundless enthusiasm for the subject.","start":1167.18,"end":1171.76,"wordCount":11},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"So economy of expression is foremost.","start":1171.77,"end":1174.84,"wordCount":6},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Omit dull and ineffective generalities and make sure you give concrete examples.","start":1175.26,"end":1181.02,"wordCount":12},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"Admissions officers read every personal statement that arrives.","start":1181.83,"end":1185.98,"wordCount":8},{"id":"g7-s16","groupIndex":6,"groupLabel":"Passage 2","answer":"You have to get across what it is about a particular area that has inspired you.","start":1191.2,"end":1196.75,"wordCount":16},{"id":"g7-s17","groupIndex":6,"groupLabel":"Passage 2","answer":"They will look for evidence that you have reflected and thought about the subject.","start":1197.42,"end":1201.88,"wordCount":14},{"id":"g7-s19","groupIndex":6,"groupLabel":"Passage 2","answer":"There is no point saying you run marathons if you are going to be out of breath arriving at the interview on the second floor.","start":1204.94,"end":1212.39,"wordCount":25},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"Henry Ford’s Model T introduced in America in 1909 was cheaper because it was made on the assembly line.","start":1325.85,"end":1334.42,"wordCount":19},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"It brought cars closer towards the reach of ordinary people.","start":1335.08,"end":1338.99,"wordCount":10},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Today, the legal driving age for a car in the UK is 17.","start":1352.87,"end":1357.97,"wordCount":13},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"You are not allowed to drive a car unsupervised until you have passed a driving test.","start":1358.3,"end":1363.84,"wordCount":16},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"In 1958, Britain celebrated the opening of its first motorway—the Preston Bypass.","start":1364.94,"end":1371.7,"wordCount":13}],"manualOnly":false},"2016-06-set2":{"clips":[{"id":"g1-s1","groupIndex":0,"groupLabel":"News Report 1","answer":"You probably think college students are experts at sleeping, but parties, preparations for tests, personal problems and general stress can wreck a student’s sleep habits, which can be bad for the body and the mind.","start":150.46,"end":166.61,"wordCount":35},{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"People suffering from sleep loss are at an increased risk from obesity, psychological problems and car crashes.","start":174.16,"end":182.45,"wordCount":17},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"Students who don’t get enough sleep have poor attendance and lower grades.","start":182.77,"end":188.08,"wordCount":12},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Subjects who learned the games in the morning lost some skills when they played again 12 hours later, but they did much better after getting a good night’s sleep.","start":207.27,"end":218.94,"wordCount":29},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"So if you really want to do your job well, don’t forget to get some sleep.","start":219.18,"end":225.09,"wordCount":16},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"The idea is that competition between rival operators would lead to better service at airports.","start":318.89,"end":325.79,"wordCount":15},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"The biggest increases tended to be in brands that were popular with young smokers.","start":430.02,"end":435.75,"wordCount":14},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"That worries the department because of the addictive nature of nicotine.","start":436.27,"end":440.89,"wordCount":11},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"Stand Glance, a professor of medicine in San Francisco explains why.","start":441.48,"end":447.34,"wordCount":11},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"The big tobacco companies have always insisted that they are frank with their customers about the dangers of smoking and provide them with enough detail to make an informed decision.","start":459.25,"end":470.95,"wordCount":30},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"However, none of them were prepared to comment on this study or discuss the detailed nicotine content of their products.”","start":471.32,"end":479.55,"wordCount":20},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's great that you have had this experience of teaching in Indonesia and following up on what you just mentioned.","start":597.36,"end":604.35,"wordCount":20},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"I don't know about perfecting but they want at least to be able to communicate decently.","start":612.67,"end":617.87,"wordCount":16},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"How can they go about this?","start":618.1,"end":619.79,"wordCount":6},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"So I have to make a real effort to practice.","start":636.58,"end":639.69,"wordCount":10},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"But for speaking, there really is no substitute for trying to speak and use the language in a relaxed atmosphere.","start":652.72,"end":660.28,"wordCount":20},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"So I think that's really the challenge for people who live in a country where their target language isn't spoken.","start":660.3,"end":667.71,"wordCount":20},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"And for that, gosh, what would I do?","start":668.04,"end":671.32,"wordCount":8},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"If I didn't have people here, probably try to find a club?","start":671.58,"end":677.15,"wordCount":12},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"If the law isn't there, people will drive within their ability range.","start":844.23,"end":848.99,"wordCount":12},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"When you've got speed limits, this creates situations that actually present dangers on the road.","start":849.35,"end":855.91,"wordCount":15},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you think Germans have better education about personal responsibility when driving?","start":855.96,"end":861.13,"wordCount":12},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"They also have very good cars.","start":862.29,"end":864.85,"wordCount":6},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"If you've got a good car that can go at a high speed then it's really nice to do that.","start":865.62,"end":871.6,"wordCount":20},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"So I think it's the restrictions that create the dangers sometimes.","start":873.14,"end":878.07,"wordCount":11},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yes, speed bumps, those speed bumps that force you to slow down.","start":887.83,"end":892.42,"wordCount":12},{"id":"g5-s27","groupIndex":4,"groupLabel":"Conversation 2","answer":"Not really, because the police don't have time to police every single driver.","start":897.58,"end":903.37,"wordCount":13},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"He wrapped one layer of the plastic around the card and tried again.","start":1051.11,"end":1055.63,"wordCount":13},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"\"I don't know how it works.","start":1059.6,"end":1061.67,"wordCount":6},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"Today's shaky economy is likely to produce many more such tricks.","start":1089.46,"end":1094.97,"wordCount":11},{"id":"g6-s18","groupIndex":5,"groupLabel":"Passage 1","answer":"Today, Americans are finding their own tips and tricks for fixing malfunctioning devices with supplies as simple as paper and glue.","start":1120.05,"end":1130.4,"wordCount":21},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"Graduation requirements specify the number of credits you must earn, the minimum grade point average you must achieve and the distribution of credits you must have from among differing departments or fields of study.","start":1295.59,"end":1311.21,"wordCount":34},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"Since graduation requirements vary among divisions of the university, you should consult the Bulletin of Information.","start":1321.72,"end":1329.68,"wordCount":16},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"Her mother taught her to diet when she was only eight years old.","start":1447.61,"end":1451.91,"wordCount":13},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"She shows them pictures and images from popular culture of beautiful women and explains how computers are used to make the women look even more thin and “beautiful” than they are in real life.","start":1470.91,"end":1484.18,"wordCount":34},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"She describes how the definition of beauty has changed over the years and even from culture to culture.","start":1485.15,"end":1492.4,"wordCount":18},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"She then talks about health issues and the physical damage that can occur as a result of dieting.","start":1493.49,"end":1499.96,"wordCount":18}],"manualOnly":false},"2016-12-set1":{"clips":[{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"Details about what led to the workers’ being trapped in the elevator weren’t immediately available.","start":313.55,"end":319.65,"wordCount":15},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"So like any other business you have to make choices.”","start":435.19,"end":438.83,"wordCount":10},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"Dean Granholm, the vice president for delivery and post office operations, said the first wave of closings would begin this fall.","start":439.2,"end":448.7,"wordCount":21},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"One of the press operators arrived an hour and a half late.","start":563.29,"end":566.28,"wordCount":12},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"He’ll simply lose part of his pay.","start":568.67,"end":570.96,"wordCount":7},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"That’s why we have a clock-in system.","start":570.96,"end":573.63,"wordCount":8},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"But the point is the man was clocked-in at 8 o’clock.","start":573.63,"end":576.98,"wordCount":12},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"We have John standing by the time clock, and he swears he saw nothing irregular.","start":577.13,"end":581.61,"wordCount":15},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"That’s why we chose him for the job.","start":584.63,"end":586.67,"wordCount":8},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"Have you spoken to the man who was late?","start":587.07,"end":589.49,"wordCount":9},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"I thought I’d have a word with you first.","start":590.39,"end":592.72,"wordCount":9},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"He’s a difficult man, and I think there’s been some trouble on the shop floor.","start":592.8,"end":596.96,"wordCount":15},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"The manager told me that Jack Green’s been very active around the shop the last few days.","start":600.96,"end":606.14,"wordCount":17},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, what do you want me to do?","start":606.45,"end":608.94,"wordCount":8},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"I must say I agree with you about there being bad feelings in the works.","start":617.53,"end":622.27,"wordCount":15},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’ve had the idea for some time that Jack Green’s been busy stirring things up in connection with the latest wage claim.","start":622.27,"end":630.52,"wordCount":22},{"id":"g4-s26","groupIndex":3,"groupLabel":"Conversation 1","answer":"He’s always trying to make trouble.","start":630.83,"end":633.0,"wordCount":6},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, I’ll get the manager to send Smith up here.","start":633.0,"end":636.37,"wordCount":10},{"id":"g5-s1","groupIndex":4,"groupLabel":"Conversation 2","answer":"Our topic today is about something that foreigners nearly always say when they visit Britain.","start":721.38,"end":727.25,"wordCount":15},{"id":"g5-s2","groupIndex":4,"groupLabel":"Conversation 2","answer":"It's “Why are the British so cold?”","start":727.4,"end":730.1,"wordCount":7},{"id":"g5-s4","groupIndex":4,"groupLabel":"Conversation 2","answer":"It means that we aren't very friendly, we aren't very open.","start":735.78,"end":739.68,"wordCount":11},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"So do you think it's true?","start":739.68,"end":741.47,"wordCount":6},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"So many people who visit Britain say it's difficult to make friends with British people.","start":743.76,"end":749.78,"wordCount":15},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"They speak the same language, but they're much more open.","start":757.3,"end":760.51,"wordCount":10},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"And you see it when you travel, people—I mean strangers—speak to you on the street or on the train.","start":760.58,"end":766.64,"wordCount":21},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"British people seldom speak on the train, or the bus.","start":766.78,"end":770.59,"wordCount":10},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"Capital cities are full of tourists and are never friendly.","start":775.29,"end":779.23,"wordCount":10},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"I met a woman once, an Italian.","start":783.59,"end":785.9,"wordCount":7},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"They were friendly to her at work, but nothing else.","start":793.83,"end":797.15,"wordCount":10},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"She said that would never happen in Italy.","start":799.18,"end":801.85,"wordCount":8},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"You know what they say—An Englishman's home is his castle.","start":802.41,"end":806.86,"wordCount":11},{"id":"g5-s30","groupIndex":4,"groupLabel":"Conversation 2","answer":"That's why the British don't like flats.","start":816.46,"end":818.93,"wordCount":7},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"If you are a college student looking for a part-time job, the best place to start your job search is right on campus.","start":967.12,"end":974.83,"wordCount":24},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Plus, on-campus jobs eliminate commuting time, and could be a great way to connect with academic and professional resources at your university.","start":983.87,"end":994.44,"wordCount":23},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"Check with your school's career service or employment office for help to find a campus job.","start":994.95,"end":1001.2,"wordCount":16},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Of course, there are opportunities for part-time work off campus, too.","start":1001.71,"end":1006.66,"wordCount":12},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"He says the prices this year have been so low that he has made almost no profit.","start":1144.1,"end":1150.26,"wordCount":17},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"He says he must grow different kinds of tea if he is to survive.","start":1150.41,"end":1155.34,"wordCount":14},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Its leaves are purple and brown.","start":1168.11,"end":1170.8,"wordCount":6},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"When the tea is boiled, the drink has a purple color.","start":1170.86,"end":1174.93,"wordCount":11},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"Medical researchers have studied the health benefits of the new tea.","start":1175.37,"end":1180.01,"wordCount":11},{"id":"g7-s19","groupIndex":6,"groupLabel":"Passage 2","answer":"He says the market for the tea is unstable and he is often forced to sell his purple tea for the same price as green tea leaves.","start":1195.77,"end":1205.68,"wordCount":27},{"id":"g7-s20","groupIndex":6,"groupLabel":"Passage 2","answer":"He says there are not enough buyers willing to pay more for the purple tea.","start":1205.68,"end":1211.04,"wordCount":15},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"Today’s consumers want beautiful handcrafted objects to wear and to have for their home environment.","start":1278.09,"end":1284.79,"wordCount":15},{"id":"g8-s2","groupIndex":7,"groupLabel":"Passage 3","answer":"They prefer something unique and they demand quality.","start":1285.21,"end":1289.01,"wordCount":8},{"id":"g8-s4","groupIndex":7,"groupLabel":"Passage 3","answer":"People and homes are showing great change as more and more unique handcrafted items become available.","start":1293.16,"end":1300.63,"wordCount":16},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"No longer does a good craftsman have to work in a job he dislikes all day and then try to create at night.","start":1303.67,"end":1311.05,"wordCount":23},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"He has earned his professional status.","start":1311.28,"end":1313.82,"wordCount":6},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"He is now a respected member of society.","start":1314.05,"end":1317.2,"wordCount":8},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"They love to share their ideas and materials and help others find markets for their work.","start":1322.51,"end":1328.51,"wordCount":16},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"They help them become aware of design and technique.","start":1334.37,"end":1338.24,"wordCount":9},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"They help them relate their choice to its intended use.","start":1338.83,"end":1342.27,"wordCount":10},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"They often involve consumers in trying the craft themselves.","start":1342.77,"end":1346.98,"wordCount":9},{"id":"g8-s17","groupIndex":7,"groupLabel":"Passage 3","answer":"State art councils help sponsor local arts and crafts festivals which draw crowds of tourist consumers.","start":1366.71,"end":1374.19,"wordCount":16}],"manualOnly":false},"2016-12-set2":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"When that happened, people came from all over the world to see the falls turned off.","start":198.33,"end":205.1,"wordCount":16},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"They want to see what's underneath.","start":207.8,"end":210.41,"wordCount":6},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"In fact, those who first came to have a look did see something.","start":210.41,"end":215.91,"wordCount":13},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"They found millions of coins on the bottom.","start":215.91,"end":218.86,"wordCount":8},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"A plant uses only a small part of the energy produced by that process.","start":421.86,"end":427.86,"wordCount":14},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The rest goes into the soil.","start":428.03,"end":430.43,"wordCount":6},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"The device plugs into the ground and then into a mobile phone.","start":433.86,"end":438.96,"wordCount":12},{"id":"g4-s26","groupIndex":3,"groupLabel":"Conversation 1","answer":"We have to be back at full capacity tomorrow morning.","start":624.93,"end":628.42,"wordCount":10},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"Is it a major job to repair our robots?","start":628.49,"end":631.7,"wordCount":9},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"That's what the maintenance engineer says.","start":632.67,"end":634.63,"wordCount":6},{"id":"g5-s4","groupIndex":4,"groupLabel":"Conversation 2","answer":"Everybody is making me out to be some sort of superhero.","start":760.94,"end":764.2,"wordCount":11},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"You were going to an interview when the incident occurred, right?","start":771.47,"end":775.24,"wordCount":11},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"I was on my way to apply for a maintenance position.","start":775.89,"end":779.07,"wordCount":11},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've been looking for a job for a year and more.","start":779.17,"end":782.17,"wordCount":11},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm looking for something to support my family.","start":782.22,"end":784.56,"wordCount":8},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"Tell us what happened at the station?","start":784.75,"end":787.33,"wordCount":7},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"It had to be 30 to 40 miles an hour?","start":788.86,"end":791.66,"wordCount":10},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"The wind blew the baby onto the tracks.","start":795.55,"end":797.95,"wordCount":8},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"In the distance, people could see the train rounding a bend headed into the station.","start":808.95,"end":814.64,"wordCount":15},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"No, I just jumped down and grabbed the baby.","start":818.11,"end":821.13,"wordCount":9},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"The train was coming around the corner as I lifted the baby from the tracks.","start":821.15,"end":824.83,"wordCount":15},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"There's one sound that gets a big reaction from kids on a hot day—the sound of an ice-cream truck.","start":952.81,"end":959.54,"wordCount":21},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"“When there are three kids and only two of them have money, I always make sure the third one gets something, because I can't drive away and have that third one not have something,” she said.","start":1024.52,"end":1035.66,"wordCount":36},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"The water supply would stop; the streets might not be cleaned; schools would be closed.","start":1134.96,"end":1141.28,"wordCount":15},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"We would not want to live in such a city.","start":1141.51,"end":1144.51,"wordCount":10},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"The chief duty of every government is to protect persons and property.","start":1144.89,"end":1149.81,"wordCount":12},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"More than three fourths of government expenses are used for this purpose.","start":1149.98,"end":1155.35,"wordCount":12},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"The next largest amount of public money goes to teach and train our citizens.","start":1155.66,"end":1161.13,"wordCount":14},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"Billions of dollars each year are spent on schools and libraries.","start":1161.37,"end":1166.34,"wordCount":11},{"id":"g7-s16","groupIndex":6,"groupLabel":"Passage 2","answer":"Also a large amount of public funds is spent on roads.","start":1166.38,"end":1170.81,"wordCount":11},{"id":"g7-s17","groupIndex":6,"groupLabel":"Passage 2","answer":"Most of the needed funds is raised by taxes.","start":1171.06,"end":1174.43,"wordCount":9},{"id":"g7-s18","groupIndex":6,"groupLabel":"Passage 2","answer":"The law orders us to pay taxes.","start":1174.73,"end":1177.35,"wordCount":7},{"id":"g7-s19","groupIndex":6,"groupLabel":"Passage 2","answer":"We have no choice in the matter.","start":1177.35,"end":1179.59,"wordCount":7},{"id":"g7-s20","groupIndex":6,"groupLabel":"Passage 2","answer":"Years ago, the government made money by selling public lands, but most of the best public lands have now been sold.","start":1180.1,"end":1188.5,"wordCount":21},{"id":"g7-s22","groupIndex":6,"groupLabel":"Passage 2","answer":"They could be sold, but we want to save them for future years.","start":1195.15,"end":1199.77,"wordCount":13},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Andorra, with an area of some 200 square miles, is considerably larger than Monaco.","start":1322.96,"end":1329.28,"wordCount":14},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"This country is located in the Pyrenees Mountains, with France on one side and Spain on the other.","start":1329.72,"end":1336.58,"wordCount":18},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Potatoes and tobacco are grown in Andorra's steep mountain valleys.","start":1337.54,"end":1342.69,"wordCount":10},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"One of the products it exports is clothing.","start":1342.92,"end":1345.64,"wordCount":8},{"id":"g8-s17","groupIndex":7,"groupLabel":"Passage 3","answer":"Taxes are low, so many businesses have their headquarters here.","start":1367.79,"end":1371.98,"wordCount":10},{"id":"g8-s18","groupIndex":7,"groupLabel":"Passage 3","answer":"The country makes and exports a lot of machinery.","start":1372.39,"end":1375.73,"wordCount":9},{"id":"g8-s20","groupIndex":7,"groupLabel":"Passage 3","answer":"Each of these has unique qualities as well.","start":1381.98,"end":1384.7,"wordCount":8}],"manualOnly":false},"2017-06-set1":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"The man in the Google vehicle reported that he assumed the bus would slow down to let the car out, and so he did not switch to the manual mode.","start":73.88,"end":84.03,"wordCount":30},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"In a statement, Google said, \"We clearly bear some responsibility, because if our car hadn't moved, there wouldn't have been a crash.","start":84.15,"end":93.99,"wordCount":22},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"That said, our test driver believed the bus was going to slow or stop to allow us to merge into the traffic, and that there would be sufficient space to do that.\"","start":94.1,"end":106.15,"wordCount":32},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"The company's self-driving cars have done well over a million miles across various states in the US, and until now have only reported minor accidents.","start":106.81,"end":119.05,"wordCount":26},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"When he looked closer, he realized it was a huge group of bees.","start":185.01,"end":190.4,"wordCount":13},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"Moses said, “I’ve never seen that many bees in one spot.","start":190.9,"end":195.38,"wordCount":11},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"They were very close together and there was a lot of noise and movement.","start":197.6,"end":202.23,"wordCount":14},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"It was interesting to see such a strange sight, but there were a lot of people around and I was a bit worried about the bees and the people stopping to look.","start":202.68,"end":213.63,"wordCount":32},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"I thought that someone might do something stupid.”","start":214.16,"end":217.14,"wordCount":8},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"Moses called two local bee specialists who helped remove the bees by attracting them into a box.","start":217.89,"end":225.3,"wordCount":17},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"Moses spent three hours looking after the bees and was stung five times.","start":226.0,"end":231.74,"wordCount":13},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"He said, “my stings are a bit painful but I’m pleased it all worked out and I could help.","start":232.18,"end":238.61,"wordCount":19},{"id":"g2-s12","groupIndex":1,"groupLabel":"News Report 2","answer":"People need to realize that bees are valuable and they should be looked after.”","start":238.74,"end":244.0,"wordCount":14},{"id":"g3-s1","groupIndex":2,"groupLabel":"News Report 3","answer":"A new species of snake has been discovered on a remote island in the Bahamas.","start":288.44,"end":294.4,"wordCount":15},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"The second trip was made in October last year.","start":301.94,"end":305.36,"wordCount":9},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"The snake has been named Silver Boa because it is metal-colored and the first specimen found was climbing a silver palm tree.","start":312.79,"end":322.74,"wordCount":23},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"The scientist confirmed the snake was a previously unknown species after conducting a genetic analysis of tissue samples.","start":327.84,"end":337.76,"wordCount":18},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"Commenting on the find, snake expert Robert Henderson, from the Milwaukee Museum of Natural History, said: \"Worldwide, new species of frogs are being discovered and described quite regularly.","start":337.99,"end":352.96,"wordCount":28},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"New species of snakes, however, are much rarer.\"","start":353.47,"end":358.3,"wordCount":8},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"I had a wonderful time here.","start":461.85,"end":463.88,"wordCount":6},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"Now I'm going to the airport.","start":463.97,"end":466.17,"wordCount":6},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"My flight leaves in less than two hours, so could you tell me what's the quickest way to get there?","start":466.32,"end":472.59,"wordCount":20},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, we can call a taxi for you.","start":472.8,"end":476.04,"wordCount":8},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"We also have a free airport shuttle service.","start":476.04,"end":479.76,"wordCount":8},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"And I'm still terrified today, sort of subconsciously, you know, if I swallow one by mistake.","start":665.02,"end":672.23,"wordCount":16},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"The one that used to get me was that swans could break your leg with a blow of the wing.","start":675.75,"end":681.85,"wordCount":20},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"No, never heard of that, but my grandmother was a terror for that kind of thing.","start":697.19,"end":703.03,"wordCount":16},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"For example, she would say you'll get a spot on your tongue if you tell a lie.","start":703.22,"end":708.9,"wordCount":17},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"If you eat stale bread, your hair will curl.","start":709.25,"end":712.79,"wordCount":9},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"We went on a camping trip once in Italy and my wife spent the whole time worrying about bats getting into her hair.","start":715.22,"end":723.41,"wordCount":23},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"She said her grandmother reckoned you had to shave your head to get it out.","start":723.79,"end":728.79,"wordCount":15},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"If I could go back in history and live when I liked, I wouldn't go back very far.","start":854.79,"end":860.88,"wordCount":18},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"In fact, I'd like to relive a period I've already lived—the 1960s.","start":860.94,"end":867.74,"wordCount":13},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"all that was very exciting with new things coming out.","start":891.28,"end":895.11,"wordCount":10},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"And when looking at angry humans, they tended to turn away their gaze.","start":1093.0,"end":1098.14,"wordCount":13},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"The researchers also note that dogs scan faces as a whole to sense how people are feeling, instead of focusing on a given feature.","start":1113.99,"end":1123.84,"wordCount":24},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"Winter in many places is very cold.","start":1201.0,"end":1204.42,"wordCount":7},{"id":"g8-s2","groupIndex":7,"groupLabel":"Passage 3","answer":"There is lots of snow around and the ground freezes, which can make life difficult for animals.","start":1204.48,"end":1211.43,"wordCount":17},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"People in cold places live in warm houses and have learned to adapt.","start":1211.86,"end":1217.64,"wordCount":13},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"There are three main ways that animals survive the cold in winter: sleep, adapt or migrate.","start":1219.9,"end":1228.1,"wordCount":16},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"Some animals such as bears, frogs and snakes, sleep all winter.","start":1228.31,"end":1234.95,"wordCount":11},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"They sleep very deeply, and need little or no food.","start":1234.95,"end":1239.51,"wordCount":10},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"To prepare for this before winter, these animals eat extra food to become fat which gives them the energy they need while they sleep.","start":1245.83,"end":1255.83,"wordCount":24}],"manualOnly":false},"2017-06-set2":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"The attitudes are published in a new AAA survey of 1,800 drivers.","start":70.99,"end":77.27,"wordCount":13},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"Advocates of self-driving cars argue they would be safer than in cars driven by humans because they wouldn't get distracted or drive when tired.","start":78.4,"end":88.35,"wordCount":25},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Many feel the technology is too new and unproven.","start":94.02,"end":98.05,"wordCount":9},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"He also believes they will be more likely to trust self-driving cars as they become more familiar with features such as automatic braking or parking.","start":109.8,"end":120.68,"wordCount":26},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"He estimated that the “comfort level” will increase considerably in five to ten years.","start":120.9,"end":127.05,"wordCount":14},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"Then Jeff King, a four-time champion, reported a similar attack.","start":212.32,"end":218.45,"wordCount":11},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"He faces trial on several charges.","start":250.31,"end":253.24,"wordCount":6},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"Hi, Susan, you're looking very smart today.","start":485.81,"end":489.34,"wordCount":7},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"Actually, I'm on my way to a job interview.","start":491.82,"end":495.69,"wordCount":9},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"Oh, you mean, for the summer holidays?","start":496.97,"end":499.46,"wordCount":7},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"I've got a second interview with that big foreign accountancy firm in the city center.","start":502.42,"end":508.0,"wordCount":15},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"The work is just helping out with data input, you know, but the pay isn't too bad.","start":511.25,"end":517.16,"wordCount":17},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"I know they have at least two temporary positions available.","start":519.24,"end":523.22,"wordCount":10},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"And I don't think they have anyone else yet.","start":523.22,"end":526.1,"wordCount":9},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"If they take you on, tell them you know a friend who'd be really good too.","start":527.81,"end":533.24,"wordCount":16},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"I really need the money and the experience would look good on my resume.","start":533.32,"end":538.37,"wordCount":14},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"If the boss likes me, I'll mention it.","start":544.05,"end":547.13,"wordCount":8},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"It'll be good to have someone around who I know.","start":547.14,"end":550.92,"wordCount":10},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"But perhaps you should put in an application anyway.","start":552.9,"end":556.65,"wordCount":9},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"Listen, do you want a lift to the city?","start":559.25,"end":562.13,"wordCount":9},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"I have my dad's car today, and nothing else to do this morning.","start":562.13,"end":566.43,"wordCount":13},{"id":"g4-s33","groupIndex":3,"groupLabel":"Conversation 1","answer":"By the way, how's your knowledge of accountancy?","start":571.23,"end":574.75,"wordCount":8},{"id":"g4-s37","groupIndex":3,"groupLabel":"Conversation 1","answer":"I might just have to review a few accountancy terms.","start":580.26,"end":583.97,"wordCount":10},{"id":"g4-s38","groupIndex":3,"groupLabel":"Conversation 1","answer":"Maybe you can give me a practice interview first.","start":584.11,"end":587.17,"wordCount":9},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"Poland performed as poorly as we did.","start":716.34,"end":719.75,"wordCount":7},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, it tells us that we need to think about the preparedness of our students as they are leaving high school.","start":780.49,"end":788.53,"wordCount":21},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"And schools, employers, in fact we all need to do something about it.","start":789.55,"end":794.49,"wordCount":13},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Wild carrots probably evolved with the other flowering plants about 360 million years ago.","start":920.25,"end":928.3,"wordCount":14},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"Like apples, carrots are native to Central Asia.","start":928.37,"end":932.81,"wordCount":8},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"That's why horses, which also come from Central Asia, like both apples and carrots so much.","start":932.9,"end":940.69,"wordCount":16},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"With wild carrots, the roots are white, small and skinny, so you'd have to pick a lot of wild carrots to get enough to eat.","start":941.13,"end":950.28,"wordCount":25},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"Doctors used carrot seeds and roots as medicine, on the theory that foods that taste bad must be good for you.","start":950.47,"end":958.5,"wordCount":21},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"But people still mostly fed carrots to horses, donkeys and pigs, and didn't eat them themselves.","start":982.66,"end":989.59,"wordCount":16},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"The red color was popular for Chinese New Year celebrations.","start":997.65,"end":1001.95,"wordCount":10},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"Today, cooler countries grow most of the world's carrots.","start":1014.91,"end":1019.41,"wordCount":9},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"Machines do most of the planting and picking, and carrots are easy to store and ship, so they are cheap almost everywhere.","start":1019.56,"end":1028.29,"wordCount":22},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"With Facebook, she could stay connected with her family no matter how far away they were.","start":1103.5,"end":1109.39,"wordCount":16},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"She could see their photos and read their status updates.","start":1109.57,"end":1113.41,"wordCount":10},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"With Facebook, she could keep her relatives up-to-date on what she was doing.","start":1113.56,"end":1118.79,"wordCount":15},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"Whenever she called her parents or other relatives, she always had to think about the time difference so that she wouldn't wake someone up or call when she knew they were at church.","start":1127.37,"end":1138.88,"wordCount":33},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"At first, this didn't bother her.","start":1148.82,"end":1151.28,"wordCount":6},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"She loved finding out people were getting married, having babies, and traveling.","start":1157.44,"end":1162.77,"wordCount":12},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"She was also spending a lot of time on Facebook.","start":1178.06,"end":1181.84,"wordCount":10},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"It took a lot of time and energy to keep up with everyone's status updates.","start":1182.18,"end":1188.01,"wordCount":15},{"id":"g7-s17","groupIndex":6,"groupLabel":"Passage 2","answer":"She looked at the list of over 500 friends she had on Facebook and realized some of them were not really friends at all.","start":1190.61,"end":1199.95,"wordCount":24},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Farmers and farm animal breeders would bring their animals to market every April to show, buy, and trade.","start":1329.92,"end":1337.42,"wordCount":18},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"This was an important business before the days of tractors, when many families made a living from farming and mules were used as work animals.","start":1337.8,"end":1347.4,"wordCount":25},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"Eventually, tractors began to replace mules, making them less in demand.","start":1347.83,"end":1353.48,"wordCount":11},{"id":"g8-s17","groupIndex":7,"groupLabel":"Passage 3","answer":"Over the years other activities have been added, and today more than 200,000 people show up each year to watch and participate.","start":1359.92,"end":1370.47,"wordCount":23}],"manualOnly":false},"2017-12-set1":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"“She decided to go outside and have a lemonade stand and make some drawings and pictures and sell them.”","start":75.86,"end":82.67,"wordCount":19},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"The family turned to social media expressing their gratitude saying, \"From the bottom of our hearts, we would like to deeply thank each and every person that stopped by!\"","start":105.86,"end":117.75,"wordCount":29},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"In November 2015, the Netherlands completed a 229-foot long bike path paved with solar panels as a test for future projects.","start":218.53,"end":229.21,"wordCount":22},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’ve never heard of a golden birthday.","start":484.79,"end":487.42,"wordCount":7},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"A golden or lucky birthday is when one turns the age of their birth date.","start":495.19,"end":501.28,"wordCount":15},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"Come to think of it , my parents did throw her a surprise party that year.","start":511.56,"end":516.38,"wordCount":15},{"id":"g4-s30","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’m sure both of you will have a fantastic time.","start":561.07,"end":564.1,"wordCount":10},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"They can recognize power and know how to use it.","start":669.67,"end":672.95,"wordCount":10},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"And perhaps most importantly, they know when to stop.","start":685.03,"end":689.86,"wordCount":9},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"And what about an unsuccessful negotiator?","start":690.06,"end":694.19,"wordCount":6},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"In your opinion, can the skills of negotiation be taught?","start":719.09,"end":723.64,"wordCount":10},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"Actually, space technology helps people on earth every day.","start":900.57,"end":905.39,"wordCount":9},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"In early space programs, such as the Apollo missions of the 1960s and 1970s, and in the space shuttle missions today, scientists developed objects for the astronauts to use on the moon and in space.","start":915.03,"end":930.16,"wordCount":35},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"We now use some of these objects every day.","start":931.06,"end":933.8,"wordCount":9},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"For example, we have quartz crystal clocks and watches accurate to within one minute a year.","start":934.57,"end":942.09,"wordCount":16},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"By the 18th century, there was a feeling of community that had grown.","start":1082.77,"end":1087.52,"wordCount":13},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"My ancestor was a preacher traveling around the countryside.","start":1087.71,"end":1091.83,"wordCount":9},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"I'm deeply attached to the Puritan tradition, not in a religious sense, but they believed in working for something, working for goals, and I like that.","start":1108.45,"end":1119.39,"wordCount":26},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"They worked hard at whatever they did, but they had a sense of achievement.","start":1119.58,"end":1124.72,"wordCount":14},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"Streams normally flow through wetland before they reach a lake or a river.","start":1269.73,"end":1275.61,"wordCount":13},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"Though there are more eatable plants, there may also be wild animals, poisonous snakes, and other hazards.","start":1275.69,"end":1284.37,"wordCount":17},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"and you may even spot a highway or a railroad from this point.","start":1302.38,"end":1306.59,"wordCount":13},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Nowadays, the first way someone will search for you is by air.","start":1307.51,"end":1312.22,"wordCount":12},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Also when someone comes looking, you should be able to signal to them.","start":1326.53,"end":1331.11,"wordCount":13}],"manualOnly":false},"2017-12-set2":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"Pedals apparently has an injured leg or paw that doesn’t allow it to walk comfortably on all fours according to experts.","start":67.8,"end":76.54,"wordCount":21},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"Americans drove more miles last year than any other year on record.","start":172.28,"end":176.63,"wordCount":12},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"What happened next will pull at your heartstrings.","start":296.38,"end":299.53,"wordCount":8},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"Listen, why don’t you come along?","start":487.2,"end":489.82,"wordCount":6},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"Mom would be absolutely delighted to see you again.","start":489.88,"end":493.01,"wordCount":9},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, I’d love to see her too.","start":494.95,"end":497.17,"wordCount":7},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"What time are you heading off?","start":512.2,"end":514.04,"wordCount":6},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, I was going to leave right away.","start":514.35,"end":516.99,"wordCount":8},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"However, I can hang around for you if you like.","start":517.12,"end":520.1,"wordCount":10},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"It just means that I’ll need to change my ticket.","start":520.26,"end":522.91,"wordCount":10},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"But would that be too much trouble for you?","start":522.93,"end":525.43,"wordCount":9},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’ll go to the station first, and see if I can get tickets for us on the 6:30 train.","start":527.37,"end":533.21,"wordCount":20},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’ll text you when it’s done.","start":535.78,"end":537.53,"wordCount":6},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"Are you absolutely positive it’s okay?","start":538.43,"end":541.62,"wordCount":6},{"id":"g4-s31","groupIndex":3,"groupLabel":"Conversation 1","answer":"And as I always say, the more, the merrier.","start":547.03,"end":550.56,"wordCount":9},{"id":"g4-s32","groupIndex":3,"groupLabel":"Conversation 1","answer":"Look, I’d better go, or I’ll be late.","start":550.62,"end":553.32,"wordCount":8},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"Good, the term is coming to an end.","start":644.34,"end":647.12,"wordCount":8},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you think we should take a holiday overseas to relax and have fun?","start":647.36,"end":651.37,"wordCount":14},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’ve saved my tips for my waiter job these past few months and I should have enough by July.","start":651.54,"end":656.78,"wordCount":19},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’ve got a little put-aside for a rainy day, but I might need to earn a little more before we go.","start":659.2,"end":665.92,"wordCount":22},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"By the way, what’s it like working in a restaurant?","start":666.11,"end":669.82,"wordCount":10},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you think we should invite some others to come along?","start":681.02,"end":683.86,"wordCount":11},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"I haven’t been abroad for a long while.","start":688.46,"end":691.16,"wordCount":8},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"And it would be great to go somewhere by the sea.","start":691.16,"end":694.01,"wordCount":11},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"And, if Tom goes, we could go sailing.","start":695.92,"end":699.63,"wordCount":8},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"He has a lot of experience with boats.","start":699.63,"end":702.22,"wordCount":8},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"And it’ll work out a lot cheaper to hire one if there’s more of us to share the cost.","start":702.23,"end":707.61,"wordCount":19},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"However, few people know that she was also the mother of a Nobel Prize winner.","start":849.84,"end":855.86,"wordCount":15},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"After the war she received a Military Medal for her work.","start":897.21,"end":901.7,"wordCount":11},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"In 1918, Irene became her mother’s assistant at the Curie Institute.","start":902.87,"end":908.52,"wordCount":11},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"Their daughter was born in 1927 and their son in 1932.","start":931.48,"end":936.77,"wordCount":11},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"Like her mother, Irene combined family with career.","start":937.73,"end":941.86,"wordCount":8},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"They sailed around it until they reached the western side.","start":1088.7,"end":1092.58,"wordCount":10},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Then, in 1001, the Vikings made their most important discovery.","start":1098.94,"end":1105.41,"wordCount":10},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"He sailed west and soon found it.","start":1114.36,"end":1117.31,"wordCount":7},{"id":"g7-s16","groupIndex":6,"groupLabel":"Passage 2","answer":"He and his men landed in three places.","start":1117.63,"end":1121.0,"wordCount":8},{"id":"g7-s18","groupIndex":6,"groupLabel":"Passage 2","answer":"The Vikings then sailed south and made their second landing.","start":1127.55,"end":1131.77,"wordCount":10},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"Things haven’t turned out exactly as I imagined.","start":1261.09,"end":1263.92,"wordCount":8},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"But I wouldn’t change what I have now for that imaginary world.","start":1264.5,"end":1267.85,"wordCount":12},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"In my third year of university, I realized that I didn’t want to become a lawyer.","start":1274.57,"end":1279.17,"wordCount":16},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"I chose to become a language teacher.","start":1280.66,"end":1282.9,"wordCount":7},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"I did get married, but had more than two children.","start":1283.49,"end":1287.27,"wordCount":10},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"Do I live in the dream house with wooden floors?","start":1289.71,"end":1292.2,"wordCount":10},{"id":"g8-s18","groupIndex":7,"groupLabel":"Passage 3","answer":"But I love my home and I wouldn’t want to live in any other place.","start":1294.44,"end":1298.6,"wordCount":15},{"id":"g8-s19","groupIndex":7,"groupLabel":"Passage 3","answer":"I believe that as a young person, it’s important to dream and make plans.","start":1299.33,"end":1304.26,"wordCount":14},{"id":"g8-s20","groupIndex":7,"groupLabel":"Passage 3","answer":"However, it’s also important to realize that not all of your plans will turn out exactly as you wish.","start":1304.62,"end":1311.89,"wordCount":19}],"manualOnly":false},"2018-06-set1":{"clips":[{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"She held up to her father’s promise, giving Buffington that reward.","start":100.93,"end":105.96,"wordCount":11},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"But the biggest reward is the message in a bottle finding its way back home.","start":106.21,"end":111.21,"wordCount":15},{"id":"g2-s1","groupIndex":1,"groupLabel":"News Report 2","answer":"Millions of bees have died in South Carolina during aerial insect spraying operations that were carried out to combat the Zika virus.","start":159.29,"end":169.29,"wordCount":22},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"Juanita Stanley who owns the company said the farm “looks like it's been destroyed.”","start":192.66,"end":198.93,"wordCount":14},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"County manager Jason Ward said in a statement.","start":218.29,"end":221.72,"wordCount":8},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"“I’m not pleased that so many bees were killed.”","start":222.02,"end":225.3,"wordCount":9},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The aircraft cost 25 million pounds and can carry heavier loads than huge jet planes while also producing less noise and emitting less pollution.","start":318.95,"end":330.73,"wordCount":24},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"The makers believe it’s the future of aircraft and one day we’ll be using them to go places.","start":331.47,"end":338.92,"wordCount":18},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"But there’s still a long way to go.","start":339.35,"end":342.07,"wordCount":8},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"If it passes though, we can hope we’ll all get some extra legroom.","start":351.5,"end":356.85,"wordCount":13},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"I think it’s about how climate change affects everyday life.","start":481.86,"end":485.79,"wordCount":10},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"I wonder how they make it entertaining.","start":485.98,"end":488.2,"wordCount":7},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"It’s an important subject, I agree, but I’m not in the mood for anything depressing.","start":490.7,"end":496.42,"wordCount":15},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"Let’s see what it says in the paper.","start":506.42,"end":508.68,"wordCount":8},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"We haven’t got enough time to get there.","start":521.11,"end":523.5,"wordCount":8},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"It’s a charity comedy night with lots of different acts.","start":530.77,"end":534.23,"wordCount":10},{"id":"g4-s32","groupIndex":3,"groupLabel":"Conversation 1","answer":"It says here “Roger Whitehead is an amazing host to a night of fun performances.”","start":540.56,"end":546.7,"wordCount":15},{"id":"g4-s40","groupIndex":3,"groupLabel":"Conversation 1","answer":"Great, I’ll book the tickets online.","start":562.92,"end":565.57,"wordCount":6},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"It’s completely normal for you to be nervous about transferring schools.","start":667.72,"end":671.82,"wordCount":11},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"This happens to many transfer students.","start":671.98,"end":674.66,"wordCount":6},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, you may be the only younger one in your year, but, you know, we have a lot of after-school activities you can join in.","start":681.65,"end":691.05,"wordCount":26},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"I love games and hobby groups.","start":697.7,"end":699.97,"wordCount":6},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"Don’t worry so much and try to make the most of what we have on offer here.","start":703.19,"end":708.25,"wordCount":17},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"All students are very friendly with new arrivals.","start":734.63,"end":737.89,"wordCount":8},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"Bree is also a new student here, like you.","start":745.31,"end":748.59,"wordCount":9},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’m sure you two will have more to share with each other.","start":748.59,"end":751.69,"wordCount":12},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Have you ever felt like you would do just about anything to satisfy your hunger?","start":870.78,"end":876.11,"wordCount":15},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"A new study in mice may help to explain why hunger can feel like such a powerful motivating force.","start":876.49,"end":884.17,"wordCount":19},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"In the study, researchers found that hunger outweighed other physical drives, including fear, thirst and social needs.","start":884.7,"end":894.17,"wordCount":17},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"To determine which feeling won out, the researchers did a series of experiments.","start":894.79,"end":900.95,"wordCount":13},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"In one experiment, the mice were both hungry and thirsty.","start":901.12,"end":905.36,"wordCount":10},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"When given the choice of either eating food or drinking water, the mice went for the food, the researchers found.","start":905.36,"end":912.38,"wordCount":20},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"However, when the mice were well-fed but thirsty, they opted to drink, according to the study.","start":913.06,"end":920.07,"wordCount":17},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"It turned out that, when the mice were hungry, they ventured into the unsafe areas for food.","start":940.58,"end":947.04,"wordCount":17},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"But when the mice were well-fed, they stayed in areas of the cage that were considered “safe.”","start":947.13,"end":953.56,"wordCount":18},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"Hunger also outweighed the mice’s social needs, the researchers found.","start":954.29,"end":959.52,"wordCount":10},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"It could also get people out of cities in danger of being bombed.","start":1086.47,"end":1091.0,"wordCount":13},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"So-called roads of national importance were designated, but they were mostly small country roads.","start":1091.29,"end":1099.12,"wordCount":15},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"In 1944, Congress passed a bill to upgrade the system, but did not fund the plan right away.","start":1099.61,"end":1107.15,"wordCount":18},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"The idea was to connect the new system to existing expressways and freeways.","start":1123.53,"end":1129.39,"wordCount":13},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"For instance, highway overpasses had to be high enough to allow trailers carrying military missiles to pass under them.","start":1136.65,"end":1146.23,"wordCount":19},{"id":"g7-s16","groupIndex":6,"groupLabel":"Passage 2","answer":"A few additional roads would come later.","start":1151.25,"end":1154.31,"wordCount":7},{"id":"g7-s17","groupIndex":6,"groupLabel":"Passage 2","answer":"Quick and easy travel between all parts of the country was now possible.","start":1154.69,"end":1159.9,"wordCount":13},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"It also watches for what’s called “close by hands”, where both hands are close together near the top of the wheel, so the driver can type with both thumbs and drive at the same time.","start":1298.36,"end":1311.88,"wordCount":35},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"If they try to remove or damage the cover, that’s reported as well.","start":1324.87,"end":1330.42,"wordCount":13}],"manualOnly":false},"2018-06-set2":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"But the woman says the snake she encountered Thursday terrified her out of her wits.","start":60.86,"end":66.67,"wordCount":15},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"“I don’t know whether I had my hands on the steering wheel or not.","start":75.38,"end":79.54,"wordCount":14},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"I am not the most flexible person in the world, but I can guarantee my knees were up next to my ears.”","start":79.74,"end":87.2,"wordCount":22},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"“That didn’t work out,” she said.","start":96.81,"end":99.14,"wordCount":6},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"“Here he comes, and he wound up in my back seat before I could finally get off the road, stop and get out of the car.”","start":99.22,"end":107.36,"wordCount":26},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"Among the reasons for the slower service, today there are more choices on the menu, and the products themselves are more complex and take longer to prepare.","start":209.69,"end":220.34,"wordCount":27},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Speed, of course, is essential to the drive-through experience.","start":220.54,"end":224.81,"wordCount":10},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"Actually, I’m on holiday with my family in Thailand at the moment, although I wish it were with my friends instead.","start":488.76,"end":496.5,"wordCount":21},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"What else have you been doing in Thailand besides enjoying the sun?","start":523.47,"end":527.43,"wordCount":12},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"What other equipment do they have?","start":732.64,"end":734.82,"wordCount":6},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"You could use any of these to suit your purpose.","start":749.76,"end":753.3,"wordCount":10},{"id":"g5-s30","groupIndex":4,"groupLabel":"Conversation 2","answer":"What are the speakers talking about?","start":770.99,"end":773.48,"wordCount":6},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Accordingly, managing your job search properly is just as important as identifying job opportunities and submitting your applications.","start":909.87,"end":919.45,"wordCount":18},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"If Excel isn’t quite your cup of tea，don’t worry, you can create a table in Microsoft Word or a similar word processor.","start":931.33,"end":940.95,"wordCount":23},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"You can also link up with Google calendar to make sure you stay on top of important dates.","start":957.29,"end":964.09,"wordCount":18},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"Nevertheless, you should always focus on quality, not quantity.","start":974.13,"end":979.75,"wordCount":9},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"My reply is “No, they wouldn’t.”","start":1065.79,"end":1068.97,"wordCount":6},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"My older students say it makes them feel young.","start":1279.46,"end":1283.24,"wordCount":9},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"For many of them, it’s a way of meeting people and having a social life.","start":1285.54,"end":1290.43,"wordCount":15},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"I can tell you about one young couple，” says Bridges.","start":1293.18,"end":1296.99,"wordCount":10},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"“They arrive at the class in a bad mood, and they leave with a smile.","start":1297.15,"end":1302.11,"wordCount":15},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Even after all these years, I want to get better and better.","start":1321.33,"end":1325.92,"wordCount":12},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"I keep practicing even when I’m exhausted.","start":1326.13,"end":1329.83,"wordCount":7},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"I find it hard to stop.","start":1330.13,"end":1332.36,"wordCount":6}],"manualOnly":false},"2018-12-set1":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"The lunar network will support high-definition streaming of video and data between the moon and Earth.","start":63.06,"end":69.51,"wordCount":17},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"The network is part of Mission to the Moon.","start":70.35,"end":73.28,"wordCount":9},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"This is a project with the goal of landing the first privately paid for mission to the moon.","start":73.97,"end":79.81,"wordCount":18},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Mission to the Moon intends to establish and test the first elements of a communications network on the moon.","start":91.2,"end":98.83,"wordCount":19},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"This means that a 5G network may not yet be stable enough to work on the moon's surface.","start":115.23,"end":121.6,"wordCount":18},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"Six fire engines, two trucks and two chiefs responded to the scene.","start":183.83,"end":189.28,"wordCount":12},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"There were some people inside the building when the fire broke out, but there were no reports of any injuries.","start":198.05,"end":204.66,"wordCount":20},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Fire investigators have responded to the scene but have not yet determined the cause of the fire.","start":205.33,"end":211.99,"wordCount":17},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"Firefighters will remain on the scene until later this morning to ensure that the fire doesn't start up again.","start":212.4,"end":219.88,"wordCount":19},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"In 2014, City Hall developed a plan to knock down the building and replace it with affordable housing.","start":225.2,"end":232.84,"wordCount":18},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"However, the plan was dropped due to lack of funds.","start":233.08,"end":236.54,"wordCount":10},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"“We don’t know when we’ll be able to restart,” a company spokesman said.","start":313.35,"end":317.79,"wordCount":13},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"Japanese laws limit the amount of imported potatoes that can be used in Japanese-made products.","start":323.98,"end":330.76,"wordCount":16},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"Japan says fear of disease is its main reason to block fresh imports.","start":331.54,"end":336.98,"wordCount":13},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"It still only allows potatoes from selected US states.","start":337.87,"end":342.38,"wordCount":9},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"This is only at certain times and on condition that they are processed at factories based near Japanese ports.","start":343.25,"end":350.61,"wordCount":19},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"But global warming has raised the possibility that domestic produce could be seriously affected by rare weather events more often.","start":351.39,"end":360.46,"wordCount":20},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"How do you stay focused through the entire hour?","start":483.47,"end":486.26,"wordCount":9},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, what I do is keep my pen moving.","start":486.35,"end":489.84,"wordCount":9},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's a method of active concentration I read about.","start":490.97,"end":494.44,"wordCount":9},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"One of the most effective ways to concentrate is to write things down.","start":494.55,"end":499.45,"wordCount":13},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"But it has to be done by hand, not typing on a keyboard.","start":499.76,"end":504.02,"wordCount":13},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"Do you review your notes afterwards then?","start":511.9,"end":514.67,"wordCount":7},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"My notes may or may not be useful.","start":517.72,"end":520.71,"wordCount":8},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"In fact, sometimes I draw a little too.","start":527.94,"end":531.39,"wordCount":8},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"And that helps you pay attention?","start":533.99,"end":535.91,"wordCount":6},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, honestly, it works for me.","start":535.91,"end":538.88,"wordCount":6},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"I just draw little lines and nonsense really.","start":538.88,"end":542.91,"wordCount":8},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"It was also in that article I read.","start":542.91,"end":545.92,"wordCount":8},{"id":"g4-s26","groupIndex":3,"groupLabel":"Conversation 1","answer":"It can keep the mind active, prevent getting bored and help to concentrate.","start":545.92,"end":551.87,"wordCount":13},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"Again, the point is to listen hard while keeping the pen moving.","start":551.89,"end":556.85,"wordCount":12},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"If I'm at home and I need to study, what I do is read out loud.","start":557.01,"end":562.09,"wordCount":16},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"It has a similar effect to writing by hand.","start":562.24,"end":565.5,"wordCount":9},{"id":"g4-s30","groupIndex":3,"groupLabel":"Conversation 1","answer":"It helps memorize information in a physical way.","start":565.5,"end":569.46,"wordCount":8},{"id":"g5-s2","groupIndex":4,"groupLabel":"Conversation 2","answer":"These photos are from the Taj Mahal in India.","start":658.78,"end":663.2,"wordCount":9},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yeah, the Taj Mahal was a very romantic place.","start":667.88,"end":671.66,"wordCount":9},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"The guide told us there is a famous love story behind this building that all Indians learn in school.","start":671.66,"end":678.6,"wordCount":19},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"I think it was during the 1600s and the princess at that time died while giving birth to her 14th child.","start":678.61,"end":686.6,"wordCount":21},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"The building is very tall and there are gardens and a wall around it all.","start":705.78,"end":710.77,"wordCount":15},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"It's all built in this white stone.","start":711.15,"end":714.06,"wordCount":7},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"And some walls of the building are decorated with jewels.","start":714.06,"end":717.76,"wordCount":10},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"It must have been very crowded when you were there.","start":717.83,"end":720.71,"wordCount":10},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"Was the rest of India crowded?","start":726.95,"end":729.0,"wordCount":6},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yes, very crowded in many cities.","start":729.0,"end":732.29,"wordCount":6},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"It was sometimes so crowded that it was difficult to walk along the streets, especially through busy markets.","start":732.29,"end":739.23,"wordCount":18},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"And there are so many cars.","start":739.44,"end":741.64,"wordCount":6},{"id":"g5-s27","groupIndex":4,"groupLabel":"Conversation 2","answer":"And we had a great time.","start":746.95,"end":748.72,"wordCount":6},{"id":"g5-s30","groupIndex":4,"groupLabel":"Conversation 2","answer":"There are lots of different dishes to try, and every region has its own special food.","start":752.2,"end":757.36,"wordCount":16},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"And \\(66\\%\\) say the closing of their local public library would have a major impact on their community although notably, just 33% say this would have a major impact on them personally or on their family.","start":900.46,"end":916.95,"wordCount":36},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"A majority of Americans feel libraries are doing a good job of providing a safe place for people to hang out or spend time as well as opening up educational opportunities for people of all ages.","start":917.56,"end":932.12,"wordCount":36},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"And roughly half think their libraries contribute “a lot” to their communities in terms of helping spark creativity among young people and providing a trusted place for people to learn about new technologies.","start":932.12,"end":946.13,"wordCount":33},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Some 48% of adults specifically visited a library in the past 12 months, a modest increase from the 44% who said that in late 2015.","start":974.44,"end":986.96,"wordCount":25},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"They have a spotted coat similar to that of many types of wild cats and their ears are very large.","start":1093.15,"end":1100.08,"wordCount":20},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"They are also commonly compared to dogs in their loyalty, and can be trained to walk on a lead and to fetch.","start":1100.63,"end":1107.84,"wordCount":22},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"An often-noted characteristic of the Savannah is its jumping ability.","start":1108.56,"end":1113.5,"wordCount":11},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"They are known to jump on top of doors and high cabinets.","start":1114.01,"end":1117.53,"wordCount":12},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"They often learn how to open doors and cupboards.","start":1129.89,"end":1133.0,"wordCount":9},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"Many Savannah cats do not fear water and will play with or even dive into water.","start":1133.88,"end":1140.05,"wordCount":16},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"Some owners even shower with their Savannah cats.","start":1140.73,"end":1143.99,"wordCount":8},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"During your child's first year in school, much time will be spent in learning to read and they need to know that this is fun and worthwhile.","start":1264.52,"end":1274.26,"wordCount":27},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"Your child will naturally copy you, so it is important that you are seen reading and enjoying books, newspapers and magazines rather than just absorbed in screens.","start":1274.46,"end":1287.5,"wordCount":27},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"Ultimately, an excellent education should be a close partnership between parents and teachers.","start":1287.83,"end":1294.88,"wordCount":13},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Irrespective of the quality of a school, a child's home life is of key importance.","start":1306.08,"end":1312.19,"wordCount":15},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"It is the determining factor of their academic success.","start":1312.42,"end":1316.52,"wordCount":9}],"manualOnly":false},"2018-12-set2":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"A man described as a “non-worker civilian” was buried up to his waist in the basement.","start":62.92,"end":68.82,"wordCount":17},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"The man was collecting building materials when the first floor collapsed underneath him.","start":69.13,"end":74.28,"wordCount":13},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"He was trapped under a beam about 10 feet below the surface for nearly an hour and a half.","start":74.59,"end":80.56,"wordCount":19},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"The man was then taken to hospital.","start":81.03,"end":83.48,"wordCount":7},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"Officials said he is in stable condition with non-life-threatening injuries.","start":83.83,"end":89.0,"wordCount":12},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"The building was reportedly purchased by a neighboring church in 2011.","start":89.46,"end":94.45,"wordCount":11},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"It was the site of a 2006 fire and has remained vacant ever since.","start":94.75,"end":100.12,"wordCount":14},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"He will now retrain to fly the bigger Boeing 737s as the old planes are being phased out of service.","start":305.98,"end":313.83,"wordCount":20},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"The 50-year-old father of three and king to 17 million Dutch citizens calls flying a “hobby.”","start":314.11,"end":321.78,"wordCount":18},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"It lets him leave his royal duties on the ground and fully focus on something else.","start":322.2,"end":327.77,"wordCount":16},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"“You have an aircraft, passengers and crew.","start":328.16,"end":331.38,"wordCount":7},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"You have responsibility for them,” the king said.","start":331.62,"end":334.62,"wordCount":8},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"“You can’t take your problems from the ground into the skies.","start":335.07,"end":338.52,"wordCount":11},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"You can completely change focus and concentrate on something else.","start":338.99,"end":343.43,"wordCount":10},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"That, for me, is the most relaxing part of flying.”","start":343.79,"end":347.44,"wordCount":10},{"id":"g3-s13","groupIndex":2,"groupLabel":"News Report 3","answer":"Very few people pay attention to him as he walks through the airport in his airline uniform and cap.","start":352.9,"end":359.21,"wordCount":19},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"There was a great need for furniture and my grandparents saw a business opportunity.","start":483.13,"end":488.69,"wordCount":14},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"Their aim was to provide quality yet affordable wooden furniture.","start":488.87,"end":493.78,"wordCount":10},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"And this goal has never changed.","start":493.8,"end":496.19,"wordCount":6},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"Do you still only work with wood?","start":496.32,"end":498.64,"wordCount":7},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's what we know and what we do best.","start":500.11,"end":502.94,"wordCount":9},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"If we started trying different materials, our quality would probably suffer.","start":503.03,"end":508.44,"wordCount":11},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"And all the wood is local?","start":508.69,"end":510.72,"wordCount":6},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"Could you please outline how the company has grown over time?","start":516.16,"end":520.1,"wordCount":11},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"What have been the main challenges and opportunities that you have faced?","start":520.27,"end":524.71,"wordCount":12},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, back in the '50s and '60s, Romania was a lot poorer than it is today.","start":525.06,"end":531.57,"wordCount":16},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"My grandfather and father did not have much capital, and our customers didn't have much money either.","start":531.63,"end":539.1,"wordCount":17},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"The big change was in 2007 when Romania joined the European Union.","start":541.65,"end":547.43,"wordCount":12},{"id":"g4-s26","groupIndex":3,"groupLabel":"Conversation 1","answer":"Suddenly, our market exploded in size and we could now sell our products all across the continent.","start":547.83,"end":555.36,"wordCount":17},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"There was also more financial investment.","start":555.79,"end":558.72,"wordCount":6},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"And, as a result, we went from having 20 employees to 200.","start":558.72,"end":563.91,"wordCount":12},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"Which countries are your biggest market?","start":564.43,"end":566.74,"wordCount":6},{"id":"g4-s30","groupIndex":3,"groupLabel":"Conversation 1","answer":"Besides Romania, our biggest market is Germany.","start":567.04,"end":570.61,"wordCount":7},{"id":"g4-s31","groupIndex":3,"groupLabel":"Conversation 1","answer":"There is strong demand there for our traditional style of furniture.","start":570.64,"end":575.26,"wordCount":11},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"Susan and I go to at least three different places during the event.","start":734.67,"end":738.91,"wordCount":13},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"It's a great opportunity to try some of the more expensive restaurants at a discounted price and try something new.","start":739.58,"end":746.92,"wordCount":20},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"That's how we found the Pearl, actually.","start":747.15,"end":749.74,"wordCount":7},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"Wow, that's an event I would be interested in.","start":749.74,"end":753.0,"wordCount":9},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"When will it be happening this year?","start":753.06,"end":755.24,"wordCount":7},{"id":"g5-s28","groupIndex":4,"groupLabel":"Conversation 2","answer":"Restaurant Week starts in just a few days, the first Sunday in May.","start":756.46,"end":760.77,"wordCount":13},{"id":"g5-s30","groupIndex":4,"groupLabel":"Conversation 2","answer":"Just let me know what type of food you would like to try.","start":764.29,"end":767.22,"wordCount":13},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"All parents know it is difficult to get children to eat their vegetables.","start":891.71,"end":896.36,"wordCount":13},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"Some of them offer rewards or treats for children finishing their share.","start":896.37,"end":901.22,"wordCount":12},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"But researchers have discovered that youngsters who are not praised for trying vegetables are more likely to eat them eventually.","start":901.8,"end":909.71,"wordCount":20},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"The study found that the best way to get children to eat food they do not like is simply to give them repeated exposure to it.","start":910.15,"end":918.57,"wordCount":26},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"They gave them five kinds of vegetables to eat—mushrooms, peas, eggplants, carrots and cabbages.","start":924.31,"end":931.88,"wordCount":15},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"The taste tests revealed that carrots were the least-liked vegetable among youngsters.","start":932.21,"end":938.18,"wordCount":13},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"The children were then given a bowl of boiled carrots and told to choose how much to eat.","start":938.36,"end":944.12,"wordCount":18},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"Children were split into three groups, with one group asked to try the bowl of carrots repeatedly with no further encouragement.","start":957.77,"end":966.4,"wordCount":21},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"The other two groups were given rewards of a toy or verbal praise.","start":966.79,"end":971.39,"wordCount":13},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"But how much garbage exactly have humans left on the moon?","start":1066.58,"end":1070.64,"wordCount":11},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"Much of it was left by American astronauts who landed on the lunar surface between 1969 and 1972 during NASA's Apollo missions.","start":1079.16,"end":1090.24,"wordCount":22},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"The other rubbish comes from missions that did not have human crews.","start":1090.86,"end":1095.1,"wordCount":12},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"The equipment stayed there after its missions ended.","start":1110.91,"end":1113.94,"wordCount":8},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"The moon is also home to lunar orbiters that mapped the moon before they crashed into its surface, adding to the garbage heap.","start":1114.5,"end":1123.07,"wordCount":23},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"The objects left by the Apollo astronauts included equipment that was no longer needed.","start":1123.6,"end":1129.41,"wordCount":14},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"Bringing back unneeded equipment would have used up precious resources such as fuel.","start":1129.68,"end":1135.58,"wordCount":13},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"But, as the saying goes, one person's trash is another's treasure.","start":1135.82,"end":1140.63,"wordCount":11},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Researchers can study the garbage left on the moon to see how its materials weathered the radiation and vacuum of space over time.","start":1140.78,"end":1149.39,"wordCount":23},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"Moreover, some of the objects on the moon are still being used, including a laser-range reflector left by the Apollo 11 crew.","start":1149.61,"end":1158.67,"wordCount":23},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"As most of you will soon be entering the workforce, I would like to share with you my own rules for emailing.","start":1255.74,"end":1263.86,"wordCount":22},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"If someone sends you an email, reply to them acknowledging the email.","start":1264.39,"end":1269.66,"wordCount":12},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"A simple \"thank you\" let the sender know that their email has arrived safely, that it has not been lost among what could be 50 other emails that have arrived in your email inbox that day.","start":1269.66,"end":1283.33,"wordCount":36},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"It's not necessary to reply to a mass email sent to numerous recipients.","start":1283.43,"end":1288.94,"wordCount":13},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"It's also important to use proper English.","start":1306.23,"end":1309.47,"wordCount":7},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Just because emails are a quick form of communication, doesn't mean emails, especially business emails, should be written using informal shortened forms of words.","start":1309.86,"end":1322.21,"wordCount":24},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Think of an email as a letter.","start":1322.46,"end":1324.7,"wordCount":7},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"And never use capitals to emphasize a word or words in an email.","start":1329.41,"end":1334.51,"wordCount":13}],"manualOnly":false},"2019-06-set1":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"James said that waves in the San Francisco Bay hitting him in the face 30 minutes into his swim made him want to give up.","start":80.43,"end":89.81,"wordCount":25},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"James pushed forward, making it to Alcatraz Island and back in a little more than two hours.","start":101.42,"end":108.49,"wordCount":17},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Alcatraz is over a mile from the mainland.","start":108.98,"end":112.53,"wordCount":8},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"What did the boy from Central California do according to the report?","start":120.47,"end":125.84,"wordCount":12},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"The holiday bonus was designed to encourage young people to delay getting married in line with China's one-child policy.","start":178.55,"end":187.1,"wordCount":20},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"But with that policy now being abolished, this holiday incentive is no longer necessary, the government says.","start":187.95,"end":195.54,"wordCount":17},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"In Shanghai, a young couple at a marriage registration office told the paper that they decided to register their marriage as soon as possible to take advantage of the existing policy, because an extra holiday was a big deal for them.","start":196.39,"end":213.6,"wordCount":41},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"But one lawyer tells the paper that the changes still have to be adopted by local governments and these procedures take time.","start":229.28,"end":238.61,"wordCount":22},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"So people who are rushing to register for marriage can relax.","start":238.99,"end":243.67,"wordCount":11},{"id":"g3-s1","groupIndex":2,"groupLabel":"News Report 3","answer":"Everyone loves a good house party, but the cleaning-up the next morning isn't as enjoyable.","start":290.79,"end":297.44,"wordCount":16},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"Although they are both gainfully employed, they fit cleaning jobs into their nights and weekends, which is when their service is in most demand anyway.","start":329.32,"end":339.36,"wordCount":25},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"⑺They are reportedly meeting with lawyers to see how best to take the business forward.","start":353.05,"end":359.0,"wordCount":15},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"Then, after the exam, they printed out my result, but I was afraid to open it until I was outside.","start":484.07,"end":491.66,"wordCount":20},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"It was such a relief to pass.","start":492.04,"end":494.46,"wordCount":7},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"Now, all you have to do next is your road test.","start":514.66,"end":518.39,"wordCount":11},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"Have you had any lessons yet?","start":518.46,"end":520.42,"wordCount":6},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm so happy to be actually on the road now.","start":522.84,"end":526.11,"wordCount":10},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"It's just a bit more than the local students.","start":664.14,"end":667.08,"wordCount":9},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"Also, I have a good chance of winning a scholarship at Leeds, which would be pretty awesome, the benefits of being a music genius.","start":688.86,"end":698.41,"wordCount":24},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"So you're doing a postgraduate degree now?","start":702.02,"end":705.6,"wordCount":7},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm still in my last year, graduating next June.","start":705.73,"end":709.68,"wordCount":9},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"No money in that job then.","start":719.2,"end":721.26,"wordCount":6},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm still going to be a teacher.","start":723.04,"end":725.24,"wordCount":7},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Scientists have identified thousands of known ant species around the world—and only a few of them bug humans.","start":862.09,"end":872.2,"wordCount":19},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"Most ants live in the woods or out in nature.","start":872.62,"end":876.31,"wordCount":10},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"A very small percentage of ants do harm to humans.","start":886.14,"end":890.77,"wordCount":10},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"But those are incredibly challenging to control.","start":891.13,"end":894.55,"wordCount":7},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"They are small enough to easily slip inside your house, live in colonies that number in the tens of thousands to the hundreds of thousands, and reproduce quickly.","start":894.78,"end":906.93,"wordCount":28},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"That makes them good at getting in, and hard to kick out.","start":907.65,"end":912.29,"wordCount":12},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Once they settle in, these insects start affecting your home.","start":912.74,"end":917.63,"wordCount":10},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"In addition to biting ants, other species can cause different kinds of damage.","start":918.01,"end":923.84,"wordCount":13},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"So how can we prevent ants from getting into our homes?","start":946.49,"end":950.4,"wordCount":11},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"Most important of all, avoid giving ants any access to food, particularly sugary food, because ants have a sweet tooth.","start":951.05,"end":961.54,"wordCount":20},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"We also need to clean up spills as soon as they occur and store food in airtight containers.","start":961.98,"end":969.33,"wordCount":18},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"Even garbage attracts ants, so empty your trash as often as possible, and store your outside garbage in a lidded can, well away from doors and windows.","start":969.67,"end":982.48,"wordCount":27},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"In most of our work when we're looking at older adults who've got an illness, we always have to have health controls.","start":1080.31,"end":1088.06,"wordCount":22},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"They come to the university to provide us with blood samples, to be interviewed and to help us carry out a whole range of research.","start":1100.69,"end":1109.22,"wordCount":25},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"The real impact of our research is going to be on health in old age.","start":1110.23,"end":1115.15,"wordCount":15},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"That means an extra five hours a day.","start":1124.09,"end":1127.39,"wordCount":8},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"I want to make sure that older adults are still able to enjoy their old age and that they're not spending time in hospital with infections, feeling unwell and being generally weak.","start":1128.26,"end":1140.88,"wordCount":32},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"We want people to be healthy even when they are old.","start":1141.48,"end":1145.78,"wordCount":11},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"The competition only happens every four years and the last time the team went, they won the third place in the nation.","start":1265.44,"end":1273.81,"wordCount":22},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"The school has the highest number of kids from low-income families.","start":1280.1,"end":1284.9,"wordCount":12},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Police frequent the area day and night, as two months ago, a young man was shot just down the street.","start":1285.07,"end":1292.93,"wordCount":20},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"The lessons prove valuable outside the classroom as well.","start":1299.94,"end":1303.95,"wordCount":9},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Many parents see these lessons translate into the real world.","start":1304.53,"end":1308.75,"wordCount":10},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"Students are more likely to think about their actions and see whether they will lead to trouble.","start":1309.36,"end":1315.71,"wordCount":17}],"manualOnly":false},"2019-06-set2":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"The terror attacks in Paris last November were called Europe's worst in the past decade.","start":66.33,"end":72.83,"wordCount":15},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"Besides violence, workers' strikes and heavy floods are said to have also been why international tourists have stayed away.","start":73.48,"end":82.71,"wordCount":19},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"So far in the Paris region, there's been a 46% decline in Japanese visitors, 35% fewer Russians and 27% fewer Italians.","start":83.65,"end":96.41,"wordCount":21},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Their numbers have only dropped by roughly 5%.","start":100.78,"end":104.49,"wordCount":8},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"The sector represents roughly 9% of its GDP.","start":116.71,"end":121.22,"wordCount":8},{"id":"g2-s1","groupIndex":1,"groupLabel":"News Report 2","answer":"A small plane with two sick US workers arrived safely in Chile late Wednesday after leaving Antarctica in a daring rescue mission from a remote South Pole research station.","start":178.1,"end":191.73,"wordCount":29},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"“Antarctica creates a hostile environment,” says the operations director for the British Antarctic Survey.","start":241.88,"end":248.83,"wordCount":14},{"id":"g3-s1","groupIndex":2,"groupLabel":"News Report 3","answer":"A pilot from Virginia removed his son’s loose tooth using a helicopter.","start":301.04,"end":306.43,"wordCount":12},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"The father of four posted a video clip of his playful venture on Facebook, advising parents to do fun and creative stuff with their kids.","start":329.58,"end":339.47,"wordCount":25},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The video shows him launching the helicopter into the air and flying just far enough to successfully remove the loose tooth.","start":340.54,"end":349.09,"wordCount":21},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"“You’ve got to do everything safe in life, and that’s what I did today,” he said.","start":363.42,"end":368.34,"wordCount":16},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"Are you at home to collect it?","start":493.27,"end":495.08,"wordCount":7},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"Can you put it in my mailbox?","start":498.51,"end":500.71,"wordCount":7},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’m afraid I can’t do that.","start":500.72,"end":502.87,"wordCount":6},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"Okay, well, I’m out all day today, but I should be in tomorrow morning before I go out for lunch.","start":513.01,"end":520.21,"wordCount":20},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"And then I’ll be at home again later in the afternoon.","start":520.21,"end":524.05,"wordCount":11},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"Will either of those times be convenient for you?","start":524.21,"end":527.69,"wordCount":9},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"I won’t be in the area tomorrow as I have some other deliveries to make on the other side of town.","start":531.58,"end":537.51,"wordCount":21},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"I could come the day after if that suits you.","start":537.69,"end":540.93,"wordCount":10},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"Do I need to pay for the package?","start":551.22,"end":553.61,"wordCount":8},{"id":"g4-s26","groupIndex":3,"groupLabel":"Conversation 1","answer":"It says here that you paid for it when you ordered it online.","start":554.72,"end":558.37,"wordCount":13},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"So you just need to sign the form to say you’ve received it.","start":561.64,"end":565.22,"wordCount":13},{"id":"g5-s3","groupIndex":4,"groupLabel":"Conversation 2","answer":"It’d be really nice for us to hang out together before you go.","start":661.09,"end":665.09,"wordCount":13},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’m leaving in just two more days, and I’m going to miss all my friends here and especially this place.","start":666.89,"end":674.01,"wordCount":20},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"I need to get this assignment finished by Monday, and I’m way behind.","start":690.61,"end":695.34,"wordCount":13},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"You’re not leaving for good, and you’ll absolutely love Italy.","start":697.69,"end":702.32,"wordCount":10},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"But I just feel like I’m not quite ready to go.","start":704.09,"end":707.4,"wordCount":11},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"And studying in a foreign country seems a bit overwhelming.","start":707.4,"end":711.79,"wordCount":10},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Just think of your life in Milan.","start":712.21,"end":714.69,"wordCount":7},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"In the mornings, you can go down to a small local cafe, soaking up the sun’s rays and drinking coffee.","start":714.8,"end":722.34,"wordCount":20},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"You can buy lots of gorgeous Italian clothes.","start":724.52,"end":727.62,"wordCount":8},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"And of course I can keep in touch with everyone through Facebook.","start":729.62,"end":734.01,"wordCount":12},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"Maybe you can all come visit me.","start":734.01,"end":736.21,"wordCount":7},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"On Saturday, after lunch, at 1:45.","start":739.66,"end":743.66,"wordCount":7},{"id":"g5-s28","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’ll give you a call that morning no matter what.","start":748.8,"end":751.73,"wordCount":10},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"The mountain has been in a state of near continuous eruption for half a million years.","start":871.41,"end":877.54,"wordCount":16},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Before the eruptions, it was covered by forests of pine trees.","start":884.72,"end":889.18,"wordCount":11},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"Located in southern Italy, Etna is the highest active volcano in Europe.","start":889.9,"end":895.61,"wordCount":12},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"However, its height often changes when volcanic material accumulates during eruptions and subsequently collapses.","start":895.9,"end":904.63,"wordCount":14},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Some 200 eruptions have been recorded down through the centuries, but compared with other volcanoes, most of its eruptions have so far been fairly light in terms of death and destruction.","start":920.22,"end":934.09,"wordCount":31},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Only about 100 deaths have been attributed to the volcano.","start":934.71,"end":939.51,"wordCount":10},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"Local people have also carved out over 200 caves in the soft rock and used them for everything from sacred burial places to food storage.","start":961.39,"end":973.18,"wordCount":25},{"id":"g7-s1","groupIndex":6,"groupLabel":"Passage 2","answer":"My name is Brendan Leonard and I’m an author, magazine writer, filmmaker and public speaker.","start":1057.9,"end":1065.51,"wordCount":15},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"We have a popular saying in America which goes, “Do what you love and you’ll never work a day in your life.”","start":1072.89,"end":1080.34,"wordCount":22},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"But I’m here to tell you that instead of focusing on doing what we love, I think we should focus on loving what we do.","start":1081.4,"end":1090.38,"wordCount":25},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"In my line of work, you hear a lot about talent, which is an idea we’ve mostly invented to give ourselves an excuse to be lazy.","start":1091.27,"end":1101.13,"wordCount":26},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"Here’s why: If you see someone doing something really well, you would say it’s because they’re talented.","start":1101.89,"end":1109.8,"wordCount":17},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"You discount the tremendous amount of work they’ve done to get to where they are.","start":1112.85,"end":1117.81,"wordCount":15},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"Research has shown that talent is nothing without hard work.","start":1118.9,"end":1123.53,"wordCount":10},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"I choose to believe in hard work, but not so much in talent.","start":1124.31,"end":1129.48,"wordCount":13},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"There are no special people, just people who put in enough hard work until something special happens.","start":1130.1,"end":1137.64,"wordCount":17},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"I can promise you one thing: whatever you choose to do for a career, if you work hard at it, eventually, special things will happen.","start":1138.26,"end":1148.39,"wordCount":25},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"They may not happen as quickly as you’d like them to, and they may turn out to be completely different from the special things you imagined at the beginning, but they will happen.","start":1148.64,"end":1160.47,"wordCount":33},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"Unlike any of these typical responses, I’m proud to say that I love to dance salsa after a long and tiring day of work.","start":1250.96,"end":1260.0,"wordCount":24},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"My dancing life began not because I wanted to do it, but because my mother was sick and tired of seeing me running around after school doing nothing.","start":1267.08,"end":1277.15,"wordCount":28},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"So she enrolled me into a ballet course when I was six.","start":1277.89,"end":1281.81,"wordCount":12},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"I fell in love with it instantly and continued with ballet dancing for about 10 years.","start":1282.25,"end":1288.57,"wordCount":16},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Then I left my native country of New Zealand to start my career as an English teacher, which eventually brought my dancing life to a halt.","start":1288.88,"end":1299.34,"wordCount":26},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Since then I have been trying to attend dancing classes twice a week after work.","start":1309.69,"end":1315.84,"wordCount":15}],"manualOnly":false},"2019-12-set1":{"clips":[{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"An officer then shot an arrow to put it to sleep.","start":93.75,"end":98.07,"wordCount":11},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"Then officers waited for the drug to take effect.","start":98.19,"end":101.89,"wordCount":9},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"After it fell asleep, they loaded the cow into a horse trailer.","start":101.99,"end":107.22,"wordCount":12},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"It was not clear where the cow came from or how it got lost.","start":107.36,"end":112.34,"wordCount":14},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"The fossil hall, which displays some of the world's oldest and largest fossil specimens, receives more than 2 million visitors each year.","start":171.61,"end":181.05,"wordCount":22},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"In the meantime, the current collection will be closed.","start":205.86,"end":209.78,"wordCount":9},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"However, visitors will be compensated during the closure.","start":209.78,"end":214.12,"wordCount":8},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"This week the resident exhibition is a display of ancient wall paintings on loan from Australia.","start":220.21,"end":226.75,"wordCount":16},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"They celebrate the cultural heritage of the country and will be available to view until Sunday.","start":226.87,"end":233.37,"wordCount":16},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"He says visitors are already good at keeping things clean.","start":308.45,"end":313.17,"wordCount":10},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"Instead, he wants to show that nature itself can teach us to take care of the environment.","start":313.33,"end":320.4,"wordCount":17},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"He says that rooks, the chosen birds, are considered to be particularly intelligent.","start":320.61,"end":327.16,"wordCount":13},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"In the right circumstances, they even like to communicate with humans and establish a relationship through play.","start":327.31,"end":335.14,"wordCount":17},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"The birds will be encouraged to clean the park through the use of a small box that delivers a small amount of bird food each time the rook deposits a cigarette end or a small piece of rubbish.","start":335.43,"end":350.07,"wordCount":38},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"So far, visitors to the theme park have been excited to see the birds in action.","start":350.08,"end":356.5,"wordCount":16},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"However, some parents are concerned that it encourages their children to drop litter so they can watch the birds pick it up.","start":356.55,"end":365.59,"wordCount":22},{"id":"g3-s12","groupIndex":2,"groupLabel":"News Report 3","answer":"He maintains most of the feedback he has received has been overwhelmingly positive.","start":369.16,"end":375.54,"wordCount":13},{"id":"g3-s13","groupIndex":2,"groupLabel":"News Report 3","answer":"He hopes now to train more birds.","start":375.77,"end":378.56,"wordCount":7},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"Each episode will focus on a different area of science, and tell us what we know, how we know it, and what we still don't know.","start":489.36,"end":499.74,"wordCount":26},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"Please keep in mind this will be a new TV show like nothing ever done before.","start":533.53,"end":539.58,"wordCount":16},{"id":"g5-s3","groupIndex":4,"groupLabel":"Conversation 2","answer":"I feel like I'm a failure.","start":677.91,"end":680.13,"wordCount":6},{"id":"g5-s4","groupIndex":4,"groupLabel":"Conversation 2","answer":"I can't seem to do anything very well.","start":680.16,"end":683.08,"wordCount":8},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"You do very well in a lot of things.","start":685.0,"end":688.05,"wordCount":9},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"That presentation you gave last week was excellent.","start":688.24,"end":692.07,"wordCount":8},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yes, but I have this urge to strive for perfection.","start":692.33,"end":696.9,"wordCount":10},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"I really want to push harder and progress further.","start":696.9,"end":701.28,"wordCount":9},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"I feel awful whenever I make a mistake in whatever I'm trying to do.","start":713.93,"end":718.77,"wordCount":14},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"You can't make progress without making mistakes and learning from them.","start":720.72,"end":725.99,"wordCount":11},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Thomas Edison, the famous inventor, once said, \"I've not failed.","start":726.21,"end":731.6,"wordCount":10},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've just found 10,000 ways that won't work.\"","start":731.6,"end":735.23,"wordCount":9},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"Also, remember a successful ending is not the only thing worthy of a celebration.","start":743.08,"end":749.54,"wordCount":14},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"You need to recognize each step of progress you take towards achieving your goals, and no matter how tiny it is, it's still good news.","start":749.73,"end":760.18,"wordCount":25},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"I always feel down when I see others accomplishing things, and I feel miserable about my own achievements.","start":760.6,"end":767.77,"wordCount":18},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm always trying to be as good as others.","start":767.87,"end":771.05,"wordCount":9},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"Listen, if you always compare yourself with others, you'll never feel good enough.","start":773.26,"end":779.72,"wordCount":13},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Single-sex education can have enormous benefits for female students.","start":908.96,"end":914.43,"wordCount":10},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"The reason is that all-girls schools encourage women to enter fields traditionally dominated by men, such as science, technology and engineering.","start":938.18,"end":948.61,"wordCount":22},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"So it rains a lot less in Seattle, and the rain is spread out over more days than those cities.","start":1146.47,"end":1153.86,"wordCount":20},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"This is why few locals in Seattle carry an umbrella generally.","start":1153.86,"end":1158.54,"wordCount":11},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"When it does rain, it tends to be a very light rain.","start":1158.54,"end":1162.71,"wordCount":12},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"It almost never really rains as most people think.","start":1164.52,"end":1168.31,"wordCount":9},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"On top of that, it never really storms in Seattle, either.","start":1168.31,"end":1172.72,"wordCount":11},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"Seattle gets an average of a mere seven days a year with thunder.","start":1172.8,"end":1177.6,"wordCount":13},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"So in short, if you like sunny but not too hot summers, mild winters but with lots of cloudy days, Seattle's the place to be.","start":1177.79,"end":1188.57,"wordCount":25},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"Anyway, if you visit Seattle, don't bring an umbrella.","start":1188.58,"end":1193.08,"wordCount":9},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"People will look at you, thinking you're funny.","start":1193.08,"end":1196.64,"wordCount":8},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"After a tough workout or a day full of physical activity, it's common to find your muscles aching.","start":1260.61,"end":1267.72,"wordCount":18},{"id":"g8-s2","groupIndex":7,"groupLabel":"Passage 3","answer":"But where do these pains come from?","start":1267.74,"end":1270.1,"wordCount":7},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"According to a German professor, the soreness comes from straining your muscles in an uncommon way, for example, jumping on a bicycle for a ride, because you haven't ridden in a long time.","start":1270.1,"end":1284.08,"wordCount":33},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"As muscle soreness develops, the body has to work to repair the muscle tears.","start":1299.78,"end":1305.84,"wordCount":14},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Healing can take place after this.","start":1331.64,"end":1334.62,"wordCount":6},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"It takes about a day until these cells make it to your aching muscles.","start":1334.73,"end":1339.9,"wordCount":14},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Repair of damaged cells takes about two days, and afterwards the soreness disappears.","start":1345.66,"end":1352.36,"wordCount":13},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"Pain-relieving creams don't work, but a hot shower or warm bath can provide some relief.","start":1357.78,"end":1366.06,"wordCount":16}],"manualOnly":false},"2019-12-set2":{"clips":[{"id":"g1-s1","groupIndex":0,"groupLabel":"News Report 1","answer":"The British government has called for more men to consider a career in nursing.","start":107.3,"end":113.5,"wordCount":14},{"id":"g1-s2","groupIndex":0,"groupLabel":"News Report 1","answer":"Figures show the number of male nurses has fallen in the last three years.","start":113.59,"end":119.45,"wordCount":14},{"id":"g1-s12","groupIndex":0,"groupLabel":"News Report 1","answer":"We will become the first nation in Europe to publish a national health and care workforce plan.\"","start":180.44,"end":187.64,"wordCount":17},{"id":"g2-s1","groupIndex":1,"groupLabel":"News Report 2","answer":"A man from Libya was enjoying a walk along the sands at Southport Beach.","start":231.63,"end":236.87,"wordCount":14},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"When he was about half a mile out from the dock, he felt a bit tired.","start":237.14,"end":241.71,"wordCount":16},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"So he lay down and fell asleep.","start":241.71,"end":244.24,"wordCount":7},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"But the tide swept in quickly at the beach.","start":244.75,"end":248.25,"wordCount":9},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"And the man was shocked to wake up and find the tide had come in and completely surrounded him, cutting him off from the shore.","start":248.34,"end":257.14,"wordCount":25},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"Fortunately for him, the beach lifeguards were quickly on the scene to stop him from drowning.","start":257.69,"end":263.29,"wordCount":16},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"He was then taken to hospital.","start":269.33,"end":271.5,"wordCount":6},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"He is now in a stable condition.","start":271.52,"end":274.25,"wordCount":7},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"When interviewed, Keith Porter of the Southport Beach said, \"Our beach is so flat that it's very common for the tide to come around the back of people and cut them off from the beach.","start":274.95,"end":286.61,"wordCount":35},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"Thankfully the emergency services have again worked well together to ensure a positive outcome.","start":286.95,"end":294.02,"wordCount":14},{"id":"g2-s16","groupIndex":1,"groupLabel":"News Report 2","answer":"What did Keith Porter say at an interview?","start":323.29,"end":326.39,"wordCount":8},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"It was captured after becoming an online star across the world.","start":350.16,"end":355.27,"wordCount":11},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":", the animal made it to the roof of the building after it took a long break on a 17th floor window edge.","start":357.87,"end":366.39,"wordCount":22},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"A private wildlife management company will release the animal into the wild.","start":374.5,"end":380.48,"wordCount":12},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The raccoon's upward journey began on Monday.","start":380.66,"end":384.63,"wordCount":7},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"The brown animal was spotted stuck on a narrow window edge of the office tower.","start":384.67,"end":391.22,"wordCount":15},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"On Tuesday, the raccoon slowly climbed the building.","start":391.41,"end":395.53,"wordCount":8},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"As it went up, people gathered on the sidewalk below to take photos and cheer for its safety.","start":404.48,"end":411.97,"wordCount":18},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"Online office workers posted photos and videos of the raccoon resting on window edges and climbing up the building's concrete exterior.","start":412.28,"end":423.01,"wordCount":21},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"I just got a text message from my bank, saying my salary has been deposited in my account.","start":532.73,"end":539.51,"wordCount":18},{"id":"g5-s1","groupIndex":4,"groupLabel":"Conversation 2","answer":"What's going on with you lately?","start":716.2,"end":718.63,"wordCount":6},{"id":"g5-s2","groupIndex":4,"groupLabel":"Conversation 2","answer":"You seem so distracted, like you aren't really listening to anything I say.","start":718.63,"end":724.57,"wordCount":13},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"I can't seem to focus on anything, because I still haven't decided if I should accept the offer for that PhD program in London, or if I should take the job offer in New York.","start":727.19,"end":738.92,"wordCount":35},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"But you're running out of time, aren't you?","start":741.74,"end":744.89,"wordCount":8},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"I thought you said the company expected an answer by the end of the month.","start":744.92,"end":749.66,"wordCount":15},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"Actually, it's the beginning of next month for the job, but the university needs a decision by the end of the week.","start":750.33,"end":757.53,"wordCount":22},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"So I have to act quickly.","start":757.6,"end":759.61,"wordCount":6},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"You definitely need advice for an important decision like this.","start":759.86,"end":764.31,"wordCount":10},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"So who have you talked to about it?","start":764.31,"end":767.14,"wordCount":8},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"And your advisor for your master's program?","start":769.2,"end":771.97,"wordCount":7},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've asked their advice and that's part of the problem.","start":772.18,"end":776.03,"wordCount":10},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"My parents want me to get the degree, but my advisor thinks it's time for me to get more work experience.","start":776.53,"end":783.89,"wordCount":21},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"What do you mean by part of the problem?","start":784.18,"end":786.89,"wordCount":9},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"She must have an opinion about all this.","start":796.03,"end":798.86,"wordCount":8},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"I mean, isn't it time for you to think about getting married?","start":799.12,"end":803.91,"wordCount":12},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, I do want to get married, but she thinks we need to wait until we've launched our careers.","start":804.26,"end":811.52,"wordCount":19},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"Plus, she's not sure what she'll be doing next year.","start":811.61,"end":815.35,"wordCount":10},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"She's considering a job in England and one in Australia.","start":815.35,"end":819.13,"wordCount":10},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"And her parents are pushing for the latter.","start":819.14,"end":821.85,"wordCount":8},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Ultimately, it will help you better evaluate information and analyze different ideas and outcomes.","start":965.32,"end":972.68,"wordCount":14},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"An entertaining way of enhancing your analytical skills is to engage them by playing brain games.","start":979.79,"end":988.74,"wordCount":16},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"These games will get you used to thinking in a certain way.","start":996.61,"end":1000.8,"wordCount":12},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"As a result, they will help improve your ability to think.","start":1001.24,"end":1006.11,"wordCount":11},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"However, opinions vary on whether video games are effective.","start":1006.55,"end":1012.06,"wordCount":9},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"The general consensus is that the best ones avoid mindless violence, and instead focus on strategy and challenge us to solve problems and achieve broad goals.","start":1012.35,"end":1026.15,"wordCount":26},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"Joining a debate or reading club or group is also a good idea.","start":1026.84,"end":1032.75,"wordCount":13},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"This provides people with the opportunity to come together and discuss ideas, literature and problems.","start":1033.4,"end":1041.59,"wordCount":15},{"id":"g6-s16","groupIndex":5,"groupLabel":"Passage 1","answer":"Groups like these will help you refine your analytical skills and enable you to express yourself better.","start":1042.08,"end":1049.58,"wordCount":17},{"id":"g6-s18","groupIndex":5,"groupLabel":"Passage 1","answer":"It helps you to actively develop your analytical skills.","start":1058.12,"end":1062.12,"wordCount":9},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"People aren't kidding when they say they \"love\" their dog, or their dog \"loves\" them.","start":1142.61,"end":1148.53,"wordCount":15},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"The doctor's response to the question of whether or not dogs can fall in love like humans do was a straight \"Of course.\"","start":1166.82,"end":1175.46,"wordCount":23},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"Now our furry friends don't really experience \"romantic\" love like in the movies, but they can form deep and lasting bonds with their fellow dogs as well as humans.","start":1196.36,"end":1208.88,"wordCount":29},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"In fact, evidence shows that most dogs stay with one partner their whole lives.","start":1209.02,"end":1216.16,"wordCount":14},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"When they interact, they aren't afraid to smell each other and will express themselves clearly and honestly.","start":1223.7,"end":1231.39,"wordCount":17},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"Once again, it seems we have a lot to learn from dogs.","start":1231.66,"end":1236.11,"wordCount":12},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"\"It was fortunate that the family didn't try to dig up the fossil because that could destroy the specimen.","start":1361.43,"end":1368.24,"wordCount":19},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"They did the right thing by calling someone who would know what to do.","start":1368.36,"end":1372.94,"wordCount":14},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"It's great for the community because now everybody can appreciate it,\" he added.","start":1373.33,"end":1378.68,"wordCount":13},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"They hope to return to the site with geologists for an additional search as there could be more fossils near the site.","start":1384.45,"end":1392.04,"wordCount":22},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Jude and his family had been invited by the researchers to see the fossil being preserved at the university.","start":1392.35,"end":1399.81,"wordCount":19}],"manualOnly":false},"2020-07-set1":{"clips":[{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"That is a warning for snow that has never been seen since the modern system came into place in Scotland.\"","start":73.0,"end":80.4,"wordCount":20},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"The head of road policing said, \"I would urge drivers to take extra care on the roads for their journeys.","start":98.77,"end":105.75,"wordCount":20},{"id":"g1-s12","groupIndex":0,"groupLabel":"News Report 1","answer":"There could be significant traffic delays, so please start to plan your journey now and consider if you really need to travel when conditions are this poor.\"","start":117.04,"end":128.35,"wordCount":27},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"So his classmates decided to give him another chance.","start":304.68,"end":308.44,"wordCount":9},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"And last week, they did it again.","start":316.81,"end":319.45,"wordCount":7},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"\"I remember waking up in the hospital and asking mom what date it was.","start":326.6,"end":331.88,"wordCount":14},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"She told me it was the 28th,\" he said.","start":331.94,"end":335.44,"wordCount":9},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"Students wore their caps and gowns and sat in the front of the auditorium.","start":349.84,"end":355.03,"wordCount":14},{"id":"g3-s12","groupIndex":2,"groupLabel":"News Report 3","answer":"Scott's parents, Karen and Scott Senior, sat front and center.","start":355.35,"end":360.84,"wordCount":10},{"id":"g3-s13","groupIndex":2,"groupLabel":"News Report 3","answer":"After brief speeches, Scott's name was called, only Scott's name.","start":361.04,"end":366.59,"wordCount":10},{"id":"g3-s17","groupIndex":2,"groupLabel":"News Report 3","answer":"\"I don't know how to even explain it.","start":376.14,"end":378.75,"wordCount":8},{"id":"g3-s18","groupIndex":2,"groupLabel":"News Report 3","answer":"I'm speechless to know that so many people are behind me.\"","start":378.85,"end":383.15,"wordCount":11},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"How do you like your new flexible working arrangement?","start":482.83,"end":486.25,"wordCount":9},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"Do you enjoy working from home?","start":486.28,"end":488.33,"wordCount":6},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"Apart from my mother, not too many people I know have time for phone chats during working hours.","start":493.35,"end":499.6,"wordCount":18},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"I tried the library, but found I wasn't really keen on working there.","start":499.84,"end":504.43,"wordCount":13},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, some people seem to spend a lot of time there and not order much.","start":544.58,"end":549.04,"wordCount":15},{"id":"g5-s1","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm going to start looking for another job.","start":680.05,"end":682.48,"wordCount":8},{"id":"g5-s2","groupIndex":4,"groupLabel":"Conversation 2","answer":"I can't see myself getting an opportunity to progress at my company anytime in the near future.","start":682.66,"end":688.22,"wordCount":17},{"id":"g5-s3","groupIndex":4,"groupLabel":"Conversation 2","answer":"And I really think my skills and abilities deserve a higher salary.","start":688.75,"end":692.84,"wordCount":12},{"id":"g5-s4","groupIndex":4,"groupLabel":"Conversation 2","answer":"You're not going to quit, are you?","start":693.12,"end":695.33,"wordCount":7},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"Then I can devote more time and energy to finding a better position at another company.","start":697.68,"end":703.04,"wordCount":16},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"But you've been at your present company less than two years, haven't you?","start":703.43,"end":707.86,"wordCount":13},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"This will be the third time you've left a job in the last five years.","start":708.08,"end":712.5,"wordCount":15},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"If you do several jobs in a relatively short span of time, prospective employers might perceive that you lack loyalty.","start":712.75,"end":721.25,"wordCount":20},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"That could make them wary and reluctant to employ you.","start":721.29,"end":725.18,"wordCount":10},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"And even if I get a promotion, I'm not guaranteed to get a raise.","start":735.49,"end":739.86,"wordCount":14},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"I had that experience at another company I worked at.","start":740.08,"end":743.37,"wordCount":10},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"They wanted you to take on more work and responsibility but for the same amount of money?","start":743.93,"end":749.39,"wordCount":17},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"The way I see it, through having different jobs, I've gathered a lot of experience in different jobs and in different industries.","start":751.33,"end":758.96,"wordCount":22},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"But potential employers might worry that, that experience is not deep, or thorough enough.","start":759.34,"end":766.21,"wordCount":14},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"Perhaps, but I feel pretty confident that I can sell myself.","start":766.28,"end":770.66,"wordCount":11},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"You know what they say, \"Fortune favors the brave.\"","start":770.66,"end":774.11,"wordCount":9},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"There is a saying that goes something along the lines of \"You must love yourself first before you can love someone else.\"","start":901.1,"end":908.83,"wordCount":22},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"Similarly, I personally believe that you must be comfortable and happy in your own company before you can truly be yourself in the company of others.","start":909.35,"end":918.75,"wordCount":26},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"There is a massive difference between being lonely and being alone.","start":919.2,"end":923.55,"wordCount":11},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"However, you don't have to actually be alone to feel that way.","start":926.73,"end":931.13,"wordCount":12},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Many times, I've felt lonely when surrounded by a big group of people.","start":931.21,"end":935.85,"wordCount":13},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"In contrast, being alone can actually be a blessing, particularly when you've actively chosen it.","start":936.05,"end":943.39,"wordCount":15},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"The trick is to be active.","start":951.94,"end":954.07,"wordCount":6},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"Get outside, stretch your legs, do something cultural, buy yourself something tasty to eat or something pretty to wear.","start":954.59,"end":962.56,"wordCount":19},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"You don't have to take anyone else into consideration and can do whatever you please.","start":962.98,"end":967.87,"wordCount":15},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"Spending time alone also allows you to more efficiently take care of problems.","start":968.71,"end":973.72,"wordCount":13},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"If I messed up, he made me stay late until I got it right.","start":1089.69,"end":1094.71,"wordCount":14},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"He demanded the same of himself.","start":1097.83,"end":1100.21,"wordCount":6},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"In 1970, when I was 20, I got married and moved out of my parents' modest place into a housing project.","start":1109.37,"end":1118.41,"wordCount":21},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"But we believed in each other and our faith made us strong.","start":1134.63,"end":1139.04,"wordCount":12},{"id":"g7-s18","groupIndex":6,"groupLabel":"Passage 2","answer":"Each Friday night a truck came, with cases of food that had to be unloaded, priced, and placed on shelves.","start":1148.18,"end":1155.83,"wordCount":20},{"id":"g7-s20","groupIndex":6,"groupLabel":"Passage 2","answer":"But I was always ready to work.","start":1159.85,"end":1162.29,"wordCount":7},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"The researchers say that television viewing may be a risk factor for Alzheimer's disease, but more research is needed to establish a link.","start":1307.47,"end":1316.62,"wordCount":23}],"manualOnly":false},"2020-09-set1":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"NASA officials explained those thicker clouds are signs of ship traffic below.","start":60.0,"end":65.46,"wordCount":12},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"When ships power their way through the ocean, they pump exhaust into the atmosphere, just as cars do.","start":66.24,"end":73.32,"wordCount":18},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"And those massive amounts of particles can cause clouds to form.","start":73.86,"end":78.37,"wordCount":11},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Get enough of those particles in one place, as from the exhaust of a ship, and they can lead to the creation of new clouds easily visible from space.","start":78.85,"end":89.0,"wordCount":29},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"It’s likely that these sorts of clouds are having some effect on the global climate, according to NASA officials.","start":97.87,"end":104.8,"wordCount":19},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"But scientists aren’t yet sure what effect it has.","start":104.96,"end":108.95,"wordCount":9},{"id":"g2-s1","groupIndex":1,"groupLabel":"News Report 2","answer":"Staff at a suburban supermarket in Melbourne say they feel unsafe at work after security guards were removed.","start":159.19,"end":167.45,"wordCount":18},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"This came after a series of physical attacks and verbal abuse by customers.","start":167.62,"end":173.15,"wordCount":13},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"More than 50 workers at the store have signed a letter calling for a permanent security guard following a series of incidents, including a customer threatening to attack a supervisor with a knife.","start":173.53,"end":187.18,"wordCount":33},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":", but that had stopped suddenly on Monday, employees said.","start":194.75,"end":198.74,"wordCount":9},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"One worker said an angry customer had thrown a chicken at his head after complaining about how long she had waited to be served.","start":199.16,"end":207.51,"wordCount":24},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Another worker said the lack of protection at the store made her feel uncomfortable at work.","start":207.86,"end":213.98,"wordCount":16},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"\"We have found very few instances of bad customer behavior at our store in the past year.","start":222.11,"end":228.06,"wordCount":17},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"In the rare cases we have seen bad behavior, we have taken strong action in response, including banning a customer from the store.\"","start":228.15,"end":237.22,"wordCount":23},{"id":"g3-s1","groupIndex":2,"groupLabel":"News Report 3","answer":"Drivers on their way to the Polish capital of Warsaw on Wednesday morning found the road blocked by an unusual obstacle: tons of liquid chocolate that spilled onto the motorway.","start":289.02,"end":302.5,"wordCount":30},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"A truck carrying the sweet load hit a road barrier and overturned, blocking two lanes.","start":302.99,"end":309.75,"wordCount":15},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"The cracked tank spilled a pool of rapidly-hardening chocolate, which quickly covered the width of the road.","start":310.18,"end":317.65,"wordCount":18},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"A representative for the firefighters told the local TV that removing the chocolate was worse than dealing with snow.","start":328.38,"end":336.0,"wordCount":19},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"The local TV also noted that the cleanup spanned more than a mile, because drivers simply drove through the chocolate after the crash, leaving a long chocolate trail.","start":346.32,"end":357.93,"wordCount":28},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"But despite the sticky situation, firefighters and police attending to the cleanup were reportedly cheerful about the long task ahead.","start":358.28,"end":367.14,"wordCount":20},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"Lisa, why did you pay for your meal with cash instead of the payment apps on your phone?","start":473.19,"end":479.44,"wordCount":18},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, I've gone back to cash.","start":479.44,"end":482.06,"wordCount":6},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm only using payment apps if that's the only option.","start":482.06,"end":485.61,"wordCount":10},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm trying to save money for a new phone, and I find that using cash rather than payment apps helps me to save.","start":485.63,"end":492.88,"wordCount":23},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"I don't think it matters whether you take it out to the bank and put it in your wallet or simply transfer from your bank account to the seller's bank account using an app.","start":496.16,"end":505.48,"wordCount":34},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"No, I believe it does matter.","start":505.49,"end":508.08,"wordCount":6},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"Since I stopped carrying cash around and started using my phone apps to pay, I may have developed a tendency to buy more small or non-essential items.","start":519.6,"end":529.49,"wordCount":28},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"Think about the amount of time we spend with our phones in our hands, and all the things we do with our phones.","start":531.38,"end":537.8,"wordCount":23},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"It sometimes seems that our phone is buying the product for us, not ourselves.","start":538.02,"end":543.3,"wordCount":14},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"But if we're spending electronically, we are less likely to make that mental calculation.","start":555.86,"end":561.34,"wordCount":14},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"I stopped using my credit card because I found I was spending excessively.","start":561.48,"end":566.05,"wordCount":13},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"Perhaps I should take the same approach of paying using my phone.","start":566.07,"end":569.92,"wordCount":12},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"So what exactly is the issue?","start":674.9,"end":677.72,"wordCount":6},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm looking through my files now, and I see that the delivery was this morning.","start":689.28,"end":694.53,"wordCount":15},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"The ones we ordered were dark brown to match the table.","start":710.87,"end":715.6,"wordCount":11},{"id":"g5-s34","groupIndex":4,"groupLabel":"Conversation 2","answer":"Did everything else you ordered from us arrive okay?","start":740.31,"end":743.46,"wordCount":9},{"id":"g5-s37","groupIndex":4,"groupLabel":"Conversation 2","answer":"The mirror and two paintings are here.","start":746.79,"end":749.66,"wordCount":7},{"id":"g5-s39","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yes, we haven't noticed anything else wrong or missing.","start":753.61,"end":756.74,"wordCount":9},{"id":"g5-s40","groupIndex":4,"groupLabel":"Conversation 2","answer":"But if we do, we will certainly let you know.","start":756.74,"end":759.65,"wordCount":10},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"This method is simple in theory but can be endlessly complex in practice.","start":916.75,"end":922.26,"wordCount":13},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"You divide all the stuff in your house—all of it—into several categories, and then examine each item—all of them—to see if it sparks joy.","start":922.88,"end":933.56,"wordCount":28},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"If it does, you keep it.","start":934.07,"end":936.38,"wordCount":6},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"So, is the TV show inspiring people to tidy up?","start":941.39,"end":945.74,"wordCount":10},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"One store received thousands of bags of used possessions in one day.","start":954.6,"end":959.74,"wordCount":12},{"id":"g7-s1","groupIndex":6,"groupLabel":"Passage 2","answer":"At just 12 years old, Mike Hannon is making a difference in his community—one lunch at a time.","start":1058.97,"end":1066.84,"wordCount":19},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"Mike delivers meals to the homeless.","start":1074.83,"end":1077.81,"wordCount":6},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"\"It's like a way to give people joy, maybe spark something in them that can change them,\" Mike told WBZ-TV.","start":1078.05,"end":1086.67,"wordCount":21},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"The mayor of Mike's town feels that Mike is a great community leader, especially in such times of so much negative news.","start":1086.99,"end":1096.12,"wordCount":22},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"While his father commented on how proud he was of his son, yet, Mike isn't looking for praise, but kindness in return.","start":1096.37,"end":1106.27,"wordCount":22},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"He hopes his acts of charity will influence others to spread positive actions in their own towns.","start":1106.48,"end":1113.14,"wordCount":17},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"Mike includes a handwritten message of joy on each bag.","start":1114.17,"end":1118.09,"wordCount":10},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"His message and star power has spread all over the country.","start":1118.25,"end":1122.87,"wordCount":11},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"Use of electronics has also been known to lead to a decline in human interactions.","start":1275.67,"end":1281.99,"wordCount":15},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"Rather than having real-life conversations, many express emotions and engage in deep conversations through social media sites.","start":1282.33,"end":1292.46,"wordCount":18},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"Many students use their phones and computers during class for non-academic activities, which leads to poor grades.","start":1292.71,"end":1301.67,"wordCount":18},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Technology is a great tool; however, it's important to recognize its downsides.","start":1310.07,"end":1317.06,"wordCount":12},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Lack of sleep, reduction of productivity and weight gain are only a few.","start":1317.45,"end":1323.34,"wordCount":13}],"manualOnly":false},"2020-12-set1":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"Although fatalities are rare, the stings can cause extreme pain and stop people breathing.","start":70.95,"end":77.45,"wordCount":14},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"After being spotted in the Mediterranean, a marine scientist says, “The fish is spreading, and that's a cause for concern.”","start":90.01,"end":98.22,"wordCount":20},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"It is expected to bring significant reduction in pollution levels.","start":186.33,"end":190.44,"wordCount":10},{"id":"g3-s1","groupIndex":2,"groupLabel":"News Report 3","answer":"A Philippine fisherman was feeling down on his luck when a house fire forced him to clear out his possessions and change locations.","start":258.72,"end":266.59,"wordCount":23},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"Then a good luck charm that he had kept under his bed changed his life.","start":266.88,"end":272.22,"wordCount":15},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"What can I do for you?","start":433.43,"end":434.9,"wordCount":6},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, I'm here to show you what our firm can do for you.","start":434.9,"end":438.44,"wordCount":13},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"We are a global company with 75 years of history, and our clients include some of the world's largest companies.","start":445.62,"end":453.25,"wordCount":20},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"But you said you would show me what you could do for me.","start":458.27,"end":461.53,"wordCount":13},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, what exactly can your firm do for my company?","start":461.53,"end":466.02,"wordCount":10},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"We advise businesses on all matters, from market analysis to legal issues, anything a business like yours could need.","start":466.3,"end":474.42,"wordCount":19},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"That way I could better respond as to how we can help you.","start":482.85,"end":486.09,"wordCount":13},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"This is a family business started by my grandfather in 1950.","start":487.61,"end":492.34,"wordCount":11},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"We manufacture and export stone for buildings and other constructions.","start":495.76,"end":500.49,"wordCount":10},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"Our clients usually want a special kind of stone cut in a special design.","start":500.58,"end":505.78,"wordCount":14},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"And that's what we do in our factory.","start":505.93,"end":508.52,"wordCount":8},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"I would suggest that you let us first conduct a financial analysis of your company, together with an analysis of your competitors in India.","start":519.32,"end":527.61,"wordCount":24},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"That way we could offer the best advice on different ways forward for you.","start":527.92,"end":531.99,"wordCount":14},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"It looks like you had a professional interior designer.","start":626.74,"end":629.83,"wordCount":9},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"I did it all by myself with a little help from my brother Greg.","start":632.68,"end":637.19,"wordCount":14},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"He's actually in the construction business, which was really helpful.","start":637.29,"end":641.24,"wordCount":10},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"I know I could probably repaint the walls in my house over a weekend or something, but not a full renovation.","start":643.41,"end":650.02,"wordCount":21},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"Where did you get your ideas?","start":650.52,"end":652.43,"wordCount":6},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"I wouldn't know where to start.","start":652.43,"end":654.0,"wordCount":6},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, for a while now, I've been regularly buying home design magazines.","start":654.38,"end":659.4,"wordCount":12},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"Children were responsible for the vast majority of cases—95% of objects removed from noses and 85% from ears.","start":849.66,"end":859.94,"wordCount":19},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"According to England's Hospital Episode Statistics, children aged one to four were the most likely to need help from doctors for a foreign object in their nose.","start":875.65,"end":886.32,"wordCount":27},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"Five- to nine-year-olds come to the hospital with something in their ears the most.","start":886.84,"end":891.33,"wordCount":16},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"Paper and plastic toys were the items removed next most from noses.","start":898.5,"end":903.3,"wordCount":12},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"According to the study, the occurrence of foreign objects in children is generally attributed to curiosity.","start":908.17,"end":915.05,"wordCount":16},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"Children have an impulse to explore their noses and ears.","start":915.41,"end":919.21,"wordCount":10},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"Any ear, nose and throat surgeon has many weird stories about wonderful objects found in the noses and ears of children and adults.","start":923.82,"end":932.81,"wordCount":23},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"Batteries can pose a particular danger.","start":933.35,"end":936.19,"wordCount":6},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"In all cases prevention is better than cure.","start":936.74,"end":939.98,"wordCount":8},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"This is why many toys contain warnings about small parts.","start":940.43,"end":944.66,"wordCount":10},{"id":"g6-s16","groupIndex":5,"groupLabel":"Passage 1","answer":"Recognizing problems early and seeking medical attention is important.","start":945.26,"end":949.9,"wordCount":9},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"With a bike, newcomers here can travel farther but for almost no cost.","start":1088.06,"end":1093.34,"wordCount":13},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"The three hours a day, they used to spend walking to and from English language lessons, has been reduced to just one hour.","start":1093.79,"end":1101.95,"wordCount":23},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Our bike-riding lessons are so successful that we are urgently looking for more volunteers.","start":1102.59,"end":1109.26,"wordCount":15},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"Thanks to the International Space Station, we know quite a bit about the effects of low gravity on the human body, but NASA scientists want to learn more.","start":1199.53,"end":1210.07,"wordCount":28},{"id":"g8-s2","groupIndex":7,"groupLabel":"Passage 3","answer":"To that end, they have been studying how other species deal with low gravity, specifically focusing on mice.","start":1210.64,"end":1218.21,"wordCount":18},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"The results are both interesting and humorous.","start":1218.6,"end":1222.36,"wordCount":7},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"As you'll notice in the video, the mice definitely seem uncomfortable at the beginning of the experiment.","start":1237.51,"end":1243.3,"wordCount":17},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"They move around clumsily, drifting within the small confines of the cage, and do their best to figure out which way is up, but without success.","start":1243.64,"end":1253.54,"wordCount":26},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"However, it's not long before the mice begin to catch on.","start":1253.83,"end":1257.57,"wordCount":11},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"They adapt remarkably well to their new environment and even use the lack of gravity to their advantage as they push themselves around the cage.","start":1258.0,"end":1266.49,"wordCount":25},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"That's when things really get wild.","start":1267.31,"end":1269.64,"wordCount":6},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Several of the mice are observed running around the cage walls.","start":1278.54,"end":1282.41,"wordCount":11}],"manualOnly":false},"2020-12-set2":{"clips":[{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"The “relieved” customer was reunited with her check on Wednesday.","start":64.48,"end":68.42,"wordCount":10},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"It contained money from her apartment sale, already planned for a down payment on a new home.","start":68.55,"end":74.22,"wordCount":17},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"The customer did not tip the waiter after her meal.","start":74.65,"end":77.98,"wordCount":10},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"She tried to give him money later on, but he graciously declined.","start":78.09,"end":82.63,"wordCount":12},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"The move is due to global warming and rising sea levels.","start":146.35,"end":150.31,"wordCount":11},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"It will be costly financially to the community.","start":170.65,"end":173.53,"wordCount":8},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"“About 15 years ago, they estimated the cost at $180 million.","start":173.78,"end":178.98,"wordCount":11},{"id":"g3-s1","groupIndex":2,"groupLabel":"News Report 3","answer":"A man in Halifax, Canada, wanted to find out if people were thankful for someone holding the door open for them.","start":260.33,"end":267.63,"wordCount":21},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"The social experiment showed that 99 out of 100 people expressed gratitude.","start":267.81,"end":274.06,"wordCount":12},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"“I didn’t think we were going to get 99.","start":274.69,"end":277.38,"wordCount":9},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"“What we know from research is that from grateful people come good things,” he said.","start":291.52,"end":297.32,"wordCount":15},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"“A simple way to induce gratitude in people is opening doors and so we went to six places and opened the doors for people.”","start":297.54,"end":305.96,"wordCount":24},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"The door was held for 15 to 20 people at a time at each location.","start":314.97,"end":320.46,"wordCount":15},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"“We did have one that didn’t say thank you.","start":321.26,"end":324.09,"wordCount":9},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"I suspect out of the 100 people, there were probably a bunch of them having a bad day, but grateful people make people grateful,” said Foran.","start":330.42,"end":340.47,"wordCount":26},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"What would you like to know?","start":452.19,"end":453.41,"wordCount":6},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"He tells me it has saved him over $500 thus far.","start":460.58,"end":464.98,"wordCount":11},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"Does that sound about right to you?","start":464.98,"end":466.81,"wordCount":7},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"Are you interested in installing some solar panels on your roof, sir?","start":503.34,"end":507.9,"wordCount":12},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"If you wish to come into our office, we could show you the different solutions we offer.","start":510.46,"end":515.23,"wordCount":17},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"But you know a typical household will make back that initial investment in about five years.","start":533.33,"end":539.1,"wordCount":16},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Recycling is not one of the country's strong points.","start":867.49,"end":870.73,"wordCount":9},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"It's not uncommon to be offered many more plastic bags than one could ever need when visiting supermarkets and shopping malls.","start":871.06,"end":879.03,"wordCount":21},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"But, slowly, things are starting to change for the better.","start":879.61,"end":883.62,"wordCount":10},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"The regulation will come into full effect next month.","start":910.64,"end":913.87,"wordCount":9},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"Not only positive responses from the Balinese, we received good responses from the central government, other local governments and even from overseas.”","start":918.72,"end":929.09,"wordCount":22},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"The governor is a determined environmentalist and he has more laws planned to protect the island's waterways, in particular, and to support the introduction of electric vehicles too.","start":934.07,"end":945.81,"wordCount":28},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"The whale population has become endangered due to commercial whaling activities in recent years.","start":1061.4,"end":1067.52,"wordCount":14},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"This is because they are sometimes hunted for their meat or their skin.","start":1068.04,"end":1071.95,"wordCount":13},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"Over-hunting could lead to the disappearance of the whale population, possibly causing major problems to the global food chain.","start":1072.58,"end":1080.93,"wordCount":20},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"The whales give birth off the Southeast Coast of America in the winter and travel to feeding grounds off the Northeast Coast in the early spring.","start":1081.79,"end":1090.9,"wordCount":26},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"The Northeast Coast is a critically important source of food.","start":1091.34,"end":1094.98,"wordCount":10},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"The animals often feed close to shore.","start":1095.21,"end":1098.14,"wordCount":7},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"This provides watchers on land with “unbeatable views of one of the rarest of marine mammals.”","start":1098.21,"end":1104.23,"wordCount":16},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"But what was once advertised as nutritious is becoming unpopular.","start":1202.33,"end":1207.07,"wordCount":10},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"And in the UK, dairy consumption overall has fallen by a third in the past 20 years.","start":1213.3,"end":1219.42,"wordCount":17},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"Milk is increasingly being described in a negative light.","start":1220.43,"end":1223.91,"wordCount":9},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"A recent blog suggested maybe people are drinking less milk because it is poisonous to many of us.","start":1224.23,"end":1231.01,"wordCount":18},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"It needs a series of complex proteins to break it down.","start":1235.59,"end":1239.28,"wordCount":11},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Without enough of these proteins, the lactose is broken down by bacteria in the human body.","start":1239.87,"end":1245.65,"wordCount":16},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"This can cause physical pain and produce gas in the stomach.","start":1246.39,"end":1250.18,"wordCount":11},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"However, after we have finished breast or formula feeding, most of us don't continue producing the complex proteins in our body, which are necessary to break down the lactose.","start":1250.65,"end":1261.78,"wordCount":29},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Despite the problems in digesting milk, it does provide many benefits.","start":1262.93,"end":1267.27,"wordCount":11},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"It contains vitamins A and D, as well as protein and isn't full of calories.","start":1269.2,"end":1275.02,"wordCount":15},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"You can test yourself by drinking a large glass of milk.","start":1275.88,"end":1279.15,"wordCount":11}],"manualOnly":false},"2021-06-set1":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"His teacher recognized Joe's talent and posted all his work online, which led to something pretty wonderful.","start":67.42,"end":75.42,"wordCount":17},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"Every day after school, Joe's dad drives him to the restaurant so he can put his ideas straight on the wall.","start":86.52,"end":94.01,"wordCount":21},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Once he's all done, the work will remain there permanently.","start":94.2,"end":98.14,"wordCount":10},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Joe's dad said Joe is a really talented little boy.","start":98.51,"end":102.52,"wordCount":10},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"But drawing is definitely what he is most passionate about.","start":106.1,"end":110.3,"wordCount":10},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"The image appears to show a man carrying the dog in his arms.","start":177.84,"end":182.12,"wordCount":13},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The cafe is open in the mornings every day of the year and has two members of staff or supervisors on shift every day.","start":307.23,"end":315.36,"wordCount":24},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"It doesn't take donations and doesn't want to be seen as a charity.","start":323.06,"end":327.44,"wordCount":13},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"And whatever their financial background, or their educational background, most people will have something in common with each other.","start":334.9,"end":342.79,"wordCount":19},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"So what time do you think we should have the party on Saturday?","start":448.13,"end":451.75,"wordCount":13},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"Then we'll have the afternoon to prepare food and drink, and stuff like that.","start":455.4,"end":459.63,"wordCount":14},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"And now I think we should prepare some sandwiches and snacks, and some other kinds of food, so that people can just help themselves, rather than getting everyone to sit down at the table to eat a meal.","start":469.43,"end":481.37,"wordCount":38},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"I think that's a bit too formal.","start":481.5,"end":483.51,"wordCount":7},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's better to let people walk around and talk to each other, or sit where they like.","start":483.88,"end":489.0,"wordCount":17},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'll go to the supermarket to get some drinks.","start":491.51,"end":494.42,"wordCount":9},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"I think I might try that big new supermarket on the other side of town and see what they have.","start":494.71,"end":500.75,"wordCount":20},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"I think we should get some beer and wine, and some fruit juice, and other soft drinks.","start":503.48,"end":509.22,"wordCount":17},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"I think those drinks will be enough.","start":511.41,"end":513.43,"wordCount":7},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"And I heard that the new supermarket offers some big discounts to attract customers.","start":513.61,"end":519.06,"wordCount":14},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"So going there should be a great idea.","start":519.18,"end":521.69,"wordCount":8},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"What should we do about music?","start":522.04,"end":523.95,"wordCount":6},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"Maybe we should ask Paul to bring his computer and speakers, so that we can play some music.","start":524.25,"end":529.63,"wordCount":18},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"He has a great collection of different stuff.","start":529.67,"end":532.49,"wordCount":8},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'd also like it to be small, so that it's easy to drive in the city.","start":665.25,"end":669.69,"wordCount":16},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"In fact, I think his family owns the business.","start":673.6,"end":676.85,"wordCount":9},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"He's a really nice guy, and he knows a lot about cars.","start":676.9,"end":680.77,"wordCount":12},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"I could give you his phone number if you want, and you could call him and ask him questions.","start":680.95,"end":686.8,"wordCount":19},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"Oh, no, he's not like that.","start":693.04,"end":695.41,"wordCount":6},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"He's a good friend of mine, and he would never try to pressure you or cheat you.","start":695.41,"end":700.21,"wordCount":17},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"To be honest, I could use some help in deciding what type of vehicle would best suit my needs.","start":704.62,"end":710.83,"wordCount":19},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"Speaking to an expert would be a good idea.","start":711.01,"end":713.83,"wordCount":9},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"You have nothing to worry about.","start":715.59,"end":717.78,"wordCount":6},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"He's a lovely guy, and he'll be happy to help.","start":717.78,"end":721.48,"wordCount":10},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Pigs are not native to North America.","start":838.29,"end":841.32,"wordCount":7},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"In the early times, pigs were allowed to wander freely in search of food.","start":848.97,"end":853.78,"wordCount":14},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"They also harbor dozens of diseases that threaten both humans and farm animals.","start":872.8,"end":878.72,"wordCount":13},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"Forest patches with wild pigs have been found to have considerably reduced plant and animal diversity.","start":879.34,"end":886.15,"wordCount":16},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"Wild pigs will eat almost anything containing calories.","start":904.65,"end":909.69,"wordCount":8},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"They can also harm other wild species through indirect competition, rather than eating them or shrinking their food supply.","start":916.54,"end":924.76,"wordCount":19},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"The foxes were almost wiped out completely.","start":941.56,"end":944.79,"wordCount":7},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"The effect would be to roast the beans all over, and produce perfect coffee.","start":1033.33,"end":1038.7,"wordCount":14},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"The businessmen say that on Earth, beans can easily break apart and get burned in the roaster.","start":1039.28,"end":1045.37,"wordCount":17},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"The spacecraft will reach a height of around 200 km.","start":1058.0,"end":1062.37,"wordCount":10},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"Surprisingly, the Space Roaster concept—should it go ahead—will not be the first attempt to take coffee into space.","start":1092.28,"end":1100.38,"wordCount":20},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"In 2015, two Italian companies collaborated on the construction of a similar type of spacecraft, which was the first coffee machine designed for use in space.","start":1100.58,"end":1112.89,"wordCount":26},{"id":"g8-s2","groupIndex":7,"groupLabel":"Passage 3","answer":"It has a population of a mere 49 souls.","start":1187.47,"end":1191.1,"wordCount":9},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"Each March, this tiny village swells up in numbers, because it is located in the middle of a race that takes place every year.","start":1191.81,"end":1200.67,"wordCount":24},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"The toughness of the race allows for racers to eat pretty much whatever they want.","start":1251.24,"end":1256.18,"wordCount":15},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Jan moved from Idaho with her husband in 1972 and opened a restaurant.","start":1269.8,"end":1275.93,"wordCount":13}],"manualOnly":false},"2021-06-set2":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"He was surprised when his GPS system told him he had arrived, although there were no signs of any of the famous buildings or architecture.","start":61.91,"end":71.72,"wordCount":25},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"The man parked but didn't put on the handbrake of his car properly.","start":72.32,"end":76.41,"wordCount":13},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Police said that the car had come to a halt after hitting the sign, but did not appear to be seriously damaged, although an ambulance was called to check on the pensioner.","start":91.52,"end":103.0,"wordCount":32},{"id":"g2-s1","groupIndex":1,"groupLabel":"News Report 2","answer":"Glasgow has pledged to become the first carbon neutral city in the UK.","start":161.26,"end":165.88,"wordCount":13},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"\"Cats are sleeping just beside us.","start":318.56,"end":321.35,"wordCount":6},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"While the positives are many, there are still some obstacles.","start":342.21,"end":345.91,"wordCount":10},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"“Sometimes a cat will walk on a phone and cut off the call, or they shut down the computers by walking onto the off switch.”","start":346.45,"end":354.15,"wordCount":25},{"id":"g3-s13","groupIndex":2,"groupLabel":"News Report 3","answer":"Still, cats in the workplace have been a tremendous success for the company.","start":355.81,"end":360.45,"wordCount":13},{"id":"g3-s14","groupIndex":2,"groupLabel":"News Report 3","answer":"The policy has led to various other companies doing the same.","start":360.72,"end":365.02,"wordCount":11},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"But I can't quite remember what it was all about.","start":496.11,"end":498.96,"wordCount":10},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"Is this a lot of money we're talking about here?","start":499.26,"end":501.89,"wordCount":10},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"He told us he'd got into an accident.","start":509.3,"end":511.9,"wordCount":8},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"You think Jimmy's just making it all up?","start":533.6,"end":535.97,"wordCount":8},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"See, I did think it was a bit weird for him to be asking for money for that sort of thing.","start":536.2,"end":541.42,"wordCount":21},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"And his story was a bit vague to begin with.","start":541.5,"end":544.5,"wordCount":10},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"But I thought maybe he doesn't want his parents to know about what happened.","start":544.72,"end":549.06,"wordCount":14},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"So we didn't make a fuss about it.","start":555.15,"end":557.61,"wordCount":8},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"But there must be some problems.","start":671.7,"end":673.99,"wordCount":6},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"I mean, how do you know that you won't get bad fruit, or that the eggs won't be broken?","start":673.99,"end":679.51,"wordCount":19},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"The food is exactly the same as the stuff you buy in a conventional shop.","start":681.25,"end":686.42,"wordCount":15},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"They aren't going to deliver you food that is out of date.","start":686.53,"end":689.97,"wordCount":12},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"And if you get a broken egg, well, that could happen in a conventional shop, too.","start":689.98,"end":695.52,"wordCount":16},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Is it not more expensive to get everything delivered?","start":706.44,"end":709.78,"wordCount":9},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"I actually found that it was cheaper for me, as I live quite far away from my local supermarket.","start":710.17,"end":716.27,"wordCount":19},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"So with the deliveries, I'm actually saving on petrol.","start":716.29,"end":720.55,"wordCount":9},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"If you aren't driving your own car, then you are saving on fuel.","start":722.45,"end":726.37,"wordCount":13},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm going to go on the computer now and give it a try.","start":728.84,"end":732.12,"wordCount":13},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"So, which supermarket do you think is the best to order from?","start":732.12,"end":735.85,"wordCount":12},{"id":"g5-s27","groupIndex":4,"groupLabel":"Conversation 2","answer":"Otherwise, we'll be here all day.","start":738.63,"end":741.02,"wordCount":6},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"This means they have overwhelming negative emotions towards the subject, ranging from rage to despair.","start":862.61,"end":870.11,"wordCount":15},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"Other emotions triggered by math include feelings of tension and frustration.","start":870.65,"end":875.58,"wordCount":11},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Physical symptoms include a racing heart or struggling to catch breath.","start":875.91,"end":881.3,"wordCount":11},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"The phenomenon of math anxiety is characterized as a general sense of feeling that the subject is hard compared with other subjects leading to a subsequent lack or loss of confidence.","start":881.78,"end":894.27,"wordCount":31},{"id":"g7-s1","groupIndex":6,"groupLabel":"Passage 2","answer":"People spend a lot of time using phones and computers.","start":1038.02,"end":1042.36,"wordCount":10},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"Much of that time is devoted to text messages and social media.","start":1043.08,"end":1047.83,"wordCount":12},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"But many people choose to spend their time playing computer games.","start":1048.43,"end":1052.26,"wordCount":11},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"For years, parents and teachers have worried that these games might be addictive.","start":1052.82,"end":1058.43,"wordCount":13},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"And now, the World Health Organization has recognized addiction to computer games as a disease.","start":1058.9,"end":1065.72,"wordCount":15},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"The organization explains that this decision reflects general agreement among experts around the world that some people have a problem with these games.","start":1066.78,"end":1076.88,"wordCount":23},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"They show a pattern of behavior characterized by a lack of control.","start":1077.29,"end":1081.54,"wordCount":12},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"Such people make computer games a priority over their responsibilities.","start":1082.25,"end":1087.67,"wordCount":10},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"They may play games instead of attending school, or work, or socializing.","start":1088.01,"end":1093.6,"wordCount":12},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"According to the World Health Organization experts, people's use of computer games is different from their use of the Internet, social media and online shopping.","start":1094.27,"end":1105.12,"wordCount":25},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"These experts claim there is not sufficient data to indicate that people's reliance on those other activities is an addiction.","start":1105.81,"end":1114.04,"wordCount":20},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"This behavior can become a disorder.","start":1119.51,"end":1122.02,"wordCount":6},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"To meet the new definition for addiction, the behavior must damage a person's relationships or performance at school or work, and this must last for at least a year.","start":1122.69,"end":1134.2,"wordCount":29},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"Still not all behavior experts agree.","start":1134.78,"end":1138.06,"wordCount":6},{"id":"g7-s17","groupIndex":6,"groupLabel":"Passage 2","answer":"Thus, they claim it is too early to call computer game addiction a disorder.","start":1142.42,"end":1147.52,"wordCount":14},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"Maybe you carry the most powerful passport in the world, or perhaps the rarest passport.","start":1218.43,"end":1224.95,"wordCount":15},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"Switzerland's passport is dark red, for example, while most European countries prefer a shade of red.","start":1237.4,"end":1244.94,"wordCount":16},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"There are no official rules regarding passport colors, but countries follow a certain set of norms when designing them.","start":1246.65,"end":1255.28,"wordCount":19},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"There are also a few compulsory aspects of passports.","start":1269.52,"end":1273.77,"wordCount":9},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"They must be made from a material that bends.","start":1274.61,"end":1278.02,"wordCount":9},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Despite these existing recommendations, there is nothing regarding the cover color.","start":1292.11,"end":1298.14,"wordCount":11},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"And they can also hide dirt and wear.","start":1306.79,"end":1309.75,"wordCount":8},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"While there's little innovation when it comes to passport cover color, the same cannot be said for the pages.","start":1310.15,"end":1317.4,"wordCount":19}],"manualOnly":false},"2021-12-set1":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"They were meant to be reunited with the pet in their new home city in Texas.","start":66.57,"end":72.65,"wordCount":16},{"id":"g1-s11","groupIndex":0,"groupLabel":"News Report 1","answer":"\"I'm so glad he's alive and coming home soon!\"","start":103.33,"end":107.11,"wordCount":9},{"id":"g1-s14","groupIndex":0,"groupLabel":"News Report 1","answer":"We have notified our customers that their pets arrived safely.","start":112.85,"end":117.17,"wordCount":10},{"id":"g1-s15","groupIndex":0,"groupLabel":"News Report 1","answer":"We will arrange to return the pets to them as soon as possible,\" a spokesperson of United Airlines said.","start":117.17,"end":123.54,"wordCount":19},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"Zoo officials say the baby was born on Monday.","start":180.21,"end":184.05,"wordCount":9},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"It is a female and she weighs nearly 130 kilograms.","start":184.05,"end":188.56,"wordCount":10},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"The baby hasn't been given a name yet.","start":201.82,"end":204.38,"wordCount":8},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"Zoo officials said during this pregnancy, she was closely monitored through physical exams and blood tests.","start":207.02,"end":214.58,"wordCount":16},{"id":"g2-s12","groupIndex":1,"groupLabel":"News Report 2","answer":"She said the elephant's birth went smoothly and that there were no complications.","start":220.13,"end":225.65,"wordCount":13},{"id":"g2-s14","groupIndex":1,"groupLabel":"News Report 2","answer":"That includes the baby's parents, a sister, a brother and an adult female.","start":229.87,"end":235.65,"wordCount":13},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"During the meal, the man's wedding ring slipped off his finger.","start":293.85,"end":298.12,"wordCount":11},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"It fell through the wooden floorboards, apparently lost forever.","start":298.27,"end":302.38,"wordCount":9},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"Three days later, the happy wife called to claim the ring.","start":325.6,"end":329.68,"wordCount":11},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"She even texted pictures of her and her husband eating there in 2017 as proof.","start":329.68,"end":336.39,"wordCount":15},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"The restaurant mailed the ring back to the happy couple.","start":336.47,"end":339.99,"wordCount":10},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"That would depend on the quality of paint you choose.","start":666.38,"end":669.95,"wordCount":10},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"In that case, we would prefer the more expensive option.","start":686.38,"end":691.12,"wordCount":10},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"Please bear in mind that the price includes moving all the furniture, and the whole task would take two days.","start":704.98,"end":712.25,"wordCount":20},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"Plus, it requires two people, which works out more expensive.","start":725.43,"end":729.26,"wordCount":10},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"But does that mean I could not live here in my own house during those two days?","start":730.56,"end":735.79,"wordCount":17},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"Oh well, that changes everything, I'm afraid.","start":737.4,"end":741.09,"wordCount":7},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"I would have to stay with a friend or check into a hotel.","start":741.09,"end":744.8,"wordCount":13},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"I hadn't considered any of that.","start":744.81,"end":747.34,"wordCount":6},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm starting to realize that painting my house is far more troublesome than I had anticipated.","start":747.34,"end":753.58,"wordCount":16},{"id":"g5-s28","groupIndex":4,"groupLabel":"Conversation 2","answer":"Most of our clients go through the same realization.","start":755.79,"end":759.26,"wordCount":9},{"id":"g5-s31","groupIndex":4,"groupLabel":"Conversation 2","answer":"Please feel free to call me for any further questions.","start":762.22,"end":766.19,"wordCount":10},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"So how can you help your child do their best?","start":915.32,"end":919.2,"wordCount":10},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"Creating an ideal working environment will make it easier for them to get down to their assignments quickly.","start":919.2,"end":925.69,"wordCount":18},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Make sure it's free of distractions, and—for primary school children at least—somewhere near you, so you can answer questions and offer encouragement.","start":925.91,"end":936.44,"wordCount":24},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Get them to tell you everything they have to do.","start":946.12,"end":949.42,"wordCount":10},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Then encourage them to establish an order in which they do work.","start":949.42,"end":953.39,"wordCount":12},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"It's best to take on the most difficult task second—once they're settled, but before they get tired.","start":961.93,"end":969.73,"wordCount":18},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"If older children have more than an hour of homework, encourage them to schedule a short break to stretch.","start":969.93,"end":977.5,"wordCount":19},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"If you encourage them to tell you what they've learned, they'll absorb the information more deeply and remember it more readily.","start":977.55,"end":985.43,"wordCount":21},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"That means weight can be hard for individuals to control, which makes the bonus unfair.","start":1100.56,"end":1107.01,"wordCount":15},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"Some experts say the policy is inconsistent with the science of what we know about body weight regulation.","start":1107.04,"end":1114.97,"wordCount":18},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"A more productive method of encouraging health among employees is to promote healthy behaviors.","start":1120.01,"end":1126.69,"wordCount":14},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"For example, companies can give workers gym memberships, or encourage participation in lectures on healthy eating and living.","start":1126.69,"end":1135.77,"wordCount":18},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"They can also reduce sweets and provide healthier snacks in the office and healthier meals at the company canteen.","start":1135.8,"end":1143.41,"wordCount":19},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"Or they can give employees more time during their lunch break to exercise.","start":1143.48,"end":1148.38,"wordCount":13},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"These are much better and much more productive ways for companies to move forward on their employees' wellbeing.","start":1148.46,"end":1155.8,"wordCount":18},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"They don't understand why successive governments have failed to act on this.","start":1277.74,"end":1283.06,"wordCount":12},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"They want the department of education to record which children are left-handed and what their educational attainments are, since they make up some (10%) of the population.","start":1283.06,"end":1294.2,"wordCount":28},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Educators don't know how to deal with this.","start":1301.37,"end":1304.74,"wordCount":8},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Campaigners point out that a high percentage of the prison population is left-handed.","start":1310.03,"end":1315.86,"wordCount":14},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"They say that these prison numbers are unusually high and ask why it is the case.","start":1315.87,"end":1322.52,"wordCount":16}],"manualOnly":false},"2021-12-set2":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"For 14 years, she made numerous hospital visits.","start":60.35,"end":64.77,"wordCount":8},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"However, no doctor could identify any problem.","start":64.77,"end":69.04,"wordCount":7},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"Her uncontrollable coughing was a mystery.","start":69.04,"end":72.06,"wordCount":6},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Finally, the woman got a full body scan at a hospital in the city of Qingdao.","start":72.2,"end":77.59,"wordCount":16},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"This special medical procedure revealed she had a chicken bone stuck in her lung.","start":77.59,"end":82.96,"wordCount":14},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"Doctors performed surgery and removed the bone.","start":83.17,"end":86.35,"wordCount":7},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"The simple procedure went smoothly and the woman has recovered fully.","start":86.37,"end":91.41,"wordCount":11},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"With the bone finally removed from her lung, the woman is very happy that she no longer suffers from that annoying cough.","start":91.59,"end":99.18,"wordCount":22},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"Once the fires were over, the family had to fix the damage done to the farm, as it was such a large property.","start":180.0,"end":187.83,"wordCount":23},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"It was this huge fencing that prevented Prickles from finding her way back.","start":192.57,"end":198.51,"wordCount":13},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"Over the years, the family spotted her a few times.","start":198.66,"end":202.61,"wordCount":10},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"They even recorded her with cameras installed to monitor deer activity.","start":202.61,"end":207.56,"wordCount":11},{"id":"g2-s12","groupIndex":1,"groupLabel":"News Report 2","answer":"Seven years later, they were proven wrong.","start":215.41,"end":218.84,"wordCount":7},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"Reports suggest some bars of gold were scattered up to 15 miles away from the airport.","start":312.62,"end":318.96,"wordCount":16},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"Before we continue, I just want to make you aware that this call is being recorded and may be used in the future for training purposes.","start":445.89,"end":453.87,"wordCount":26},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"What can I help you with today?","start":453.87,"end":455.89,"wordCount":7},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"I recently bought an office chair from your company, but I returned it about a week ago.","start":458.71,"end":464.44,"wordCount":17},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’m just calling to inquire when I will be able to get my money back.","start":464.44,"end":469.08,"wordCount":15},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"It says on your website that your company will pay back the money within three working days of you receiving the returned item.","start":469.08,"end":478.18,"wordCount":23},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"But it’s been five working days and I haven’t received anything.","start":478.18,"end":482.68,"wordCount":11},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"What’s your customer reference number, please?","start":485.12,"end":487.62,"wordCount":6},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"The payment was made on Wednesday.","start":502.87,"end":505.58,"wordCount":6},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"Oh, maybe it has something to do with my new card.","start":510.63,"end":514.51,"wordCount":11},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"It was sent to me on Tuesday.","start":514.51,"end":516.86,"wordCount":7},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, you’ll need to update your card details directly on our website.","start":520.97,"end":525.62,"wordCount":12},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"Just make sure you’re logged in.","start":525.62,"end":527.58,"wordCount":6},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"And then under the description of your personal information, you should see an option for updating payment methods.","start":527.58,"end":534.59,"wordCount":18},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"I am logged in, and I’ll give that a go.","start":534.59,"end":538.06,"wordCount":10},{"id":"g4-s26","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’ll make a note here on the system for you, so that the payment will be made tomorrow morning.","start":538.06,"end":543.46,"wordCount":19},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"Oh, can we stay away from the junk food?","start":663.31,"end":666.3,"wordCount":9},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"Okay, well, there’s a place that does salads.","start":668.19,"end":673.17,"wordCount":8},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"Let me have a look at that.","start":673.22,"end":675.16,"wordCount":7},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"But to be honest, I’d prefer something hot, not cold.","start":677.57,"end":682.4,"wordCount":10},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"That’s not the kind of hot I mean.","start":684.38,"end":686.81,"wordCount":8},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’m just not a fan of sauces.","start":686.81,"end":688.98,"wordCount":7},{"id":"g5-s27","groupIndex":4,"groupLabel":"Conversation 2","answer":"Would you like some Italian food, perhaps?","start":701.16,"end":704.38,"wordCount":7},{"id":"g5-s31","groupIndex":4,"groupLabel":"Conversation 2","answer":"I know it’s really tasty and great comfort food, but it’s too fattening for me.","start":712.7,"end":718.52,"wordCount":15},{"id":"g5-s32","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’m trying to keep a slim figure, you know.","start":718.52,"end":721.32,"wordCount":9},{"id":"g5-s33","groupIndex":4,"groupLabel":"Conversation 2","answer":"Oh, you’re really difficult to please.","start":721.32,"end":724.56,"wordCount":6},{"id":"g5-s34","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, there’s a nice Chinese restaurant that delivers.","start":724.56,"end":728.35,"wordCount":8},{"id":"g5-s38","groupIndex":4,"groupLabel":"Conversation 2","answer":"That’s a bit too far away.","start":735.24,"end":737.49,"wordCount":6},{"id":"g5-s39","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you feel like Vietnamese food then?","start":737.49,"end":739.87,"wordCount":7},{"id":"g5-s41","groupIndex":4,"groupLabel":"Conversation 2","answer":"It’s healthy, and we can afford it.","start":741.25,"end":743.81,"wordCount":7},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"The findings suggest that, just as a parent’s personality can affect the personality of a child, the same is true for a cat and its owner.","start":876.99,"end":887.02,"wordCount":26},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"It is possible that the wellbeing of pets is driven by the underlying nature of the owner, not simply by their conscious decisions and behaviours.","start":963.38,"end":973.52,"wordCount":25},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"However, the precise effects vary according to whether you engage in short, fast running or long-distance running.","start":1090.06,"end":1099.04,"wordCount":18},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"For example, in one study, researchers compared participants’ ability to learn new words after several minutes of intense running and after 40 minutes of gentle running.","start":1099.04,"end":1111.88,"wordCount":26},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"In another study, researchers asked volunteers to jog for 30 minutes and then showed them clips from a sad movie.","start":1122.85,"end":1131.53,"wordCount":20},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"The researchers said moderate exercise appears to have helped those participants to be less vulnerable to the impact of the sad movie.","start":1146.72,"end":1156.55,"wordCount":22},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"This meant that he could design the house according to the needs of the family.","start":1262.16,"end":1266.91,"wordCount":15},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"The building style is radically different from what was the fashion of the period.","start":1275.5,"end":1280.89,"wordCount":14},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"At the time, most large homes were constructed of timber and brick.","start":1281.05,"end":1286.52,"wordCount":12},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"This one, however, is made of concrete, a novel construction material in those days.","start":1286.52,"end":1292.79,"wordCount":14},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"The interior of the house, including fittings and furniture, was also designed by the same person.","start":1292.95,"end":1299.46,"wordCount":16},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Most of the furniture you will see is original and in good condition.","start":1299.47,"end":1303.77,"wordCount":13},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"However, those pieces in the children’s bedrooms are copies built to the designs of the architect.","start":1303.99,"end":1311.55,"wordCount":16},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Fortunately, all the blueprints for both the building and its contents have been preserved, so we’ve been able to replace badly damaged furniture.","start":1311.62,"end":1320.9,"wordCount":23},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"Let’s begin our tour, starting from the rooms.","start":1321.23,"end":1324.51,"wordCount":8}],"manualOnly":false},"2022-06-set1":{"clips":[{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"They completed surveys about their diet every four years.","start":61.01,"end":65.33,"wordCount":9},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"They also answered questions about sleep and exercise and health every two years.","start":65.33,"end":71.9,"wordCount":13},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"These beverages included soda, energy drinks and sports drinks.","start":80.28,"end":85.5,"wordCount":9},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"Beverages like pure fruit juice which are sweet but do not contain added sugar were not part of the study.","start":85.68,"end":93.45,"wordCount":20},{"id":"g1-s11","groupIndex":0,"groupLabel":"News Report 1","answer":"The findings held even after the researchers considered other factors that could affect people’s health.","start":93.94,"end":100.63,"wordCount":15},{"id":"g1-s12","groupIndex":0,"groupLabel":"News Report 1","answer":"These factors included lack of exercise and not eating enough vegetables.","start":100.85,"end":106.6,"wordCount":11},{"id":"g1-s13","groupIndex":0,"groupLabel":"News Report 1","answer":"They also included consuming too much meat.","start":106.67,"end":110.43,"wordCount":7},{"id":"g1-s14","groupIndex":0,"groupLabel":"News Report 1","answer":"The scientists say that their results support limiting beverages with added sugar.","start":110.94,"end":116.52,"wordCount":12},{"id":"g1-s15","groupIndex":0,"groupLabel":"News Report 1","answer":"They argue we should replace them with other drinks, with water being the best choice.","start":116.69,"end":122.5,"wordCount":15},{"id":"g1-s16","groupIndex":0,"groupLabel":"News Report 1","answer":"However, the researchers admit this is simply their recommendation.","start":122.6,"end":127.22,"wordCount":9},{"id":"g1-s17","groupIndex":0,"groupLabel":"News Report 1","answer":"The study found only an association: It did not prove that drinks with added sugar cause early death.","start":127.29,"end":134.8,"wordCount":18},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"The young girl braved the threat of bears, wolves and temperatures far below freezing.","start":305.81,"end":312.1,"wordCount":14},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"She made the journey through a remote region in Siberia after waking up to find her grandmother motionless.","start":312.3,"end":319.86,"wordCount":18},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"As a result, the girl’s mother is facing a criminal case.","start":328.35,"end":332.74,"wordCount":11},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"She stands accused of leaving a minor in danger in the care of the elderly.","start":332.85,"end":338.6,"wordCount":15},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"The journey was only recently confirmed by authorities.","start":365.19,"end":368.86,"wordCount":8},{"id":"g3-s12","groupIndex":2,"groupLabel":"News Report 3","answer":"But though she was suffering from the effects of extreme cold, the child reportedly suffered no life-threatening effects.","start":368.99,"end":377.14,"wordCount":19},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"I’ve made a new friend recently.","start":487.16,"end":489.55,"wordCount":6},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"Her name is Susan and she’s from South Africa.","start":489.55,"end":492.9,"wordCount":9},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"She has very cool photos on her social media.","start":496.79,"end":500.1,"wordCount":9},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"The photos of her hometown look amazing.","start":500.3,"end":503.45,"wordCount":7},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"It’s in the southwest of South Africa.","start":508.41,"end":511.63,"wordCount":7},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"She says it’s very green and windy.","start":511.74,"end":515.09,"wordCount":7},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"The city was built by European settlers.","start":515.18,"end":518.52,"wordCount":7},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"And there’s a big mountain that overlooks the city.","start":518.52,"end":522.17,"wordCount":9},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"The mountain is called Table Mountain because it’s flat at the top.","start":522.39,"end":528.19,"wordCount":12},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"What are the people there like?","start":530.28,"end":532.26,"wordCount":6},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, Susan says South Africa is very mixed.","start":532.42,"end":537.02,"wordCount":8},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"There are black people and white people and Indian people.","start":537.07,"end":542.04,"wordCount":10},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"She says her ancestors were from Britain.","start":543.77,"end":546.76,"wordCount":7},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"Many languages are spoken in South Africa, but she only speaks English.","start":546.95,"end":552.49,"wordCount":12},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"They must play football a lot then, right?","start":557.14,"end":559.96,"wordCount":8},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"I think they play football, but it’s not as popular as rugby.","start":560.15,"end":564.76,"wordCount":12},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"Rugby is a sport with two teams and the players carry the ball in their arms and throw it at each other.","start":567.41,"end":574.88,"wordCount":22},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"The ball is not round and the players push each other.","start":575.14,"end":579.12,"wordCount":11},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"I don’t really understand the rules.","start":579.23,"end":581.8,"wordCount":6},{"id":"g4-s31","groupIndex":3,"groupLabel":"Conversation 1","answer":"That sounds like a very strange sport indeed.","start":584.37,"end":587.7,"wordCount":8},{"id":"g4-s32","groupIndex":3,"groupLabel":"Conversation 1","answer":"Is it only South Africa that plays it?","start":587.93,"end":590.51,"wordCount":8},{"id":"g4-s33","groupIndex":3,"groupLabel":"Conversation 1","answer":"No, it’s also popular in Britain and in other former British colonies like Australia and New Zealand.","start":590.91,"end":599.14,"wordCount":17},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"My main problem is that my study folder is full of notes and worksheets, and is badly disorganized.","start":714.2,"end":723.1,"wordCount":18},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"I don’t know where to start.","start":723.28,"end":725.34,"wordCount":6},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, the main thing is to have everything in the right place.","start":726.4,"end":731.7,"wordCount":12},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"Whatever you’re reviewing, it’s important that it’s arranged for your particular needs of that subject, and in the most user-friendly way you can.","start":731.9,"end":741.77,"wordCount":24},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"What kind of learner are you?","start":742.08,"end":744.34,"wordCount":6},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, visual learners prefer using images, pictures, colors, and maps to organize information.","start":747.76,"end":755.94,"wordCount":13},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Logical learners have a linear mind and would rather use logic, reasoning and systems.","start":756.2,"end":763.63,"wordCount":14},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’m an emotional learner, which means I need to connect to information emotionally to understand it.","start":764.0,"end":770.88,"wordCount":16},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’m very much dependent on vision as a way of taking in information.","start":772.13,"end":777.28,"wordCount":13},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"As an emotional learner, I organize my notes into a story that I can connect to and recite to myself.","start":804.16,"end":812.2,"wordCount":20},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"I didn’t know there were so many different ways to learn.","start":814.08,"end":817.81,"wordCount":11},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Different people tend to be exposed to different forms of the golden rule, based on factors such as the religion in their society.","start":960.72,"end":970.52,"wordCount":23},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"However, all forms of the golden rule revolve around the same concept.","start":971.0,"end":976.64,"wordCount":12},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Namely, they help you treat others better, by using the way you yourself would want to be treated as a guide of how to behave.","start":977.07,"end":986.44,"wordCount":25},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"A notable criticism of the golden rule is that its application can lead to undesirable outcomes, when it conflicts with laws and ethical principles.","start":986.94,"end":998.6,"wordCount":24},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"For example, if someone breaks the law, the golden rule would suggest that we should let them go, because we would not want to be punished ourselves.","start":999.04,"end":1009.96,"wordCount":27},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"However, this issue with the golden rule can be dealt with in a general manner, by viewing this principle as one of several principles that we use to guide our behavior as individuals and as a society.","start":1010.62,"end":1026.1,"wordCount":37},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"Specifically, in the example described above, most individuals and societies choose to place laws and ethical principles above the golden rule.","start":1026.71,"end":1038.18,"wordCount":21},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"This means that they strive to implement the golden rule whenever possible, as long as it doesn’t clash with a more important concept.","start":1038.57,"end":1048.24,"wordCount":23},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"Many cultures place a much greater value on the spoken word than the American working culture does.","start":1347.06,"end":1355.34,"wordCount":17},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"A person’s word is linked to their honor, so verbal agreements are seen as important, whereas written contracts are taken as memos of understanding.","start":1363.71,"end":1376.12,"wordCount":24},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"Western working culture tends to place a high value on the written word, and this reaches its highest level of intensity when it comes to contracts.","start":1376.52,"end":1388.17,"wordCount":26}],"manualOnly":false},"2022-09-set1":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"These were a red meat diet which is primarily beef, a white meat diet which is mostly chicken and turkey, and a vegetarian protein diet.","start":62.46,"end":71.9,"wordCount":25},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Each diet period was four weeks.","start":72.24,"end":75.06,"wordCount":6},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Between the diet periods, participants had a break, during which they ate their regular foods.","start":75.2,"end":81.58,"wordCount":15},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"In addition, participants had blood tests at the start and finish of each new diet.","start":81.87,"end":88.21,"wordCount":15},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"The results showed that white and red meat diets had the same effects on blood cholesterol levels.","start":88.28,"end":94.88,"wordCount":17},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"Further, both diets increased blood cholesterol levels compared with the diet built on vegetarian protein sources.","start":94.98,"end":102.96,"wordCount":16},{"id":"g1-s12","groupIndex":0,"groupLabel":"News Report 1","answer":"This is because other effects of red meat consumption could contribute to heart disease independent of cholesterol.","start":111.24,"end":119.09,"wordCount":17},{"id":"g1-s13","groupIndex":0,"groupLabel":"News Report 1","answer":"Their main recommendations are that people eat less of both kinds of meat and more vegetarian protein.","start":119.09,"end":126.89,"wordCount":17},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"Hundreds of frozen turkeys were spilled all over the road.","start":182.38,"end":186.9,"wordCount":10},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"It is reported that nobody was hurt in the incident, but police said it may affect traffic and Christmas dinners.","start":187.58,"end":196.07,"wordCount":20},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"With just one week to go before Christmas, there are worries that local supermarket supplies of this holiday favorite may be affected.","start":196.33,"end":205.88,"wordCount":22},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"A police spokeswoman said that officers were currently in attendance at the scene.","start":206.26,"end":211.88,"wordCount":13},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"She stated that the driver of the lorry had been arrested on suspicion of dangerous driving.","start":212.12,"end":218.3,"wordCount":16},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"This year alone, there have been seven traffic accidents at this location.","start":223.58,"end":229.06,"wordCount":12},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"Thankfully, none of these accidents have resulted in serious injury.","start":229.49,"end":234.7,"wordCount":10},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"Hi, I wish to buy some cheese for a barbecue this weekend.","start":472.03,"end":476.65,"wordCount":12},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"Sorry, I don't know much about cheese.","start":478.14,"end":481.23,"wordCount":7},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"What type do you think would be suitable for a barbecue?","start":481.23,"end":484.87,"wordCount":11},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"For a barbecue, you could have any cheese you want.","start":486.4,"end":490.23,"wordCount":10},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"I imagine there will be different foods and people will just help themselves and eat at their own pace, right?","start":490.42,"end":497.59,"wordCount":20},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"We will just be a small group of friends gathering together at Washington Park.","start":501.28,"end":506.47,"wordCount":14},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"There will be around 20 of us, including children.","start":506.62,"end":510.34,"wordCount":9},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"So you could have different types of cheese.","start":511.51,"end":514.15,"wordCount":8},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"How much would you like to spend?","start":514.24,"end":516.36,"wordCount":7},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"I would suggest having at least one soft cheese and one hard cheese.","start":520.67,"end":525.82,"wordCount":13},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"That will offer you a good variety to suit different people's tastes.","start":525.83,"end":530.38,"wordCount":12},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"What's the difference between a soft cheese and a hard cheese?","start":532.04,"end":536.55,"wordCount":11},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"But generally speaking, soft cheeses are creamy and go well with sweet things like honey and jam.","start":538.32,"end":546.29,"wordCount":17},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"I would suggest something like this Spanish goat cheese.","start":546.52,"end":550.04,"wordCount":9},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's only $15, a very good price.","start":550.07,"end":554.06,"wordCount":7},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"You can spread it on bread with a knife, and then add a tiny bit of honey on top.","start":554.14,"end":560.49,"wordCount":19},{"id":"g4-s30","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, for hard cheese, I would recommend this Italian one here.","start":567.36,"end":572.4,"wordCount":11},{"id":"g4-s31","groupIndex":3,"groupLabel":"Conversation 1","answer":"It has a very strong smell and a dry flavor.","start":572.58,"end":576.26,"wordCount":10},{"id":"g4-s32","groupIndex":3,"groupLabel":"Conversation 1","answer":"You can cut it into thin slices and eat it on its own.","start":576.32,"end":580.52,"wordCount":13},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"In fact, research suggests that people who read printed text comprehend more, remember more and learn 30% more than those who read digital text.","start":720.91,"end":732.97,"wordCount":24},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"Students are able to highlight and edit text, write notes and search for information much more quickly than they can with printed textbooks.","start":741.82,"end":752.31,"wordCount":23},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"And what about all those trees that are cut down to make printed books?","start":752.35,"end":757.52,"wordCount":14},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Actually, manufacturing tablets is environmentally destructive and dangerous to human health.","start":757.76,"end":764.96,"wordCount":11},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"The health impacts from making one electronic reader are 70 times greater than those from making a single printed book.","start":765.06,"end":774.52,"wordCount":20},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"A lot of minerals are extracted from the earth to make electronic readers.","start":774.71,"end":779.76,"wordCount":13},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"When you visit the grocery store, you might draw conclusions about the cashier who checks you out.","start":964.11,"end":970.3,"wordCount":17},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Obviously, person perception is a very subjective process that can be affected by a number of variables, including the characteristics of the person you are observing, the context of the situation, your own personal traits, and your past experiences.","start":970.56,"end":988.86,"wordCount":39},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"One of the techniques we use in person perception is social categorization.","start":988.96,"end":994.21,"wordCount":12},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"In this process, we mentally categorize people into different groups based on common characteristics.","start":994.35,"end":1001.81,"wordCount":14},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Problems with this technique include the fact that it can lead to errors and prejudice.","start":1002.21,"end":1007.86,"wordCount":15},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"Imagine that you are getting on a bus.","start":1007.95,"end":1010.46,"wordCount":8},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"There are only two seats available.","start":1010.46,"end":1012.69,"wordCount":6},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"Results showed both groups of children were rated similarly on important social skills.","start":1142.12,"end":1148.32,"wordCount":13},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"They were also rated similarly on self-control, such as the ability to regulate their temper.","start":1154.78,"end":1161.33,"wordCount":16},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"In virtually every comparison made, ratings of social skills either remain constant or improved for the children born later.","start":1161.59,"end":1170.81,"wordCount":19},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"There was one exception: Social skills were slightly lower for children who accessed online games and social networking sites many times a day.","start":1171.05,"end":1181.65,"wordCount":23},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"Adults are worried when technological change starts to undermine traditional relationships, particularly the parent-child relationship.","start":1181.78,"end":1191.02,"wordCount":16},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Fears over screen-based technology represent the most recent panic in response to technological change.","start":1203.82,"end":1211.42,"wordCount":15},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"But overall, the study found little evidence that time spent on screens was hurting social skills for most children.","start":1211.57,"end":1220.3,"wordCount":19},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"You might learn something, but you don't actually have to do anything.","start":1320.17,"end":1324.43,"wordCount":12},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"Hearing about other people's success isn't the same as creating your own.","start":1324.56,"end":1329.5,"wordCount":12},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"Instead, it is through the process of active inspiration—the act of creating things, applying new ideas to our goals, and making mistakes—that we discover who we are and what is important to us.","start":1329.91,"end":1344.47,"wordCount":35},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"Furthermore, active inspiration is what results in long-term passion and enthusiasm.","start":1344.8,"end":1351.32,"wordCount":12},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"Watching someone else's success might leave you feeling excited for a few minutes.","start":1351.44,"end":1357.03,"wordCount":13},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Learning and listening can help you think about things in a different way.","start":1366.64,"end":1371.23,"wordCount":13},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"But creating, producing, and experimenting is what drives you forward.","start":1371.23,"end":1377.09,"wordCount":10},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Too often we spend our lives consuming the world around us instead of creating it.","start":1384.38,"end":1390.37,"wordCount":15},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"And what matters is the power your actions have to inspire you.","start":1390.64,"end":1394.86,"wordCount":12},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"The best inspiration comes from the application of ideas, not the consumption of them.","start":1395.08,"end":1401.15,"wordCount":14}],"manualOnly":false},"2022-12-set1":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"The dams are generally constructed using earth-fill and are gradually raised over time.","start":79.57,"end":85.65,"wordCount":14},{"id":"g2-s1","groupIndex":1,"groupLabel":"News Report 2","answer":"Two boys and four girls were born on Monday to the surprise of a young couple and doctors who had expected five babies.","start":158.36,"end":166.6,"wordCount":23},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"This was the first record of six babies being born at the same time in that region.","start":166.86,"end":172.62,"wordCount":17},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"The doctors prepared from early in the morning to help deliver five tiny citizens.","start":173.28,"end":179.23,"wordCount":14},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"They were in the operating room with five teams of doctors, one for each baby.","start":179.59,"end":185.08,"wordCount":15},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"The first five babies were delivered successfully, and all baby beds were occupied.","start":185.59,"end":191.85,"wordCount":13},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"And then all of a sudden, it turned out there was another waiting to come out.","start":192.15,"end":197.62,"wordCount":16},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"The doctor said the babies were in healthy condition, but could not go home immediately.","start":198.44,"end":204.09,"wordCount":15},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"The mother who is in stable condition could return home a day later if all physical tests came back normal.","start":210.8,"end":218.78,"wordCount":20},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"The new parents have yet to name the sixth baby but are considering either Lily or Rose.","start":229.93,"end":236.39,"wordCount":17},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"They come to enjoy its unspoiled beaches and crystal clear waters.","start":303.2,"end":307.85,"wordCount":11},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"Its natural beauty is protected as it lies inside a natural park.","start":308.55,"end":312.96,"wordCount":12},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"When the island was put up for sale, it was offered to the local government but proved too expensive for the local authorities.","start":323.91,"end":331.52,"wordCount":23},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"It is unclear whether the new owners have the power to ban tourists from the island.","start":332.14,"end":336.94,"wordCount":16},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"But with their newfound luxury comes the responsibility for its protection and maintenance.","start":337.36,"end":343.67,"wordCount":13},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"The island is less than two miles long and half a mile wide.","start":344.46,"end":348.54,"wordCount":13},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"It is said to have a remarkable location that few other private islands of this size can match, according to estate agents.","start":349.05,"end":357.08,"wordCount":22},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"Hi, I'm calling to ask about the newly scheduled gym classes.","start":472.12,"end":476.55,"wordCount":11},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm just wondering if I can get a discount on them.","start":476.55,"end":479.32,"wordCount":11},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, I signed up two months ago, but I haven't been to any of the group classes yet.","start":481.1,"end":486.6,"wordCount":18},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"Can I take your name please?","start":486.6,"end":488.2,"wordCount":6},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"And you signed up two months ago.","start":493.32,"end":495.2,"wordCount":7},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"Currently we are offering existing members discounts off two of our brand new classes, hot yoga, and advanced spinning, but the discount doesn't apply to any of our regular classes I'm afraid.","start":495.43,"end":508.92,"wordCount":32},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm only interested in the new classes.","start":509.03,"end":511.92,"wordCount":7},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"So how much of a discount is there on these two new classes?","start":511.92,"end":516.5,"wordCount":13},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's a shame you missed out on the general discount.","start":525.64,"end":528.42,"wordCount":10},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"But you can get 25% off if you sign up in advance.","start":529.6,"end":533.99,"wordCount":12},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"Which of the two classes are you thinking about?","start":534.43,"end":537.09,"wordCount":9},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, I guess I am only really interested in hot yoga.","start":537.09,"end":541.2,"wordCount":11},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"Can you sign me up for the 10-week course on Thursday evenings?","start":541.2,"end":545.02,"wordCount":13},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"Would you prefer to pay in advance?","start":546.16,"end":547.87,"wordCount":7},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"No, I don't like giving my card details over the phone anyway.","start":548.24,"end":552.43,"wordCount":12},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"We've got a bit of spare time now.","start":666.6,"end":668.95,"wordCount":8},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"Can we discuss the return trip to the head office?","start":668.95,"end":671.52,"wordCount":10},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've checked the availability of flights from Beijing to London on the 22nd and you have a choice.","start":672.36,"end":678.8,"wordCount":18},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've booked a room in a hotel about a mile from the office.","start":695.87,"end":699.44,"wordCount":13},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"The nearest metro station is Earl's Court.","start":699.44,"end":702.52,"wordCount":7},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"Can you find a map that shows where the hotel is and send it to me online?","start":704.26,"end":708.98,"wordCount":17},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've never been to the head office, you know.","start":709.25,"end":711.68,"wordCount":9},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"For the presentation, I'll bring my own laptop and hook it up to their projector.","start":718.03,"end":723.03,"wordCount":15},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you remember the capacity of their meeting room?","start":723.23,"end":726.12,"wordCount":9},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'll pay everything with my own card, right?","start":729.76,"end":732.94,"wordCount":8},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"And I'll submit my claims form afterwards.","start":732.96,"end":735.66,"wordCount":7},{"id":"g5-s28","groupIndex":4,"groupLabel":"Conversation 2","answer":"Just remember to keep all your receipts.","start":736.74,"end":739.02,"wordCount":7},{"id":"g5-s29","groupIndex":4,"groupLabel":"Conversation 2","answer":"You remember the trouble you had last time.","start":739.02,"end":741.67,"wordCount":8},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"A new study has demonstrated the importance of women's rights.","start":862.18,"end":866.58,"wordCount":10},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"The researchers behind the study state that many parts of the world have made good economic progress, but women's rights are often overlooked.","start":866.77,"end":876.35,"wordCount":23},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"Thus, they wanted to determine if there was a link between protection of women's rights and public health.","start":876.68,"end":883.23,"wordCount":18},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"Countries were classified according to the respect they gave to women's economic and social rights.","start":894.73,"end":901.02,"wordCount":15},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"They were high, moderate, and poor.","start":903.58,"end":906.51,"wordCount":6},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Analysis of the data showed that countries with strong women's rights had better health than those where women's rights were not as respected.","start":906.95,"end":916.15,"wordCount":23},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"The health indicators studied included disease prevention, reproductive health, death rates, and life expectancy.","start":916.54,"end":925.49,"wordCount":14},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"Furthermore, in countries where women's rights were most respected, but where access to hospitals and doctors was below average, health outcomes were still better than in countries rated as moderate or poor.","start":926.26,"end":939.52,"wordCount":32},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"This confirms that even with a lack of resources, if a country has strong women's rights, the health outcomes are better.","start":939.8,"end":948.36,"wordCount":21},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"It is also a development issue.","start":954.24,"end":956.51,"wordCount":6},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"This is because better health aids economic development.","start":957.07,"end":960.54,"wordCount":8},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"They note that the value of women's rights has often been questioned from an economic standpoint.","start":960.83,"end":966.74,"wordCount":16},{"id":"g6-s16","groupIndex":5,"groupLabel":"Passage 1","answer":"Some have argued that ensuring those rights would limit progress, but this study indicates the opposite.","start":966.95,"end":973.86,"wordCount":16},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"Sunshine can stop you from sweating, too.","start":1084.54,"end":1087.34,"wordCount":7},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"The body's normal temperature is 36 to 37 degrees centigrade.","start":1087.96,"end":1092.94,"wordCount":10},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"At that point, your heat regulatory system can essentially quit, which stops you from sweating as your body tries to keep water around your vital organs.","start":1100.67,"end":1111.65,"wordCount":26},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"However, the sun can have a positive influence on your body by raising your energy levels.","start":1112.24,"end":1117.96,"wordCount":16},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"You might feel like the sun is giving you extra energy for your day, which is actually happening.","start":1118.24,"end":1123.84,"wordCount":18},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"And vitamin D from sunshine can help your body to absorb certain minerals, which are linked to building stronger bones.","start":1124.4,"end":1131.95,"wordCount":20},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"Therefore, I suggest you spend more time in the park with your friends, but make sure you apply lots of skin protection and fill up those water bottles, too.","start":1132.59,"end":1142.73,"wordCount":29},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"No one understands the reason for this.","start":1264.02,"end":1266.54,"wordCount":7},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Left-handed people may think differently.","start":1267.24,"end":1269.83,"wordCount":6},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Left-handed people were more likely to prefer the images on the left.","start":1279.07,"end":1283.45,"wordCount":13},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Right-handed people preferred the ones on the right.","start":1284.03,"end":1287.07,"wordCount":9},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Both groups disliked stuff on their opposite side.","start":1287.44,"end":1291.22,"wordCount":8},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"Left-handers are also overrepresented in professional, interactive sports.","start":1291.79,"end":1296.87,"wordCount":9},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"Researchers have looked at the influence of being left-handed on performance and interactive sports.","start":1297.16,"end":1302.79,"wordCount":15},{"id":"g8-s18","groupIndex":7,"groupLabel":"Passage 3","answer":"So if you have a left-handed child, you should encourage them to play table tennis, baseball and tennis.","start":1308.67,"end":1315.87,"wordCount":19},{"id":"g8-s19","groupIndex":7,"groupLabel":"Passage 3","answer":"Being left-handed maximizes their chances of success in these sports.","start":1316.02,"end":1320.85,"wordCount":11}],"manualOnly":false},"2022-12-set2":{"clips":[{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Also, a free shuttle bus will run between the event car parks and the competition site.","start":69.41,"end":75.22,"wordCount":16},{"id":"g1-s11","groupIndex":0,"groupLabel":"News Report 1","answer":"The event first took place in Glasgow in 1948.","start":94.44,"end":98.34,"wordCount":9},{"id":"g1-s12","groupIndex":0,"groupLabel":"News Report 1","answer":"It has been held regularly in Glasgow since 1986.","start":98.34,"end":102.82,"wordCount":9},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"The most significant concern here is how early this is all happening.","start":189.7,"end":194.75,"wordCount":12},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"Greenland experiences annual ice melt and growth cycles.","start":194.75,"end":199.08,"wordCount":8},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"But this year, the melting season began in early May.","start":199.08,"end":202.9,"wordCount":10},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"That's a month earlier than normal and something that's happened only once before in the historical record in 2016.","start":203.35,"end":212.66,"wordCount":19},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"Longer melt seasons like this one seem to lead to much greater contributions to sea-level rise than in previous decades.","start":222.39,"end":231.31,"wordCount":21},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"The latest discovery was on Monday, meaning four of these cash bundles have been handed in this year and 13 since 2014.","start":299.06,"end":308.38,"wordCount":22},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"A Durham Police spokesperson said the money has been returned to the lucky finders in all cases except yesterday.","start":323.28,"end":330.38,"wordCount":19},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"He told The Northern Echo: \" It isn't an affluent part of the world, so for them to find cash of that amount and instantly think about taking it to the police stations shows the community spirit there is.","start":342.94,"end":356.05,"wordCount":38},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"Many begin to search for the meaning of their existence, leading to behaviors such as ending or starting a relationship, or plans, like starting a vigorous diet or fitness program.","start":480.0,"end":492.05,"wordCount":30},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"I have wonderful friends and I love celebrating their birthdays.","start":492.05,"end":496.5,"wordCount":10},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"It seems to trigger a type of social anxiety.","start":502.12,"end":505.48,"wordCount":9},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"I think social media too can intensify things as birthdays now play out more publicly.","start":505.48,"end":511.56,"wordCount":15},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"Birthday reminders can be helpful, but I kind of worry I won't be able to drum up my own day and show it to look as exciting as it is supposed to be.","start":511.61,"end":520.8,"wordCount":33},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, to deal with the birthday blues, you should not isolate yourself.","start":520.8,"end":525.59,"wordCount":12},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's best to gradually face your birthday with people you trust.","start":525.61,"end":529.96,"wordCount":11},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"That would help you learn self-acceptance, or that it's okay to be the focus.","start":529.96,"end":535.15,"wordCount":15},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"Or I could perceive my birthday as an opportunity to do something for others like asking people to make a donation instead of buying a gift.","start":536.28,"end":544.78,"wordCount":26},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"Or even simply see your birthday as an opportunity to bring people together for them to have fun.","start":546.04,"end":552.39,"wordCount":18},{"id":"g5-s1","groupIndex":4,"groupLabel":"Conversation 2","answer":"The metro was absolutely terrible this morning.","start":641.11,"end":644.78,"wordCount":7},{"id":"g5-s3","groupIndex":4,"groupLabel":"Conversation 2","answer":"No, but the train was so packed that I could barely move, and it was difficult to breathe too.","start":646.52,"end":652.88,"wordCount":19},{"id":"g5-s4","groupIndex":4,"groupLabel":"Conversation 2","answer":"At every station, more people squeezed in and I got pushed further and further inside.","start":652.88,"end":658.84,"wordCount":15},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"When I got to my station, I could hardly get out.","start":658.84,"end":661.62,"wordCount":11},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"Once I did get out, I was totally exhausted.","start":661.62,"end":664.89,"wordCount":9},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"Why didn't you take the bus?","start":667.02,"end":668.77,"wordCount":6},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"The bus takes twice as long and it's just as crowded.","start":668.77,"end":672.59,"wordCount":11},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've got a driver's license, but that's all.","start":676.31,"end":679.21,"wordCount":8},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm saving up to buy something reasonably small and cute, but it's still a bit expensive for me, and it'll take a while before I have enough money.","start":679.21,"end":688.22,"wordCount":28},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"Have you thought about getting an electric motorbike?","start":688.22,"end":690.91,"wordCount":8},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"But honestly, I've just seen too many horrible accidents involving those dangerous monsters.","start":693.9,"end":700.61,"wordCount":13},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"You could register to use one.","start":703.06,"end":704.87,"wordCount":6},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"There are always several of those bikes out in front of our apartment complex.","start":707.23,"end":711.86,"wordCount":14},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"Or you could just walk to work.","start":711.86,"end":713.94,"wordCount":7},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"But you've given me a thought.","start":718.23,"end":720.04,"wordCount":6},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"I could take a change of clothes and jog to work.","start":720.04,"end":723.31,"wordCount":11},{"id":"g5-s29","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, that's an expensive way to get to work.","start":731.88,"end":735.19,"wordCount":9},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"Being a deaf person in tech required a huge amount of effort in organization.","start":860.82,"end":866.96,"wordCount":14},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"Because there was no email or text message service, everything had to be done face to face, or by telephone.","start":867.28,"end":874.54,"wordCount":20},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Communicating in meetings was very difficult.","start":874.61,"end":877.85,"wordCount":6},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"He needed a sign language interpreter for every meeting, but it was a huge effort to coordinate.","start":877.85,"end":883.75,"wordCount":17},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"These days, although challenges still remain, it's a good time to be a deaf person in tech, says Miller.","start":884.06,"end":890.94,"wordCount":19},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"Big advances in speech recognition technology have enabled communication tools to turn live speech into text in real time on your smartphone or laptop, and sign language into text as well.","start":891.23,"end":905.14,"wordCount":31},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"New Tech coupled with improvements in hearing aid technology and medical advances means that Miller is able to focus far more on his work.","start":905.3,"end":914.94,"wordCount":24},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"He has benefited to a great extent from a tiny hearing device in his ear.","start":915.25,"end":919.96,"wordCount":15},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"It gives him a degree of hearing, and he can use a variety of communication methods depending on the situation.","start":920.06,"end":926.94,"wordCount":20},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"He can employ lip-reading and have meetings via video instead of on the phone.","start":927.03,"end":932.58,"wordCount":15},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"These things have made a huge difference.","start":932.74,"end":935.52,"wordCount":7},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"He no longer has to worry about whether or not he can understand.","start":935.58,"end":939.61,"wordCount":13},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"He can just concentrate on how interesting the meeting might be and what he needs to get out of it in order to progress.","start":939.64,"end":947.15,"wordCount":24},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"Pure white walls simply don't do that.","start":1032.39,"end":1035.47,"wordCount":7},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"Another interior designer commented that certain combinations can key into something on a deeper level, transporting you to a different moment in time.","start":1037.34,"end":1047.01,"wordCount":23},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"If it gives you joy every time you open the cupboard, you can start to take it further.","start":1073.05,"end":1078.16,"wordCount":18},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"Additionally, a painted ceiling is a magical thing without being too obvious and can affect how the space feels as well.","start":1098.26,"end":1107.22,"wordCount":21},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"Parents often hear that reading to their children is critical for supporting development, and the message is getting through to them.","start":1177.2,"end":1185.24,"wordCount":21},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"So what does this mean for parents?","start":1263.31,"end":1265.69,"wordCount":7},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Not all books are created equal, so parents need to choose the books they share with their children with great care.","start":1265.83,"end":1273.58,"wordCount":21}],"manualOnly":false},"2023-03-set1":{"clips":[{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Currently, 13 African countries have visa-free deals in place with each other.","start":65.67,"end":71.37,"wordCount":13},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"These allow citizens to visit another country without a visa.","start":71.83,"end":75.8,"wordCount":10},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"Some countries offer visas on arrival.","start":76.59,"end":79.19,"wordCount":6},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"In contrast, Americans are able to travel to 20 of the continent's countries without a visa, or secure a visa on arrival.","start":79.49,"end":88.86,"wordCount":22},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"The African Union, which represents 54 states, wants to abolish the requirement of a visa for Africans visiting other African countries.","start":89.63,"end":99.51,"wordCount":21},{"id":"g1-s11","groupIndex":0,"groupLabel":"News Report 1","answer":"It also wants to establish a free-trade deal across the continent in the near future, as trade within the African continent costs more than any other region.","start":99.85,"end":110.19,"wordCount":28},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"The gas turned into solid in just two years, much faster than the hundreds or thousands of years researchers had predicted.","start":203.31,"end":211.62,"wordCount":21},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"Firstly, the association cited changing diets, in particular the switch to those low in calories, as a factor in the reduction of bread consumption.","start":316.53,"end":327.82,"wordCount":24},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"This could explain why the difference in consumption between genders is so big.","start":328.76,"end":333.75,"wordCount":13},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"The second reason, they say, is lifestyle changes in the country, with people dedicating less time to breakfast when bread would traditionally be eaten with butter and jam.","start":344.91,"end":356.75,"wordCount":28},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, I'd like to book two train tickets to London tomorrow morning, please.","start":469.52,"end":474.67,"wordCount":13},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, after the rush hour, I think.","start":476.99,"end":479.64,"wordCount":7},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"Then you can walk down through the train to your carriage and take your seats.","start":542.24,"end":546.26,"wordCount":15},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"When you arrive in London, hand the ticket to the guard and he will return the bicycles to you.","start":546.5,"end":551.73,"wordCount":19},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"It's located in what used to be a hat factory.","start":661.72,"end":664.94,"wordCount":10},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"But fashion changed and most people stopped wearing hats.","start":672.37,"end":676.28,"wordCount":9},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"So practically all of those factories had to close down.","start":676.53,"end":680.11,"wordCount":10},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"Is there enough demand for that?","start":700.03,"end":701.94,"wordCount":6},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"I would have thought that in London most people don't speak foreign languages.","start":702.17,"end":706.79,"wordCount":13},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"London is a very large and international city.","start":713.49,"end":716.73,"wordCount":8},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"There are lots of people interested in watching such movies.","start":716.73,"end":720.41,"wordCount":10},{"id":"g5-s26","groupIndex":4,"groupLabel":"Conversation 2","answer":"Furthermore, I might add, all movies come with English text at the bottom of the screen.","start":720.53,"end":726.14,"wordCount":16},{"id":"g5-s27","groupIndex":4,"groupLabel":"Conversation 2","answer":"So even if you don't understand what the actors say, you can still read it.","start":726.19,"end":730.84,"wordCount":15},{"id":"g5-s29","groupIndex":4,"groupLabel":"Conversation 2","answer":"What movie are you showing right now?","start":732.43,"end":734.69,"wordCount":7},{"id":"g5-s30","groupIndex":4,"groupLabel":"Conversation 2","answer":"This week, we're showing a musical from Pakistan.","start":734.69,"end":737.82,"wordCount":8},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Love them or hate them, smartphones have become an integral part of our daily lives.","start":855.89,"end":861.53,"wordCount":15},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"But should they be left outside the classroom?","start":861.64,"end":864.46,"wordCount":8},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"Nick Gibb, minister for school standards in England, believes schools should ban their pupils from bringing in smartphones.","start":865.01,"end":873.09,"wordCount":18},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Astrid Natley, a secondary school math teacher, incorporates phones into her classroom.","start":873.77,"end":880.07,"wordCount":12},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"\"My school doesn't have money for tablets,\" she says.","start":880.44,"end":883.94,"wordCount":9},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"\"When students use their phones for research, they learn they have a powerful tool in their hands.","start":884.0,"end":889.73,"wordCount":17},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Meanwhile, Helen Lockhart, a registered nurse working for community education, supports a complete ban.","start":895.16,"end":902.77,"wordCount":14},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"\"I'm banned from mobile use at work, and my phone must be handed in.","start":903.05,"end":907.55,"wordCount":14},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"Richard Stone, an English teacher, thinks there should be a clear separation between school and home.","start":920.87,"end":926.75,"wordCount":16},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"\"Students should do things differently in the two environments.","start":926.86,"end":930.32,"wordCount":9},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"Children are getting more than enough screen time in their lives without the need to bring their phone into the classroom.","start":930.57,"end":936.55,"wordCount":21},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"The internet is too easy and too unreliable a research tool, so let's leave phones and laptops at home, and show them a different world in their lessons—one of books and pens,\" he says.","start":936.93,"end":950.23,"wordCount":35},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"When the packages arrived, Kate wanted to open them, but her parents said no.","start":1081.99,"end":1087.45,"wordCount":14},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"Instead of sending back the dolls, her father suggested giving them to the local children's hospital.","start":1087.61,"end":1093.44,"wordCount":16},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"So the next week, Kate's family loaded up their car and took all the dolls to the playroom at the children's hospital.","start":1093.88,"end":1100.93,"wordCount":22},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"She had a lot of fun and learned a really good lesson.","start":1111.38,"end":1115.01,"wordCount":12},{"id":"g8-s4","groupIndex":7,"groupLabel":"Passage 3","answer":"Those who are relatively old compared to their classmates have certain advantages over them.","start":1200.0,"end":1205.42,"wordCount":14},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"Previous research has found older students achieve better results.","start":1205.93,"end":1210.6,"wordCount":9},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"They are also more likely to attend university and become professional athletes, chief executives and even important politicians.","start":1210.9,"end":1220.23,"wordCount":18},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"But the Australian researchers wanted to discover what was driving these differences.","start":1220.77,"end":1226.2,"wordCount":12},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"They suspected older, more mature students obtained more self-confidence than their peers because they achieved better grades.","start":1226.66,"end":1235.1,"wordCount":18},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"To test this out, they conducted two studies.","start":1235.84,"end":1239.21,"wordCount":8},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"In the first study, more than 600 high-school students were surveyed about their tendency to take risks and feel confident.","start":1249.39,"end":1257.39,"wordCount":21},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"In the second study, those born on both sides of the cutoff date for starting school, were asked to complete online math questions and rate their performance.","start":1257.97,"end":1268.16,"wordCount":27},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"They were also asked about the risks they took while riding bicycles and managing their finances.","start":1268.71,"end":1274.99,"wordCount":16},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"While risk-taking can be considered a negative attribute, it's also a characteristic of successful people, including athletes, political leaders and entrepreneurs.","start":1281.71,"end":1293.87,"wordCount":22}],"manualOnly":false},"2023-06-set1":{"clips":[{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"\"Who would have known just loving animals gets you that much trouble,\" she said.","start":64.43,"end":69.67,"wordCount":14},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"It is prohibited to feed any wild animals including birds in Rhode Island City.","start":70.09,"end":75.88,"wordCount":14},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"Nevertheless, while the woman's intention was to feed birds, it is clear that rats were also benefiting.","start":75.95,"end":84.04,"wordCount":17},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"He said it will take months to get the problem under control.","start":92.17,"end":96.31,"wordCount":12},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Some plants will be grown, but not potatoes like in the movie The Martian.","start":183.27,"end":188.5,"wordCount":14},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"The requirements are strict, including a master's degree in a science, engineering or math field or pilot experience.","start":204.88,"end":214.55,"wordCount":18},{"id":"g2-s14","groupIndex":1,"groupLabel":"News Report 2","answer":"Applicants must be between 30 and 55 and in good physical health.","start":219.93,"end":225.83,"wordCount":12},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"However, it is only for the winners themselves, not others.","start":316.24,"end":320.83,"wordCount":10},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"Goto, however, has accepted the International Olympic Committee's offer of a replacement, according to Japanese media reports.","start":334.44,"end":343.19,"wordCount":17},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"The scene broadcast on television prompted thousands of complaints to city hall.","start":343.42,"end":349.05,"wordCount":12},{"id":"g3-s13","groupIndex":2,"groupLabel":"News Report 3","answer":"\"I handle my own gold medal so gently that I would not scratch it.\"","start":364.09,"end":368.91,"wordCount":14},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"What's that orange thing on your computer screen?","start":464.92,"end":467.93,"wordCount":8},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's a plastic sheet that blocks blue light.","start":469.78,"end":472.72,"wordCount":8},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"I have one that I use to cover my phone screen too.","start":472.72,"end":475.93,"wordCount":12},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"What do you mean by blue light?","start":476.13,"end":478.97,"wordCount":7},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"So blue light is harmful and that's why you want to block it.","start":490.62,"end":494.88,"wordCount":13},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"Blue light isn't necessarily bad for us.","start":496.49,"end":499.63,"wordCount":7},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"In fact, we need blue light during the day to be healthy.","start":499.63,"end":503.15,"wordCount":12},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"But too much blue light, especially from electronic devices, can harm our health by weakening our vision and making it harder for us to fall asleep.","start":503.27,"end":512.47,"wordCount":26},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"And poor sleep can cause all sorts of health problems.","start":512.48,"end":516.26,"wordCount":10},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm not so sure that sleep is nearly as important as people always say it is.","start":516.4,"end":522.05,"wordCount":16},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"I haven't slept enough in months because I have too much work to do, and I feel fine.","start":522.26,"end":529.14,"wordCount":18},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"And it's the same for most of my friends.","start":529.14,"end":531.75,"wordCount":9},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"Poor sleep might be a problem for older people, but surely young people can handle late nights.","start":531.97,"end":538.57,"wordCount":17},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, the research I've read shows that sleep is probably even more important than we thought, and that not having enough sleep can contribute to serious health problems like obesity and heart disease.","start":538.62,"end":551.51,"wordCount":33},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"And all the artificial blue light from electronic devices means we have to try harder to sleep well.","start":551.76,"end":558.28,"wordCount":18},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm on my computer very late most nights, and that's probably why I don't sleep enough.","start":560.01,"end":565.28,"wordCount":16},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"And I'm tired of people asking that question of my 10-year-old daughter.","start":662.99,"end":667.4,"wordCount":14},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"My daughter's stock answers are basketball player, pop singer, mechanical engineer.","start":667.54,"end":674.12,"wordCount":11},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"Adults love that last one, as it's the perfect mix of the sensible and the ambitious.","start":674.33,"end":680.57,"wordCount":16},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"When she was much younger, my daughter used to say she wanted to be Queen of the Clouds, which I loved.","start":680.69,"end":687.55,"wordCount":21},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"That's the kind of goal-setting I like to see in children, springing from their boundless imaginations.","start":687.83,"end":694.66,"wordCount":17},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"And we teach a very gloomy image of adulthood—that whatever our children's future holds, it must be seen within the context of a job.","start":700.49,"end":709.53,"wordCount":25},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"We can't dismiss the idea that teenagers have to plan to do something after they finish school, and parents are entitled to hope it's more than simply spending 10 hours a day playing computer games.","start":722.09,"end":734.42,"wordCount":35},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"But asking \"What do you want to be?\"","start":734.62,"end":737.17,"wordCount":8},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"We should be helping our kids understand who they are, even if that means letting go of who we think they should be.","start":745.93,"end":753.25,"wordCount":23},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Certain companies have started selling simple smartphones for only $ 20.","start":906.93,"end":912.06,"wordCount":10},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"Previously, the lowest price had been around $ 40, well out of reach for many people.","start":912.06,"end":918.21,"wordCount":15},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Most companies are trying to make phones ever more powerful and capable.","start":926.57,"end":931.28,"wordCount":12},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"It made every effort to keep the essential capabilities of smartphones, but strip out costs and preserve battery life for people who likely have inadequate access to electricity.","start":934.09,"end":946.03,"wordCount":28},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"Instead of a touchscreen, they're controlled with an old-school keypad.","start":962.88,"end":967.75,"wordCount":11},{"id":"g7-s1","groupIndex":6,"groupLabel":"Passage 2","answer":"For years, using recycled plastic to make plastic products was cheap.","start":1059.76,"end":1065.3,"wordCount":11},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"By contrast, fossil fuel plastic was more expensive.","start":1065.52,"end":1069.88,"wordCount":8},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"But now it is cheaper for major manufacturers to use new plastic.","start":1075.03,"end":1080.2,"wordCount":12},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"This may be because of consumer demands.","start":1090.87,"end":1093.9,"wordCount":7},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"They are pushing for more recycled plastics in new products.","start":1093.9,"end":1098.3,"wordCount":10},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"Meanwhile, new plastic is becoming cheaper.","start":1098.49,"end":1101.89,"wordCount":6},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"Smaller manufacturers may also be forced to use new plastic to reduce costs.","start":1117.15,"end":1122.97,"wordCount":13},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Plastic packaging makers are being pressured to use more recycled plastic.","start":1131.29,"end":1136.79,"wordCount":11},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"This is done in hopes of reducing the enormous amount of plastic pollution in the oceans.","start":1136.79,"end":1142.76,"wordCount":16},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"The UK government plans to tax companies which don't use at least 30% recycled plastic in their products.","start":1143.5,"end":1152.21,"wordCount":18},{"id":"g7-s16","groupIndex":6,"groupLabel":"Passage 2","answer":"Additionally, the government is planning to increase the quantity of recycled plastic in the market.","start":1152.45,"end":1158.74,"wordCount":15},{"id":"g7-s17","groupIndex":6,"groupLabel":"Passage 2","answer":"This could mean incentives for new recycling plants.","start":1159.24,"end":1162.98,"wordCount":8},{"id":"g7-s18","groupIndex":6,"groupLabel":"Passage 2","answer":"Additionally, recycling facilities may be improved at a local council level and recycled plastic could be imported.","start":1163.07,"end":1171.2,"wordCount":17},{"id":"g7-s19","groupIndex":6,"groupLabel":"Passage 2","answer":"This would help increase the amount of recycled plastic in circulation.","start":1171.43,"end":1176.49,"wordCount":11},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"It sells the idea of the nap as much as the nap itself.","start":1264.24,"end":1268.53,"wordCount":13},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"Here, at this point in the argument, it's traditional for me to bring up all the studies that show the benefits of napping.","start":1275.54,"end":1282.43,"wordCount":23},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"But do you really need experts to tell you that?","start":1282.6,"end":1285.71,"wordCount":10},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"I've been working from home for more than 10 years now.","start":1290.01,"end":1293.24,"wordCount":11},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"And the quality and quantity of work I can do emerges directly from my ability to concentrate.","start":1293.24,"end":1299.31,"wordCount":17},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"I don't understand how people have creative careers without napping.","start":1299.31,"end":1303.95,"wordCount":10}],"manualOnly":false},"2023-06-set2":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"The snake was eventually captured by the local animal handlers and taken to an animal hospital afterward.","start":60.08,"end":67.04,"wordCount":17},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"It was being treated for an outer skin infection.","start":67.04,"end":70.08,"wordCount":9},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"It was unclear who the owner was.","start":70.08,"end":72.86,"wordCount":7},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"The snake may be taken to a local zoo for care if the owner does not come forward.","start":72.86,"end":78.39,"wordCount":18},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"Over the years, other creatures like frogs and fish have found their way into toilets.","start":78.56,"end":84.37,"wordCount":15},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"But this was the first instance of a snake in recent years.","start":84.39,"end":88.7,"wordCount":12},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"And before she knew it, she had done 20 weeks.","start":184.41,"end":188.74,"wordCount":10},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"Explaining why she has kept up the videos, Andrea explained how nice it was to have a little bit of fun and craziness that made people smile.","start":188.92,"end":198.43,"wordCount":27},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"The board has messages of kindness like, \"If you want more kindness in the world, put it here.\"","start":301.09,"end":307.25,"wordCount":18},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"There have been no reports of anyone taking advantage of the situation.","start":315.05,"end":319.09,"wordCount":12},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"In fact, there are a lot more people giving tickets than receiving.","start":319.09,"end":323.51,"wordCount":12},{"id":"g3-s12","groupIndex":2,"groupLabel":"News Report 3","answer":"It seems people want to help and are driven by helping others.","start":323.51,"end":327.7,"wordCount":12},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"Our question today is why friends suddenly disappear.","start":441.03,"end":445.52,"wordCount":8},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"They may block us on their social media accounts and stop responding to our emails.","start":445.52,"end":450.84,"wordCount":15},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"They simply vanish without a trace.","start":450.84,"end":453.84,"wordCount":6},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"When there is a relationship breakdown with their parents, children with an anxious attachment style scream and cry to get their parents to come back.","start":470.3,"end":478.41,"wordCount":25},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"But other children simply shut down and try to deal with their emotions by ignoring the situation.","start":478.5,"end":484.61,"wordCount":17},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"And these attachment styles carry on into adulthood.","start":484.61,"end":488.18,"wordCount":8},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"Does avoidance reduce their stress levels?","start":488.18,"end":491.53,"wordCount":6},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"Their stress levels are actually the same as those experienced by the children who yell and scream.","start":492.56,"end":497.5,"wordCount":17},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"And it's a very insecure attachment.","start":501.96,"end":504.76,"wordCount":6},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"How does an insecure attachment affect relationships between friends, co-workers and romantic relationships?","start":504.76,"end":512.15,"wordCount":14},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"So if you have a disagreement with a securely attached person, they're not going to panic.","start":513.84,"end":520.54,"wordCount":16},{"id":"g4-s26","groupIndex":3,"groupLabel":"Conversation 1","answer":"However, an insecurely attached person won't.","start":526.29,"end":530.32,"wordCount":6},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"They might either attack you, get defensive, or just disappear from your life.","start":530.34,"end":535.69,"wordCount":13},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"To them, a difference, no matter how small in your eyes, signals the end of the relationship.","start":535.69,"end":542.14,"wordCount":17},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"That explains why they suddenly disappear.","start":542.38,"end":545.51,"wordCount":6},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"I would have thought America made the best jeans because it's a typical American garment.","start":667.91,"end":673.12,"wordCount":15},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"It's a slower process of making clothing.","start":683.75,"end":686.41,"wordCount":7},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"But the end result is surely superior.","start":686.49,"end":689.53,"wordCount":7},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"Also, the fabric they use is of a higher quality and the dyes are natural.","start":689.77,"end":695.29,"wordCount":15},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"What size do you want and how much are they?","start":702.41,"end":704.93,"wordCount":10},{"id":"g5-s28","groupIndex":4,"groupLabel":"Conversation 2","answer":"But make double certain they are made in Japan.","start":714.92,"end":718.34,"wordCount":9},{"id":"g5-s31","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you typically spend that much on a pair of casual trousers?","start":721.98,"end":726.03,"wordCount":12},{"id":"g5-s35","groupIndex":4,"groupLabel":"Conversation 2","answer":"I think they're totally worth it.","start":736.47,"end":738.38,"wordCount":6},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Every time I walk out of a superhero movie, I feel the same way.","start":862.57,"end":866.99,"wordCount":14},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"The desire for adventure is a human one.","start":872.47,"end":875.29,"wordCount":8},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Superhero films capture this desire perfectly.","start":875.29,"end":879.0,"wordCount":6},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"The plot of each superhero film has become relatively predictable: the world is in peril, the world needs a hero, the hero is in peril, the hero resolves the peril, the hero saves the world.","start":879.24,"end":892.56,"wordCount":35},{"id":"g7-s1","groupIndex":6,"groupLabel":"Passage 2","answer":"Telling stories is one of the most powerful means leaders have to influence, teach and inspire.","start":1038.96,"end":1046.84,"wordCount":16},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"When it comes to our countries, our communities, and our families, we understand instinctively that the stories we hold in common are an important part of the ties that bind.","start":1050.74,"end":1063.36,"wordCount":30},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"Good stories do more than create a sense of connection.","start":1078.35,"end":1082.18,"wordCount":10},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"They allow the listener to enter the story, making them more open to learning.","start":1085.31,"end":1090.18,"wordCount":14},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"Good stories can contain multiple meanings, so they're surprisingly economical in conveying complex ideas in graspable ways.","start":1090.43,"end":1099.67,"wordCount":17},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"And stories are more engaging than the recital of data points or a discussion of abstract ideas.","start":1099.93,"end":1106.86,"wordCount":17},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"Stories about professional mistakes and what leaders learned from them are another great avenue for learning.","start":1107.11,"end":1114.19,"wordCount":16},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"Because people identify so closely with stories, they can imagine how they would have acted in similar circumstances.","start":1114.42,"end":1122.07,"wordCount":18},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"They're able to work through situations in a way that's risk free.","start":1122.15,"end":1126.6,"wordCount":12},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"There are extra benefits for leaders: with a simple personal story, they can convey fundamental values.","start":1126.93,"end":1134.6,"wordCount":16},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"On two key measures of financial performance, immigrants outperform native-born Americans.","start":1225.86,"end":1232.4,"wordCount":12},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"Immigrants aren't just becoming entrepreneurs more frequently.","start":1245.22,"end":1249.11,"wordCount":7},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"Over 40% of Fortune 500 companies had a founder who was either an immigrant or the child of one.","start":1250.9,"end":1258.98,"wordCount":19},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"Another key measure of financial strength is debt level.","start":1259.3,"end":1263.63,"wordCount":9},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Immigrants do better in this area too.","start":1263.81,"end":1266.83,"wordCount":7},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"This can be compared to just 19% of the general population.","start":1288.14,"end":1293.47,"wordCount":11},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"Why are immigrants doing so well?","start":1293.83,"end":1296.66,"wordCount":6},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"The values and habits they bring from their own homelands help explain some of the success.","start":1296.66,"end":1302.55,"wordCount":16},{"id":"g8-s17","groupIndex":7,"groupLabel":"Passage 3","answer":"Unemployment tends to be higher in developing countries.","start":1302.77,"end":1307.05,"wordCount":8},{"id":"g8-s18","groupIndex":7,"groupLabel":"Passage 3","answer":"That means more people must become entrepreneurs.","start":1307.15,"end":1310.47,"wordCount":7},{"id":"g8-s19","groupIndex":7,"groupLabel":"Passage 3","answer":"Credit is also scarcer in most developing countries.","start":1310.54,"end":1314.82,"wordCount":8},{"id":"g8-s20","groupIndex":7,"groupLabel":"Passage 3","answer":"This means individuals must save more in order to achieve their goals, or they borrow money from friends and family rather than a bank.","start":1314.91,"end":1324.4,"wordCount":24}],"manualOnly":false},"2023-12-set1":{"clips":[{"id":"g1-s1","groupIndex":0,"groupLabel":"News Report 1","answer":"Have you noticed how similar you are to your friends?","start":108.78,"end":111.96,"wordCount":10},{"id":"g1-s2","groupIndex":0,"groupLabel":"News Report 1","answer":"It may be because your brains operate in harmony with each other.","start":112.09,"end":116.46,"wordCount":12},{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"We know that friends are more likely to be the same age, gender and ethnic background as each other.","start":116.93,"end":124.02,"wordCount":19},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Some people might find a romantic scene touching, for instance, while others would feel it was embarrassing.","start":139.02,"end":145.68,"wordCount":17},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"The activity of friends' brains was more similar than that of people who didn't know each other, particularly in regions involved in attention, emotion and language.","start":146.29,"end":158.47,"wordCount":26},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"This similarity was strong enough that it could be used to predict whether two people were already friends or not.","start":158.9,"end":166.32,"wordCount":20},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"The relationship probably goes two ways.","start":167.02,"end":170.04,"wordCount":6},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"We are drawn to people who think like us; we then influence their thoughts over time, which may push their brain activity into more closely resembling our own.","start":170.23,"end":182.42,"wordCount":28},{"id":"g2-s1","groupIndex":1,"groupLabel":"News Report 2","answer":"Two men who have been best friends for 60 years have just realized they are actually brothers.","start":235.62,"end":242.88,"wordCount":17},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"They have been best friends ever since.","start":251.1,"end":253.92,"wordCount":7},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"So recently, they made separate attempts on DNA matching websites to discover more about their ancestry.","start":261.85,"end":269.44,"wordCount":16},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"The pair were born to the same mother 15 months apart.","start":285.91,"end":290.36,"wordCount":11},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"The beach was not as nice or beautiful as it should be.","start":369.09,"end":372.56,"wordCount":12},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"He felt so sad to see such a gorgeous place littered with so much trash.","start":372.66,"end":377.24,"wordCount":15},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"Thus, he and his friends decided to grab a few trash bags and clean it all up.","start":377.76,"end":383.35,"wordCount":17},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"A man passing by decided to video their good deed and put it on the internet.","start":383.67,"end":388.69,"wordCount":16},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"One local woman commented on being embarrassed that tourists were cleaning up their beach.","start":395.27,"end":400.58,"wordCount":14},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"Hello Benjamin, Dan and I will be going for a run along the canal Saturday morning.","start":507.87,"end":513.79,"wordCount":16},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"Would you like to join us?","start":513.79,"end":515.32,"wordCount":6},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'd love to, but I hurt my ankle last weekend playing football with work colleagues.","start":515.4,"end":520.53,"wordCount":15},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"I won't be here next Saturday.","start":534.77,"end":536.93,"wordCount":6},{"id":"g5-s2","groupIndex":4,"groupLabel":"Conversation 2","answer":"Thanks for having me on the show, Lisa.","start":688.98,"end":691.15,"wordCount":8},{"id":"g5-s3","groupIndex":4,"groupLabel":"Conversation 2","answer":"John, your book is getting a lot of attention, partly because you write that most people can retire by 40.","start":691.42,"end":699.11,"wordCount":20},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"When researching this book, I interviewed hundreds of people who retired by 40.","start":701.84,"end":706.85,"wordCount":13},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"Okay, but how much money does a person need to retire?","start":707.12,"end":711.17,"wordCount":11},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"While most financial planners do give numbers, I don't think that's useful, as people are living in different areas with different costs of living, and have different needs and wants, which is why I suggest that people aim for financial independence.","start":717.19,"end":731.8,"wordCount":41},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"What do you mean by financial independence?","start":731.95,"end":735.24,"wordCount":7},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"Having investment income that's greater than monthly expenses.","start":735.24,"end":739.11,"wordCount":8},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"What if an accident happens or you get ill and need medical treatment?","start":741.4,"end":746.28,"wordCount":13},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"Shouldn't people have extra cash for emergencies?","start":746.46,"end":750.15,"wordCount":7},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"Too many people spend their lives working on jobs they hate because they're afraid, so I counsel people to take risks.","start":750.53,"end":757.94,"wordCount":21},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"Retirement doesn't have to be permanent, and if people need to, they can go back to work.","start":757.96,"end":763.62,"wordCount":17},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"But it's not always easy to get back into the workforce after an extended absence.","start":763.95,"end":769.52,"wordCount":15},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"Maybe, but how can anyone save enough to retire by 40 when most people can't retire at 60?","start":774.74,"end":781.52,"wordCount":18},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"Simple, by cutting housing, food, and transport expenses, and investing half your monthly income.","start":781.78,"end":788.24,"wordCount":14},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"I admit it's difficult, but it has worked for thousands.","start":790.34,"end":793.88,"wordCount":10},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"New research from America studies the role that the presence of individuals from different social or racial groups has in influencing consumers' food choices.","start":914.99,"end":926.2,"wordCount":24},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"This research found college students were more likely to choose healthy food in the presence of an observer of a different race, as opposed to an observer from their own race.","start":926.47,"end":938.22,"wordCount":31},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"The same was true when they were with someone from a different university, compared to someone from their own.","start":938.43,"end":944.62,"wordCount":19},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Researchers say this was because participants anticipated more negative judgment from an outsider group.","start":944.77,"end":952.09,"wordCount":14},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"In contrast, they felt less judged by members of their own group.","start":952.41,"end":957.09,"wordCount":12},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"In one experiment, participants were offered the choice between candy and fruit as a snack.","start":957.5,"end":963.49,"wordCount":15},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Other experiments showed similar results based on racial group.","start":979.71,"end":983.92,"wordCount":9},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"What's the reason for this pattern?","start":984.32,"end":986.38,"wordCount":6},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"The study found that people feel judged to a larger extent by members of other groups.","start":987.0,"end":992.73,"wordCount":16},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"Because of this, they strategically use healthy food choices to make a positive impression.","start":993.24,"end":999.14,"wordCount":14},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"There have been many attempts to help consumers make healthier choices, but consumers often struggle to maintain a healthy diet.","start":1000.04,"end":1008.82,"wordCount":20},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"This research finds that one way to promote a healthy diet could be to advertise the social benefits of healthy choices.","start":1009.09,"end":1018.11,"wordCount":21},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"Executive function is a term for the skills one needs to plan, organize, motivate, concentrate and memorize.","start":1140.61,"end":1148.99,"wordCount":17},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"These are skills students need to succeed in college.","start":1149.14,"end":1153.11,"wordCount":9},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"The researchers found that students who were most at risk had the most improvements in executive functioning after interacting with therapy dogs.","start":1154.07,"end":1163.76,"wordCount":22},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"These results remained when researchers followed up six weeks later.","start":1164.22,"end":1169.09,"wordCount":10},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"Many universities provide academic stress management programs and workshops.","start":1169.8,"end":1174.97,"wordCount":9},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"These are traditionally very similar to college classes.","start":1175.33,"end":1178.67,"wordCount":8},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"They often talk about ways to get more sleep, set goals, or manage stress or anxiety.","start":1178.88,"end":1185.46,"wordCount":16},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Pendry acknowledges that these are really important topics and these workshops help typical students succeed.","start":1186.14,"end":1193.48,"wordCount":15},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"But they're less helpful for struggling students.","start":1193.72,"end":1196.53,"wordCount":7},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"Pendry believes those students may experience the programs as another lecture and feel even more stressed.","start":1196.68,"end":1203.8,"wordCount":16},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"Taking risks in business does not mean going into business blindly and then expecting great results.","start":1277.42,"end":1284.68,"wordCount":16},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"Nobody can really be sure if risks will be met with success, no matter how calculated they may be.","start":1292.97,"end":1300.13,"wordCount":19},{"id":"g8-s4","groupIndex":7,"groupLabel":"Passage 3","answer":"But this should not stop you from taking risks, as risks are necessary if you want your business to succeed.","start":1300.54,"end":1307.6,"wordCount":20},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"Some risks may not work out, but an optimistic risk-taker will always look at failure as an opportunity to learn.","start":1308.39,"end":1316.86,"wordCount":21},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"The willingness to experiment with new ideas is key to business growth.","start":1317.72,"end":1322.67,"wordCount":12},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"As the old saying goes, \"Nothing ventured, nothing gained.\"","start":1323.38,"end":1327.92,"wordCount":9},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"Failure will teach you how to think and plan strategically.","start":1328.89,"end":1333.29,"wordCount":10},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"But just remember that not all risks are good ones, and when you fail, learn from it and move forward.","start":1333.79,"end":1341.68,"wordCount":20},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Since most people tend to avoid risk, businesses that are brave enough to take risks already have a competitive advantage.","start":1342.37,"end":1350.6,"wordCount":20},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"They are the ones setting the standard with new ideas, fresh offers and bold inventions.","start":1351.14,"end":1357.36,"wordCount":15},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"Risk-takers are best at adapting in difficult times.","start":1357.75,"end":1361.84,"wordCount":9},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Simply put, when most individuals stay away from risk, it means less competition for risk-takers.","start":1362.83,"end":1369.95,"wordCount":16},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"We don't know if you'll achieve what these risk-takers have achieved.","start":1370.76,"end":1374.6,"wordCount":12},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"But for as long as you want to stay safe, and for as long as you are content with where your business is right now, you will never find out.","start":1374.6,"end":1383.04,"wordCount":30}],"manualOnly":false},"2023-12-set2":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"He expected to find a driver who was either very drunk or having a medical emergency.","start":117.77,"end":123.47,"wordCount":16},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"Instead, the officer discovered a five-year-old boy sat on the edge of the driver's seat.","start":123.77,"end":129.87,"wordCount":17},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"The child had taken the keys to the family car while his teenage sister was napping.","start":136.68,"end":142.12,"wordCount":16},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"He then drove three kilometers across town before getting on the highway.","start":142.75,"end":147.5,"wordCount":12},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"These pieces of bone are caused by the way people bend their heads when they use the phone.","start":248.81,"end":254.57,"wordCount":18},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"This shifts weight onto the muscles at the back of the head and causes the bone to grow in a way that is not normal.","start":255.01,"end":263.18,"wordCount":25},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"This process can be compared to the way the skin hardens in response to constant rubbing or pressure.","start":263.39,"end":270.32,"wordCount":18},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"There was one time when the doctor's receptionist came back and he was sitting on her chair.","start":357.13,"end":363.26,"wordCount":17},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"\"He's been a regular visitor for most of this year,\" she told the Press Association.","start":377.7,"end":382.53,"wordCount":15},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"\"He's a very relaxed cat, happy for customers and villagers young and old to come in and say hello.\"","start":382.74,"end":388.79,"wordCount":19},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"She also said he is a cat of expensive tastes who likes his high priced cat food.","start":389.38,"end":395.62,"wordCount":17},{"id":"g3-s12","groupIndex":2,"groupLabel":"News Report 3","answer":"Sarah Godfrey, who is organizing Wilbur's party, told the local newspaper, \"Wilbur is part of our lives, as he is for everyone who lives in the village.\"","start":396.07,"end":406.47,"wordCount":27},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"What about the Sandwich Place on Camden Street?","start":514.78,"end":518.04,"wordCount":8},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's a great place, but I think we go there too often.","start":522.54,"end":525.95,"wordCount":12},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"There were crowds of people around her asking for a photo with her.","start":533.59,"end":537.52,"wordCount":13},{"id":"g5-s3","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you have a reservation with us already?","start":683.65,"end":686.17,"wordCount":8},{"id":"g5-s5","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yes, we reserved our rooms yesterday morning on your website for three nights.","start":687.74,"end":692.45,"wordCount":13},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yes, the two kids, my wife and I, and her parents too.","start":699.54,"end":703.53,"wordCount":12},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"So we have a family room for you and your wife and the kids, and another double room for your parents-in-law.","start":704.66,"end":711.87,"wordCount":23},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"They are right next to each other on the ground floor, since you mentioned in your message that they have trouble with stairs.","start":711.87,"end":718.61,"wordCount":23},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"And if you need any help to find transportation for the whole family, we can definitely recommend someone for you.","start":727.25,"end":733.95,"wordCount":20},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"We were thinking of renting a car, but we will explore all the options available for sure.","start":733.95,"end":739.08,"wordCount":17},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"So, yes, that would be very helpful in comparing prices.","start":739.08,"end":742.91,"wordCount":10},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"We're also wondering what tours and day trips are available.","start":742.93,"end":746.51,"wordCount":10},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"We have bunches of brochures here.","start":746.51,"end":749.06,"wordCount":6},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"I would recommend getting out on a boat trip.","start":749.11,"end":751.84,"wordCount":9},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"The kids will love it and there are so many islands nearby to explore.","start":751.84,"end":756.38,"wordCount":14},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"There's also a great night market further into town that has all kinds of food and cool little shops selling souvenirs and local jewelry and clothing made by hand.","start":756.4,"end":767.2,"wordCount":29},{"id":"g5-s27","groupIndex":4,"groupLabel":"Conversation 2","answer":"Now, all I need is to photocopy your passports and then I can get you all checked in and show you to your rooms.","start":770.27,"end":777.52,"wordCount":24},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Artificial intelligence agents play ever more influential roles in our lives.","start":901.58,"end":907.41,"wordCount":11},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"They do everything from suggesting new friends to recommending purchases.","start":907.62,"end":912.47,"wordCount":10},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"They're even beginning to drive our cars.","start":913.06,"end":915.77,"wordCount":7},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Another role that they are expected to take over is negotiating on our behalf in commercial transactions or legal disputes.","start":916.29,"end":924.93,"wordCount":20},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"So, it's important to know whether using an artificial intelligence agent might affect how we negotiate.","start":925.3,"end":932.5,"wordCount":16},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"In a new study, participants were told to imagine that they were negotiating for something important to them, like a house.","start":935.79,"end":943.37,"wordCount":21},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Next, they were told either that they would negotiate for themselves, or they would program an artificial intelligence agent to negotiate for them.","start":943.56,"end":953.52,"wordCount":23},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Participants then completed a survey indicating how tough, deceptive and pleasant or otherwise they wanted to be, or wanted their agent to be, in the negotiations.","start":953.7,"end":965.7,"wordCount":26},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"For example, participants could choose to be tough by making an opening demand far greater than what they'd be willing to accept.","start":966.14,"end":974.15,"wordCount":22},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"They could also choose to express sympathy with their opponent to appear pleasant.","start":974.78,"end":979.52,"wordCount":13},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"But they could also indicate that they—or their agent—would strategically express anger toward the opponent to gain advantage, or they could opt to convey dissatisfaction with the encounter so that the other party would think they were losing interest.","start":980.05,"end":996.17,"wordCount":41},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"These are both examples of deceptive strategies.","start":996.41,"end":999.81,"wordCount":7},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"Participants were more willing to employ deceptive strategies when assigned an agent to negotiate on their behalf.","start":1000.27,"end":1007.31,"wordCount":17},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"This suggests a link between cooking confidence and satisfaction around cooking, and mental health benefits.","start":1154.91,"end":1162.06,"wordCount":15},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"Who benefits most from learning to cook?","start":1162.83,"end":1165.39,"wordCount":7},{"id":"g7-s17","groupIndex":6,"groupLabel":"Passage 2","answer":"At the end of the program, cooking confidence and skills were equal across both counterparts.","start":1177.74,"end":1183.54,"wordCount":15},{"id":"g7-s18","groupIndex":6,"groupLabel":"Passage 2","answer":"This change in confidence could lead to a gender balance in home cooking.","start":1185.97,"end":1190.28,"wordCount":13},{"id":"g7-s19","groupIndex":6,"groupLabel":"Passage 2","answer":"This in turn could reduce consumption of unhealthy, high-calorie processed meals.","start":1190.54,"end":1196.46,"wordCount":12},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Extending from 4 to 12 feet away from us is “social space”.","start":1329.35,"end":1334.64,"wordCount":12},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Here people feel comfortable conducting routine social interactions with new acquaintances or total strangers.","start":1334.88,"end":1342.43,"wordCount":14},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"It is important to keep in mind that personal space varies depending on culture and context.","start":1348.28,"end":1354.98,"wordCount":16},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"Furthermore, there are significant individual differences.","start":1355.43,"end":1359.28,"wordCount":6},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"As we all know, cultural or individual differences in personal bubble diameters are all too often the cause of discomfort.","start":1359.56,"end":1368.48,"wordCount":20},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"How did these personal bubbles arise?","start":1369.02,"end":1371.78,"wordCount":6}],"manualOnly":false},"2024-06-set1":{"clips":[{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"Officials described the structure as a mixed-use building that features commercial businesses on the first floor and residential on the second and third floors.","start":76.83,"end":87.45,"wordCount":25},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Town records list four apartments in the building.","start":87.66,"end":90.89,"wordCount":8},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"Due to smoke and heat damage, the four apartments were declared uninhabitable, and the six residents had to move to another place, officials said.","start":91.51,"end":101.36,"wordCount":24},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"No injuries were reported in connection with the fire.","start":102.0,"end":105.42,"wordCount":9},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"The Norwalk Fire Marshal is investigating the cause and origin of the fire.","start":105.51,"end":110.55,"wordCount":13},{"id":"g2-s3","groupIndex":1,"groupLabel":"News Report 2","answer":"A number of past studies have found the link between season of birth and mental health diagnoses.","start":181.4,"end":187.96,"wordCount":17},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"Researchers have suggested that such links could arise from various things.","start":188.34,"end":192.89,"wordCount":11},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"These include nutrient intake, sun exposure, climate, and disease exposure varying across the course of the year.","start":193.16,"end":202.12,"wordCount":17},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"Overall, the new study found no significant relationship between participants' month of birth and symptoms of depression or anxiety.","start":216.19,"end":225.53,"wordCount":19},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"There was some variability in some countries.","start":225.97,"end":228.99,"wordCount":7},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"In Poland, depressive symptoms fluctuated a little depending on birth month.","start":229.23,"end":234.83,"wordCount":11},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"In the Czech Republic, the same was true of anxiety symptoms.","start":235.03,"end":239.28,"wordCount":11},{"id":"g2-s12","groupIndex":1,"groupLabel":"News Report 2","answer":"But on the whole, there was no systematic pattern.","start":239.49,"end":242.63,"wordCount":9},{"id":"g3-s1","groupIndex":2,"groupLabel":"News Report 3","answer":"Genetic researchers in China have made a clone of a star police dog.","start":296.46,"end":301.58,"wordCount":13},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"The clone was born in a laboratory in Beijing in December.","start":301.76,"end":306.36,"wordCount":11},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"Tests show that the clone and her mother are almost identical genetically.","start":306.95,"end":312.23,"wordCount":12},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"The mother dog helped solve multiple murders and many other crimes.","start":312.56,"end":317.11,"wordCount":11},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"The clone has already performed better than traditionally bred dogs on several tests.","start":317.43,"end":323.38,"wordCount":13},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"If the clone continues to perform as well as expected, it could mean a huge reduction in the training time for police dogs, which usually takes about five years.","start":324.04,"end":335.43,"wordCount":29},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"The ultimate goal of scientists is to produce clones of talented police dogs that can be trained in months instead of years.","start":335.77,"end":344.15,"wordCount":22},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"However, this goal is not yet possible due to the current costs of the technology.","start":344.6,"end":350.69,"wordCount":15},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"This is not the first time a clone has been made of a star police dog.","start":351.13,"end":355.58,"wordCount":16},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's written by a Chinese science fiction writer.","start":483.48,"end":486.31,"wordCount":8},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"I don't want to say too much and spoil it for you, but it's definitely got some amazing technological and sociological concepts in it.","start":494.21,"end":503.17,"wordCount":24},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"It does sound like it would suit my taste, but if they are making a TV series based on it now, I don't know if I should read the book or watch the show first.","start":503.66,"end":513.73,"wordCount":35},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"And then, you just end up ruining the book for yourself, if the show isn't very good.","start":519.79,"end":524.79,"wordCount":17},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"When is the show supposed to start?","start":525.02,"end":527.31,"wordCount":7},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm a bit overwhelmed with the amount of data I still need to collect to finish my thesis.","start":527.31,"end":532.17,"wordCount":18},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"But I still need to relax sometimes.","start":532.41,"end":535.29,"wordCount":7},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"And then, maybe we can watch the series together.","start":550.45,"end":553.66,"wordCount":9},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"It says on your website that you are still looking for vendors, and I grow organic vegetables on my farm, as well as doing my own home baking.","start":661.24,"end":670.08,"wordCount":28},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"Would I be able to sell both the vegetables and items baked from them at the festival?","start":670.48,"end":676.12,"wordCount":17},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you prefer to fill out an application on the web, or to print it out and fill it in by hand and then post it back to us?","start":682.69,"end":690.19,"wordCount":29},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"I should be fine with doing it on your website, and I already have all my certificates, as we run a small farm shop too.","start":703.63,"end":710.8,"wordCount":25},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"But can you give me your details anyway?","start":710.82,"end":713.42,"wordCount":8},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"Supporters call it “wild camping”; opponents call it “illegal camping”.","start":856.99,"end":862.39,"wordCount":10},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"What both sides accept is that there has been a boom in the past few months, with increasing numbers of visitors pitching their tents on any bit of land they fancy in the UK.","start":862.56,"end":873.98,"wordCount":34},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"In part, this reflects the fact that official campsites have been wholly or partially closed, or are overflowing in a summer when fewer people are going abroad.","start":874.02,"end":885.14,"wordCount":27},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"It is also cheap, at a time when many are worried about what the economic future holds.","start":885.76,"end":891.97,"wordCount":17},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"But it may also be an expression of a desire for going outdoors—a response to the months of lockdown.","start":892.29,"end":899.76,"wordCount":20},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"There's also a theory that this color helps the dolphins more readily blend in with their surroundings.","start":1092.78,"end":1099.08,"wordCount":17},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"The Amazon wetland system, fed by the Amazon River, is a crucial place for pink dolphins to breed, and since 2018 has been granted internationally protected status.","start":1110.05,"end":1122.59,"wordCount":27},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"\"Financial independence is something they were struggling with and challenged by.","start":1272.72,"end":1277.63,"wordCount":11},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Many of the parents have taken on college loans for the kids, too, sometimes at the expense of their own finances.","start":1290.13,"end":1297.5,"wordCount":21},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Whether that's likely, or even possible, anytime soon, is anyone's guess.","start":1305.12,"end":1310.62,"wordCount":11}],"manualOnly":false},"2024-06-set2":{"clips":[{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"“It was like a split second of panic…that resulted in this nervous reaction on the plane,” said passenger Brian Healy.","start":71.67,"end":80.59,"wordCount":21},{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"“There was total quiet, and then there was relief when the plane came to a stop.”","start":81.08,"end":86.78,"wordCount":16},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"The staff believe he squeezed himself out of a gap located around new energy-saving bulbs installed inside the snake house.","start":188.66,"end":197.6,"wordCount":21},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"He was only found the first time around because staff brought in a special machine to trace him inside a wall opening.","start":198.09,"end":206.62,"wordCount":22},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"And she’s aware of the concerns.","start":322.46,"end":324.59,"wordCount":6},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"And never assume the driver is going to stop or see you.”","start":333.12,"end":337.21,"wordCount":12},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"What’s the best way to teach children how to save and spend their money?","start":445.7,"end":450.42,"wordCount":14},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"You should make money a regular topic of discussion.","start":451.01,"end":454.38,"wordCount":9},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"It’s best to start young, so it’s instinctive rather than a scary subject.","start":454.62,"end":460.45,"wordCount":13},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"In our family, we talk openly about things like the budget for holidays, how taxes reduce your income, and how to shop around for the best deals.","start":460.82,"end":470.05,"wordCount":27},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"It’s also essential to make money real for children through practical examples.","start":471.0,"end":476.61,"wordCount":12},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"Working out how much we save using discount pizza coupons, for example, is much more relevant than abstract sums.","start":476.9,"end":485.2,"wordCount":19},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"We also give our kids pocket money, and the amount they get is linked to chores, such as putting the bins out and emptying the dishwasher.","start":485.48,"end":493.6,"wordCount":26},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"We do that too, and it’s paid according to their age.","start":493.6,"end":497.07,"wordCount":11},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"Teaching them to save is important.","start":501.18,"end":503.36,"wordCount":6},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"After birthdays and Christmas, they would go to the branch and deposit their gift money.","start":506.1,"end":511.3,"wordCount":15},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"Oh, I hadn’t considered doing that.","start":511.36,"end":513.77,"wordCount":6},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"In our house, we have transparent money boxes for them to put small change in, so they can see their savings grow.","start":513.82,"end":521.11,"wordCount":22},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"When the time is right, I’ll start talking to our children about investing and show them how the money saved for their further education has grown.","start":521.28,"end":529.7,"wordCount":26},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"I am always talking to my elder daughter about the importance of saving into a pension.","start":529.98,"end":535.14,"wordCount":16},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"She’s just started a part-time job and was thinking of not contributing to her pension.","start":535.33,"end":541.05,"wordCount":16},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"Luckily, I managed to persuade her otherwise.","start":541.21,"end":544.34,"wordCount":7},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, it’s such an important lesson to learn.","start":544.37,"end":547.62,"wordCount":8},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"I spent 25 years as a professor, actually.","start":660.33,"end":663.81,"wordCount":8},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"And then, for the last 10 years, I’ve worked as a political consultant, advising politicians at the national level about problems in our country.","start":663.81,"end":672.69,"wordCount":24},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"You discuss three of those problems in the book, improving public education, reducing our nation’s healthcare burden, and increasing personal savings.","start":672.83,"end":683.14,"wordCount":21},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"But your ideas about education are the most controversial.","start":683.46,"end":687.39,"wordCount":9},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"A lot of people think I’m trying to punish students who aren’t doing well, when actually my goal is to give all students more incentive to succeed.","start":688.92,"end":697.99,"wordCount":27},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"I’m not sure I agree with you.","start":697.99,"end":700.13,"wordCount":7},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"Your proposal to pay cash rewards to students who get good grades is a particular problem.","start":700.13,"end":706.21,"wordCount":16},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"What about students who don’t get good grades?","start":706.48,"end":709.43,"wordCount":8},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"But my proposal is not just to reward students with good grades, but also students who show improvements.","start":716.57,"end":724.23,"wordCount":18},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Okay, another criticism of the plan is the cash rewards themselves.","start":724.49,"end":729.38,"wordCount":11},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"Where will the money come from?","start":729.38,"end":731.25,"wordCount":6},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"So, in the end, the rewards will pay for themselves.","start":735.19,"end":738.5,"wordCount":10},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"The reply was exactly the same.","start":874.22,"end":876.24,"wordCount":6},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Honestly, I hear the same answer from the vast majority of people I meet.","start":877.48,"end":882.4,"wordCount":14},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"So I started to think: “Guess what?","start":882.56,"end":885.41,"wordCount":7},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"I’m busy, you’re busy, everybody’s busy.","start":886.96,"end":890.64,"wordCount":6},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"So you being busy doesn’t make me sympathetic at all.","start":891.07,"end":895.09,"wordCount":10},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Because “busy” is the state of the world.","start":895.09,"end":897.78,"wordCount":8},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"So I’m launching a campaign to stop people complaining about being “busy.”","start":898.32,"end":903.27,"wordCount":12},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"It may sound harsh, but the truth is, nobody cares.","start":903.35,"end":907.3,"wordCount":10},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"In a busy world, “being busy” doesn’t stand out, nor does it mean productive, creative, accomplished, or professional.","start":907.3,"end":916.08,"wordCount":18},{"id":"g6-s17","groupIndex":5,"groupLabel":"Passage 1","answer":"So the next time someone asks you how you are, maybe respond differently.","start":943.68,"end":948.66,"wordCount":13},{"id":"g6-s18","groupIndex":5,"groupLabel":"Passage 1","answer":"In my experience, the “I’m busy” response is really covering up the fact that they’re not actually accomplishing their real purpose.","start":948.71,"end":957.17,"wordCount":21},{"id":"g6-s19","groupIndex":5,"groupLabel":"Passage 1","answer":"And “being busy” is the lie they tell themselves about why they can’t achieve it.","start":957.17,"end":962.71,"wordCount":15},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"It’s great to stay fit and healthy, but standard exercise routines and sports only work the same muscles repeatedly.","start":1093.42,"end":1101.48,"wordCount":19},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"With extreme sports, you’ll be working entirely different muscles, and that means you get an all-over workout.","start":1101.81,"end":1109.16,"wordCount":18},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"Extreme sports also burn a lot more calories than other sports.","start":1109.61,"end":1114.32,"wordCount":11},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"Skateboarding, for example, can burn as many as 500 calories per hour.","start":1114.73,"end":1120.22,"wordCount":12},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"Basketball burns around 300 in the same time.","start":1120.67,"end":1124.58,"wordCount":8},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"When you find that you can overcome the physical or mental challenges involved in extreme sports, you’ll feel superhuman and your self-confidence will be at an all-time high.","start":1125.25,"end":1137.18,"wordCount":30},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Without conflict, we’re often stuck in this artificial harmony where people don’t express potentially innovative ideas for fear that they may start conflict with others.","start":1269.2,"end":1280.83,"wordCount":25},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"But if you’re in a place where you have a basis of trust, conflict can be extremely productive.","start":1281.5,"end":1287.5,"wordCount":18},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"It can lead to increased innovation and greater trust on teams.","start":1287.85,"end":1292.94,"wordCount":11},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"It may be an uncomfortable process, but good leaders and healthy teams recognize that productive and healthy conflict is an important part of how they function.","start":1293.16,"end":1305.02,"wordCount":26}],"manualOnly":false},"2024-12-set1":{"clips":[{"id":"g1-s2","groupIndex":0,"groupLabel":"News Report 1","answer":"As part of the event, the city is celebrating its longest-serving driver on the force.","start":115.5,"end":121.26,"wordCount":16},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"Christian has been a driver for 25 years.","start":124.15,"end":127.41,"wordCount":8},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"She says that the best part of the job is watching the children who ride her bus grow up.","start":133.72,"end":139.4,"wordCount":19},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Transit Driver Appreciation Day has been celebrated across the country as far back as 2009.","start":139.73,"end":147.05,"wordCount":15},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"These account for 64% of the total request at $59 million.","start":248.14,"end":254.07,"wordCount":11},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"There are some factors that could affect the budget moving forward.","start":262.03,"end":266.01,"wordCount":11},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"One of those is total enrollment.","start":266.03,"end":268.8,"wordCount":6},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"The district will have a total enrollment of 3,742 students.","start":269.25,"end":274.85,"wordCount":11},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"This represents 47 fewer students than the current year.","start":284.44,"end":289.5,"wordCount":9},{"id":"g2-s12","groupIndex":1,"groupLabel":"News Report 2","answer":"Fewer students mean less federal and state funding.","start":289.59,"end":293.96,"wordCount":8},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"And alarmed locals contacted police, thinking they had heard bombs going off.","start":346.67,"end":352.35,"wordCount":12},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"The phenomenon happens when thunder and lightning mix with a heavy snowstorm— sometimes causing loud claps that can be confused with explosions.","start":352.87,"end":363.92,"wordCount":22},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"One person described it as a loud boom, similar to a plane crash.","start":364.46,"end":369.49,"wordCount":13},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"Another person was woken up in the middle of the night by what he thought was early construction work starting.","start":369.6,"end":376.21,"wordCount":20},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The noise was powerful enough to shake buildings and set off car alarms.","start":376.39,"end":381.55,"wordCount":13},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"The police were flooded with many calls from the public.","start":382.17,"end":385.45,"wordCount":10},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"And they sent out a message asking people to remain calm.","start":385.46,"end":389.38,"wordCount":11},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"The police assured everyone that it was just thunder and lightning rather than some military exercise.","start":389.56,"end":396.7,"wordCount":16},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"The weather was the coldest it had been for the season, so people were warned to be careful when traveling outside.","start":396.92,"end":403.85,"wordCount":21},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"In particular, dangerous conditions such as icy roads or wet ground could cause difficulty for drivers.","start":403.92,"end":411.72,"wordCount":16},{"id":"g3-s12","groupIndex":2,"groupLabel":"News Report 3","answer":"The rail service also announced potential disruptions to trains due to the deep snow.","start":411.87,"end":418.13,"wordCount":14},{"id":"g3-s13","groupIndex":2,"groupLabel":"News Report 3","answer":"Some roads were also closed because of the severe weather.","start":418.32,"end":422.05,"wordCount":10},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"Maybe you're right, but the thing is, everyone at the office has a nice, expensive phone, and I'm a little embarrassed by mine.","start":544.39,"end":552.45,"wordCount":23},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"I just got a credit card, so I thought I might as well buy a new phone.","start":552.45,"end":557.29,"wordCount":17},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"I don't think buying a phone on credit is a good idea.","start":557.43,"end":561.14,"wordCount":12},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"Look, you've only been working for five months now.","start":561.14,"end":564.05,"wordCount":9},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"People understand that you are a recent graduate, and I doubt anyone cares about your phone other than yourself.","start":564.05,"end":570.91,"wordCount":19},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"Maybe you're right, but the credit card has a very good special offer, where I don't pay any interest for six months.","start":571.11,"end":578.89,"wordCount":22},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'll be able to pay for the phone well before that period is over.","start":578.96,"end":583.68,"wordCount":14},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"I still think it's a bad idea to use a credit card for something you don't need.","start":583.68,"end":588.41,"wordCount":17},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"One of my colleagues bought a lot of things on credit during her first year of work, and it became a bad habit, and she accumulated a lot of debt.","start":588.41,"end":597.42,"wordCount":30},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"Of course, those are great goals.","start":720.99,"end":723.53,"wordCount":6},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"But I've seen your blog, and you write about houses that are as small as 20 square meters.","start":723.53,"end":729.57,"wordCount":18},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"That's not a realistic size for families.","start":729.6,"end":733.0,"wordCount":7},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"I do talk about very small homes, but there's no set definition of a tiny home.","start":733.11,"end":739.59,"wordCount":16},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"And other people include homes that are much larger, say, 60 square meters.","start":739.59,"end":745.0,"wordCount":13},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"And you'd be surprised many families of four are happy living in houses that are under 30 square meters.","start":745.04,"end":752.83,"wordCount":19},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"But I think most of us want spacious homes.","start":753.02,"end":756.82,"wordCount":9},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"The average new house in this area is 150 square meters.","start":756.82,"end":761.43,"wordCount":11},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"And that's what people dream of owning.","start":761.43,"end":763.77,"wordCount":7},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yes, but I think that dream needs to change, considering the cost of housing.","start":764.02,"end":769.66,"wordCount":14},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"Housing costs are high, but do people really save that much by having a smaller home?","start":769.8,"end":775.81,"wordCount":16},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"So, tiny homes might not be for everyone, but they're a good option for many.","start":795.12,"end":801.15,"wordCount":15},{"id":"g5-s27","groupIndex":4,"groupLabel":"Conversation 2","answer":"How does this benefit the planet?","start":804.01,"end":806.25,"wordCount":6},{"id":"g5-s28","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, if people have smaller homes, they use less land and fewer resources to build them.","start":806.41,"end":812.73,"wordCount":16},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"Secondly, movement activities build children's big body skills such as coordination and balance, as well as the fine motor skills they need for tasks like writing, tying their shoes, or throwing and catching a ball.","start":964.53,"end":981.14,"wordCount":35},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Thirdly, according to the American Psychological Association, regular physical activity (and especially outdoor activity) reduces children's stress and depression, and improves their ability to focus and learn.","start":981.43,"end":995.81,"wordCount":27},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"Regular exercise can significantly improve self-regulation and decrease disciplinary consequences for negative behavior.","start":996.07,"end":1005.82,"wordCount":14},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Physical activity provides a positive outlet for frustration, anxiety, or anger and can become a healthy coping skill throughout life.","start":1005.89,"end":1016.09,"wordCount":20},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Finally, we know that physical activity is important for our physical and mental health, and cultivating the habit of physical activity starts early.","start":1016.49,"end":1026.58,"wordCount":23},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"Children are more likely to develop a lifelong love of physical activity from frequent positive early experiences.","start":1026.82,"end":1035.46,"wordCount":17},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"There are plenty of other options such as imaginative play, non-competitive games, and gardening or nature experiences.","start":1041.95,"end":1051.6,"wordCount":18},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"To conduct the study, the team partnered with an online job listings platform which emails postings relevant to individuals and their job search criteria.","start":1143.56,"end":1154.04,"wordCount":24},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"For the course of the 11-week study, the platform emailed job listings to some 180,000 users placed in one of two conditions.","start":1154.04,"end":1164.77,"wordCount":24},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"Information was then gathered on whether the email was opened, and which job listings were clicked on by each user.","start":1188.91,"end":1196.84,"wordCount":20},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"A new study from Oregon State University found that dogs tend to match their behavior with the children in their family.","start":1300.75,"end":1308.71,"wordCount":21},{"id":"g8-s2","groupIndex":7,"groupLabel":"Passage 3","answer":"The findings are important because there is a growing body of evidence that dogs can help children in many ways.","start":1309.03,"end":1316.59,"wordCount":20},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"\"But research does show that kids are very capable of training dogs.\"","start":1392.3,"end":1397.75,"wordCount":12}],"manualOnly":false},"2024-12-set2":{"clips":[{"id":"g1-s2","groupIndex":0,"groupLabel":"News Report 1","answer":"A number of factors are creating a bad situation: Global energy consumption is up, but supplies have been reduced.","start":111.85,"end":119.75,"wordCount":19},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"The study aimed to identify disconnects between how healthily Americans think they eat and how they actually do.","start":249.42,"end":257.79,"wordCount":18},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"Folks also completed 24-hour food questionnaires.","start":266.75,"end":271.37,"wordCount":7},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Then, the researchers compared answers to see how well responses to the two exercises matched up.","start":271.37,"end":278.48,"wordCount":16},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"Those who rated their diet as poor tended to be far more accurate.","start":292.66,"end":297.92,"wordCount":13},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"But I've found that if I review my spending every night, that keeps me from spending too much.","start":548.55,"end":554.65,"wordCount":18},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, what do you do now then?","start":571.31,"end":573.66,"wordCount":7},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"It seems like you'd have the same problems with cash.","start":573.66,"end":576.68,"wordCount":10},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"I go to the bank once a week, and the rest of the time I keep my bank card at home, so I can't get more cash out.","start":576.83,"end":583.98,"wordCount":28},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"And I also have a notebook where I record my expenses.","start":584.35,"end":588.13,"wordCount":11},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"But what prevents you from just going to the bank and getting more money, if you want to buy something?","start":588.14,"end":593.74,"wordCount":20},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"The first month I did withdraw extra cash twice, but I felt guilty about it.","start":594.0,"end":599.24,"wordCount":15},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"And after that I refused to spend more than what I had budgeted, and by now it's just a habit.","start":599.24,"end":605.97,"wordCount":20},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"The environment is easier to control, and he can still get a good workout, in addition to improving his hand-eye coordination.","start":726.62,"end":734.38,"wordCount":22},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"Besides, I could teach him some of the basics from my time as a badminton player.","start":734.59,"end":739.78,"wordCount":16},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"There's nothing like playing as part of a unit to accomplish a goal like winning a game or even a championship.","start":744.45,"end":750.79,"wordCount":21},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"He could try basketball since many of the courts are indoors now and it's a sport that could help him understand team spirit while cooperating with others.","start":751.08,"end":760.64,"wordCount":27},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"Maybe he could even join the school basketball team when he's ready.","start":760.99,"end":765.01,"wordCount":12},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"It's a team sport and they often have mixed-gender teams so he could socialize with both girls and boys.","start":767.91,"end":774.71,"wordCount":20},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"This is the equivalent produced by your average car driving almost 70 times around the world.","start":939.49,"end":946.2,"wordCount":16},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"These issues are growing more pressing with the emergence of commercial spaceflight.","start":952.54,"end":957.72,"wordCount":12},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"A household pet can also cultivate a child's sense of responsibility as their parent explains the necessary processes of keeping their pet happy and healthy.","start":1131.94,"end":1145.33,"wordCount":25},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"As a child matures, they can then take on more of the daily responsibilities, boosting their sense of independence.","start":1145.73,"end":1153.16,"wordCount":19},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"Pets also provide a fantastic subject for research and learning.","start":1153.8,"end":1158.31,"wordCount":10},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"Taking children along to the pet shop to buy food and supplies will support their cognitive development as their passion for learning flourishes.","start":1167.08,"end":1176.09,"wordCount":23},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"A child's physical development can benefit greatly from taking pets for walks in the fresh air.","start":1176.68,"end":1182.76,"wordCount":16},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"When responsibilities are well paced and communicated, a child can benefit greatly from involvement in bringing up a happy and healthy pet.","start":1188.96,"end":1197.79,"wordCount":22},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"And of course, if a child doesn't have a pet in their own household, they can still benefit from all of the above when visiting a friend who does.","start":1198.31,"end":1207.7,"wordCount":29},{"id":"g8-s2","groupIndex":7,"groupLabel":"Passage 3","answer":"This would include costs of college, grants and scholarships.","start":1293.31,"end":1298.32,"wordCount":9},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"It would also include expected monthly loan payments and projected salary after college.","start":1298.59,"end":1305.48,"wordCount":13},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"He said it would give prospective students more information about what to expect once they graduate.","start":1312.4,"end":1319.31,"wordCount":16}],"manualOnly":false},"2025-06-set1":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"This was after his online interview attracted millions of views and was made into a song.","start":69.6,"end":76.34,"wordCount":16},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"South Dakota is one of the top corn producers in America.","start":77.02,"end":81.58,"wordCount":11},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"The corn provides nourishment across the globe.","start":81.82,"end":85.12,"wordCount":7},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"Officials wanted to highlight South Dakota's two largest industries: tourism and agriculture.","start":103.51,"end":111.05,"wordCount":12},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Investigators were also able to recover the key that was used to open the collection boxes.","start":209.53,"end":216.36,"wordCount":16},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"In the absence of environmentally and economically feasible recycling options, fast-fashion manufacturers pump out low-quality clothes produced in high volumes that are worn only a few times and then discarded.","start":302.68,"end":318.19,"wordCount":32},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The researchers put forth policy contributions, ranging from sustainable disposal of leftover stock to production tax to incentivize both manufacturers and consumers to be more waste conscious.","start":318.47,"end":333.61,"wordCount":27},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"In order to devise effective policies to curb the environmental impact of the clothing industry, it is important to identify the source of the problem in the supply chain.","start":333.89,"end":345.47,"wordCount":29},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"Manufacturers, consumers, and regulatory bodies can then take an informed approach to recognize the environmental impact of fast-fashion and to design an ecosystem to reduce waste, incentivize innovation, and create new business models to manage waste.","start":345.87,"end":366.47,"wordCount":37},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, I think the local government could help improve things.","start":482.43,"end":486.39,"wordCount":10},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"I mean, getting rid of rush hour may be impossible, but it could be made more tolerable, don't you think?","start":486.39,"end":493.74,"wordCount":20},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, for example, the subway system could have air conditioning.","start":497.6,"end":502.49,"wordCount":10},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"I know many cities in the world have air conditioning in their subway, so why can't we?","start":502.54,"end":508.99,"wordCount":17},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"It gets so hot in the summer.","start":509.07,"end":511.46,"wordCount":7},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"I can hardly breathe down there.","start":511.46,"end":513.52,"wordCount":6},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"And add to that the rush-hour crowds with strangers packed close together in the subway carriages, the whole thing is just horrible.","start":513.74,"end":523.37,"wordCount":23},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"The trains here are too old.","start":526.41,"end":528.36,"wordCount":6},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"The government should definitely invest in new ones with air conditioning.","start":528.56,"end":532.66,"wordCount":11},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"I guess I'm fortunate I take the bus instead.","start":532.78,"end":535.97,"wordCount":9},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you remember he had a scar on his face?","start":660.87,"end":663.99,"wordCount":10},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've known him since primary school, and I always remember him having that on his cheek.","start":666.75,"end":672.11,"wordCount":16},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"He had an operation done on it, plastic surgery, in order to cover it and make it less noticeable.","start":680.36,"end":686.73,"wordCount":19},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"Oh, well, that's ridiculous, isn't it?","start":687.07,"end":690.15,"wordCount":6},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"But it wasn't an ugly scar.","start":692.1,"end":694.38,"wordCount":6},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"It never occurred to me that he should have it taken care of like that.","start":694.39,"end":698.24,"wordCount":15},{"id":"g5-s23","groupIndex":4,"groupLabel":"Conversation 2","answer":"I can understand some scars and physical defects can be ugly and distracting, but not Johnny's.","start":699.56,"end":705.87,"wordCount":16},{"id":"g5-s24","groupIndex":4,"groupLabel":"Conversation 2","answer":"like it gave him a certain uniqueness.","start":708.8,"end":711.52,"wordCount":7},{"id":"g5-s25","groupIndex":4,"groupLabel":"Conversation 2","answer":"He must have felt differently though.","start":711.78,"end":714.14,"wordCount":6},{"id":"g5-s28","groupIndex":4,"groupLabel":"Conversation 2","answer":"He was totally fine with his scar.","start":720.91,"end":723.21,"wordCount":7},{"id":"g5-s29","groupIndex":4,"groupLabel":"Conversation 2","answer":"As you said, he had had it for most of his life.","start":723.21,"end":726.67,"wordCount":12},{"id":"g5-s33","groupIndex":4,"groupLabel":"Conversation 2","answer":"That's so superficial and selfish of her.","start":732.42,"end":735.56,"wordCount":7},{"id":"g5-s34","groupIndex":4,"groupLabel":"Conversation 2","answer":"If Johnny's girlfriend doesn't like him for who he is, then she does not deserve to be his girlfriend.","start":735.56,"end":742.11,"wordCount":19},{"id":"g5-s36","groupIndex":4,"groupLabel":"Conversation 2","answer":"So he is insane to give in to her like that.","start":743.0,"end":746.07,"wordCount":11},{"id":"g5-s37","groupIndex":4,"groupLabel":"Conversation 2","answer":"But when I told him, he said he loves her and would just do what she wants him to.","start":746.07,"end":751.26,"wordCount":19},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Perhaps they made the sound of wind to comment on the weather or imitated the sound of a bird to tell a friend that there was a bird nearby.","start":903.61,"end":912.45,"wordCount":29},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"At some point, people started stringing the words together to form sentences.","start":921.33,"end":926.92,"wordCount":12},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"The other main theory, which is more recent, is that people started off by gesturing—pointing at things with their hands and imitating actions using their bodies.","start":927.39,"end":938.66,"wordCount":27},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"This theory guesses that after developing sign languages, people eventually started making sounds along with their gestures.","start":943.65,"end":952.4,"wordCount":17},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"At some point, they switched to mostly making sounds that became words instead of just using their bodies.","start":952.68,"end":960.1,"wordCount":18},{"id":"g7-s1","groupIndex":6,"groupLabel":"Passage 2","answer":"Is it a good idea to display luxury brands and other signals of status?","start":1041.18,"end":1046.81,"wordCount":14},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"This means people are less willing to collaborate with them.","start":1070.23,"end":1074.13,"wordCount":10},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"Experiments showed that participants were less likely to choose someone who signals their wealth or status to join a group seeking cooperative members.","start":1085.35,"end":1095.1,"wordCount":23},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"These findings suggest that people should change how they present themselves depending on their social goal.","start":1102.43,"end":1109.11,"wordCount":16},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"This is the era of social media.","start":1109.46,"end":1111.95,"wordCount":7},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"People can easily share their wealth and status to large audiences, but they need to consider the consequences.","start":1111.95,"end":1119.49,"wordCount":18},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"Posting about luxury purchases and expensive vacations online may help you to persuade others and frighten competitors, but it could also signal to potential friends or future employers that you are unlikely to think about the needs of others.","start":1120.17,"end":1137.24,"wordCount":39},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"This makes things tricky for people who may want to impress others while also demonstrating that they are a team player.","start":1137.76,"end":1145.8,"wordCount":21},{"id":"g8-s1","groupIndex":7,"groupLabel":"Passage 3","answer":"Human fascination with animals goes back as far as humans do.","start":1218.95,"end":1223.56,"wordCount":11},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"At some point, humans began to capture and hold animals.","start":1234.05,"end":1238.63,"wordCount":10},{"id":"g8-s4","groupIndex":7,"groupLabel":"Passage 3","answer":"The first-known collections were held by royalty and were not open to the public.","start":1238.89,"end":1244.28,"wordCount":15},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":", containing the remains of animals, including elephants, which were not native to Egypt.","start":1250.52,"end":1256.17,"wordCount":13},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"But life wasn't easy for these animals.","start":1256.49,"end":1259.04,"wordCount":7},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"Researchers think the zoo was started with animals brought home from a far-off land known as Punt.","start":1274.63,"end":1280.7,"wordCount":18},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"It's unclear why the Queen built the zoo, but it might have been to show off her wealth and power.","start":1280.86,"end":1287.04,"wordCount":20},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Early zoos are found all over the world.","start":1287.76,"end":1290.89,"wordCount":8},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"His collection included tigers and lions.","start":1311.14,"end":1314.38,"wordCount":6},{"id":"g8-s16","groupIndex":7,"groupLabel":"Passage 3","answer":"This collection eventually moved to the Tower of London in 1235.","start":1314.68,"end":1319.69,"wordCount":11}],"manualOnly":false},"2025-06-set2":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"He is a student at Marathon High School.","start":140.2,"end":143.06,"wordCount":8},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"The race drew competitors from 41 US states.","start":156.3,"end":160.82,"wordCount":8},{"id":"g1-s11","groupIndex":0,"groupLabel":"News Report 1","answer":"The April contest is one of the most popular running events in the southeastern United States.","start":175.58,"end":182.23,"wordCount":16},{"id":"g1-s12","groupIndex":0,"groupLabel":"News Report 1","answer":"The race field filled within minutes after online registration opened in January.","start":182.33,"end":188.6,"wordCount":12},{"id":"g2-s2","groupIndex":1,"groupLabel":"News Report 2","answer":"He's going to take up a full-time position as ambassador for science and space instead—work he's been doing since 2019.","start":245.7,"end":255.07,"wordCount":22},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Tim said, \"Being an astronaut has been the most extraordinary experience.","start":279.19,"end":284.22,"wordCount":11},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"I've had the privilege of working with an exceptional team of individuals during the past 13 years with the agency.","start":284.66,"end":292.12,"wordCount":20},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"By assuming the role of an ambassador for human flights to space, I'll continue to support the European and the UK space agencies.\"","start":295.96,"end":305.56,"wordCount":23},{"id":"g3-s11","groupIndex":2,"groupLabel":"News Report 3","answer":"They visit the store so much that staff have been forced to put up signs, asking their customers not to feed them.","start":424.8,"end":433.29,"wordCount":22},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"I don't know if that's a good idea as your mother and I would worry about you living all by yourself in an apartment so far from home.","start":541.48,"end":550.13,"wordCount":28},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"And then there's the expense, too.","start":550.19,"end":552.3,"wordCount":6},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm not sure we can afford it.","start":552.38,"end":554.36,"wordCount":7},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"And with four of us, it wouldn't cost any more than living in the dorm.","start":561.51,"end":566.28,"wordCount":15},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"Rents in big cities are high, and then there's the cost of electricity and gas.","start":568.07,"end":572.81,"wordCount":15},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"We've budgeted for those, and for Internet and transportation.","start":574.69,"end":579.29,"wordCount":9},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"And if we move far enough from the city center, the rent is low enough for us to afford all of it.","start":579.59,"end":586.72,"wordCount":22},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"It sounds like you'll be wasting several hours every day on the road instead of studying.","start":589.68,"end":594.81,"wordCount":16},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's about an hour to campus, but there's no reason I can't study on the bus.","start":594.86,"end":600.38,"wordCount":16},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"But I'm not sure why you want to leave campus and go through all that trouble when the cost is the same.","start":607.04,"end":612.79,"wordCount":22},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"We'd have a kitchen, so we could cook ourselves.","start":614.78,"end":618.1,"wordCount":9},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"And we'd each have our own bedroom, where we could study instead of going to the library.","start":618.22,"end":624.28,"wordCount":17},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"We just have more space and privacy.","start":624.37,"end":627.56,"wordCount":7},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm not convinced that the benefits are greater than the disadvantages, but I'll discuss this with your mother.","start":627.78,"end":634.15,"wordCount":18},{"id":"g5-s4","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you have anything in mind?","start":727.1,"end":729.14,"wordCount":6},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"For that age group, our biggest seller this year has been this action figure.","start":736.11,"end":741.4,"wordCount":14},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"It has no batteries, if that's what you mean.","start":748.29,"end":750.89,"wordCount":9},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"And this toy is the lead character from the show.","start":755.2,"end":758.29,"wordCount":10},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"I've never heard of it, but I do know little Lawrence loves cartoons.","start":760.68,"end":765.97,"wordCount":13},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Do you have any other popular toys?","start":766.27,"end":768.84,"wordCount":7},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"Right over here, we have dozens of puzzles for children of all ages.","start":772.37,"end":776.66,"wordCount":13},{"id":"g6-s1","groupIndex":5,"groupLabel":"Passage 1","answer":"We assume that if we offer our customers more choices, then they'll be more likely to buy our products.","start":948.92,"end":956.07,"wordCount":19},{"id":"g6-s2","groupIndex":5,"groupLabel":"Passage 1","answer":"But here's the paradox of choice: if a person is presented with too many choices, they are actually less likely to buy.","start":956.33,"end":965.1,"wordCount":22},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"On a regular day at a local food market, people would find a display table with 24 different kinds of jams.","start":970.49,"end":978.52,"wordCount":21},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Guess which display table led to more sales?","start":987.16,"end":990.64,"wordCount":8},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"The study found that while the bigger display table created more interest, people were almost 10 times less likely to purchase a jar of jam than in the case of the smaller display.","start":990.95,"end":1002.97,"wordCount":33},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"Customer satisfaction takes a hit as well.","start":1003.47,"end":1006.33,"wordCount":7},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"In the study, the bigger display of jams leads to lower customer satisfaction than the smaller display.","start":1006.56,"end":1013.5,"wordCount":17},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"So as you can see, when it comes to choices, less is more.","start":1044.94,"end":1049.91,"wordCount":13},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"But if that resolution was to volunteer more, now is the best time to start.","start":1128.94,"end":1134.88,"wordCount":15},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"Volunteering can drop after the holiday season, and by February, some organizations lack the volunteers they had in surplus just a month ago.","start":1135.3,"end":1146.25,"wordCount":23},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"Most people cite time and conflicting work schedules as major barriers, but employees and employers would actually benefit if companies made employee volunteering part of the job.","start":1158.98,"end":1171.74,"wordCount":27},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"Researchers have found donating our time and talent to others can lower blood pressure, boost happiness and improve mental and physical health.","start":1171.84,"end":1181.64,"wordCount":22},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"Studies have also linked employee volunteer programs with more productive employees.","start":1181.95,"end":1188.31,"wordCount":11},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"With so much emphasis on employee wellness these days, company volunteer programs could be the perfect 2025 resolution.","start":1188.34,"end":1197.83,"wordCount":18},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"But for volunteering to benefit employees and the workplace, the entire organization needs to be involved.","start":1198.28,"end":1205.9,"wordCount":16},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"By allowing employees to donate their time during work hours, the workplace becomes an outlet for personal fulfillment without affecting personal time.","start":1206.12,"end":1216.84,"wordCount":22},{"id":"g8-s15","groupIndex":7,"groupLabel":"Passage 3","answer":"Perhaps unlike other waste food, the supply is regular.","start":1400.06,"end":1404.0,"wordCount":9},{"id":"g8-s17","groupIndex":7,"groupLabel":"Passage 3","answer":"So the menus remain regular too.","start":1408.04,"end":1410.78,"wordCount":6}],"manualOnly":false},"2025-12-set1":{"clips":[{"id":"g1-s5","groupIndex":0,"groupLabel":"News Report 1","answer":"\"We weren't even sure it was alive.","start":69.15,"end":71.51,"wordCount":7},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"So I gently pushed it with a stick to check it was breathing and saw it was a terrified little cat.","start":71.51,"end":78.68,"wordCount":21},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"It reversed even further into the engine and was stuck.","start":79.09,"end":83.1,"wordCount":10},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"I tried to reach it but it was too far down and there wasn't any way I could get it out.\"","start":83.29,"end":88.62,"wordCount":21},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"There will also be a fun tent for children.","start":180.0,"end":182.63,"wordCount":9},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"For anyone who wants to help make this year's games a massive success, there are still opportunities to volunteer for Fayetteville's Special Olympics.","start":189.08,"end":198.65,"wordCount":23},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"The color of the wrapper is similar as are the illustrations of the features.","start":309.06,"end":314.1,"wordCount":14},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"The chocolate company has been to court before to protect its popular chocolate treat.","start":314.29,"end":319.62,"wordCount":14},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"Last year, a German federal court said the shade of the gold wrapping was also protected.","start":319.71,"end":326.32,"wordCount":16},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"Can you please hand me that book over there?","start":426.45,"end":429.02,"wordCount":9},{"id":"g4-s2","groupIndex":3,"groupLabel":"Conversation 1","answer":"It has instructions for making a winter bean salad.","start":429.07,"end":432.27,"wordCount":9},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"My sister's boyfriend is coming over for dinner.","start":432.3,"end":434.93,"wordCount":8},{"id":"g4-s4","groupIndex":3,"groupLabel":"Conversation 1","answer":"He's vegetarian, so I need to make a lot of vegetable dishes.","start":434.94,"end":438.63,"wordCount":12},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"That doesn't sound like a very balanced diet.","start":441.54,"end":444.46,"wordCount":8},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"How can he get enough protein?","start":444.46,"end":446.44,"wordCount":6},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"What does he do to strengthen his muscles and all that?","start":446.44,"end":449.61,"wordCount":11},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"He's explained this to me when we first met.","start":452.01,"end":454.56,"wordCount":9},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"He eats a variety of different vegetables and nuts, especially those with high amounts of protein.","start":454.68,"end":460.5,"wordCount":16},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"It sounds a bit difficult, but he's done his research, I suppose.","start":460.74,"end":464.89,"wordCount":12},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"What's his reasoning for being vegetarian?","start":464.94,"end":467.53,"wordCount":6},{"id":"g4-s15","groupIndex":3,"groupLabel":"Conversation 1","answer":"Is it his religion, health condition or lifestyle?","start":467.53,"end":471.55,"wordCount":8},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"He's always been very sensitive and sympathizes with animals.","start":473.45,"end":477.07,"wordCount":9},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"He's even written to his state senator about the torture of dolphins in sea parks.","start":477.15,"end":481.87,"wordCount":15},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"He says that keeping animals in zoos and parks causes them great distress.","start":481.93,"end":486.68,"wordCount":13},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"That's a little gloomy, but I can understand that to a point.","start":486.87,"end":491.12,"wordCount":12},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"Not all zoos and animal parks have the most favorable conditions, but without them, it just wouldn't be feasible to learn about animals and their environments.","start":491.26,"end":500.97,"wordCount":26},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"Besides, I don't think I could ever give up a good hot dog at a baseball game.","start":501.37,"end":506.15,"wordCount":17},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"Honestly, I agree, but just don't let him hear you say that.","start":506.15,"end":510.24,"wordCount":12},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"He's the spokesperson for his local animal rights group.","start":510.27,"end":513.52,"wordCount":9},{"id":"g5-s1","groupIndex":4,"groupLabel":"Conversation 2","answer":"Did you see that television program on air travel last night?","start":602.16,"end":606.06,"wordCount":11},{"id":"g5-s3","groupIndex":4,"groupLabel":"Conversation 2","answer":"The part about overcoming jet lag was interesting.","start":606.85,"end":609.91,"wordCount":8},{"id":"g5-s4","groupIndex":4,"groupLabel":"Conversation 2","answer":"I was surprised that the expert recommended not eating for the entire journey and avoiding sleeping on the plane.","start":609.98,"end":616.52,"wordCount":19},{"id":"g5-s6","groupIndex":4,"groupLabel":"Conversation 2","answer":"As I read an article on the subject in the past that suggested the opposite, it claimed that it was important not to miss meals and that taking a nap on the plane was the best way to adjust to a new time zone.","start":618.38,"end":630.96,"wordCount":44},{"id":"g5-s7","groupIndex":4,"groupLabel":"Conversation 2","answer":"Well, the expert on the show did cite research supporting her recommendations.","start":631.29,"end":636.32,"wordCount":12},{"id":"g5-s8","groupIndex":4,"groupLabel":"Conversation 2","answer":"So I guess I'll give it a try next time I fly a long distance.","start":636.33,"end":639.91,"wordCount":15},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"Jet lag is a big problem for me and has been for the last few years, even though I never suffered from it before.","start":640.16,"end":647.18,"wordCount":24},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"So I guess I'm lucky that I can still adjust to different time zones well.","start":652.56,"end":657.49,"wordCount":15},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"My problem is I'm afraid to fly.","start":657.52,"end":660.45,"wordCount":7},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"Actually my mother is terrified of airplanes to the point where she can't even fly.","start":662.28,"end":667.39,"wordCount":15},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"So our family vacations were always by car or train.","start":667.39,"end":670.99,"wordCount":10},{"id":"g5-s19","groupIndex":4,"groupLabel":"Conversation 2","answer":"That segment was too brief, especially as so many people have that problem.","start":683.53,"end":688.31,"wordCount":13},{"id":"g5-s21","groupIndex":4,"groupLabel":"Conversation 2","answer":"Actually, it was a quarter of people.","start":691.77,"end":694.24,"wordCount":7},{"id":"g5-s22","groupIndex":4,"groupLabel":"Conversation 2","answer":"So the problem really is widespread and deserves attention.","start":694.24,"end":698.34,"wordCount":9},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"In other words, being proficient with a design tool and a few methods doesn't make you a user experience designer.","start":847.88,"end":856.25,"wordCount":20},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"There simply isn't a one-size-fits-all process.","start":856.76,"end":860.12,"wordCount":9},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"It's gained through experience on the job and learning what's appropriate given the needs of the project.","start":870.63,"end":876.84,"wordCount":17},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"I found my way to user experience through graphic design, and slowly over many different roles and experiences that led me to become a user experience designer.","start":877.55,"end":889.42,"wordCount":27},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"It took time and commitment to continue to pursue roles within teams that I knew could teach and challenge me.","start":890.03,"end":897.76,"wordCount":20},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"That's not to say that I think my path is the only one—but once again, nothing can substitute real-world experience.","start":898.38,"end":906.24,"wordCount":22},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"You can start anywhere as long as you know your end goal and you commit to actively pursuing opportunities to learn and grow along the way.","start":906.91,"end":916.11,"wordCount":26},{"id":"g7-s5","groupIndex":6,"groupLabel":"Passage 2","answer":"Flexible seating has been defined as movable furniture to create an engaging learning environment.","start":1023.7,"end":1031.0,"wordCount":14},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"For us, flexible seating has meant removing most of the traditional chairs and desks and introducing a variety of different seating options to promote student engagement.","start":1038.17,"end":1049.48,"wordCount":26},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"Teachers tend to still use this format because of either the need to control students or the belief that the teacher is the most important person in the room.","start":1061.61,"end":1071.6,"wordCount":29},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"It is a win for all concerned.","start":1097.34,"end":1099.67,"wordCount":7},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"Nearly all British schools have uniforms.","start":1202.45,"end":1205.02,"wordCount":6},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"According to the new rules, students of Tavern are required to wear smart black shoes appropriate for the workplace.","start":1213.44,"end":1221.38,"wordCount":19},{"id":"g8-s10","groupIndex":7,"groupLabel":"Passage 3","answer":"Harris held that strengthened rules around school uniforms improved student outcomes and behavior.","start":1222.03,"end":1228.27,"wordCount":13},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"But for some parents, the school's restrictions are an unnecessary burden.","start":1228.9,"end":1233.69,"wordCount":11}],"manualOnly":false},"2025-12-set2":{"clips":[{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"But officials say they usually seize and destroy the eggs.","start":80.44,"end":84.61,"wordCount":10},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"They also impose a $300 penalty.","start":85.05,"end":88.74,"wordCount":6},{"id":"g1-s10","groupIndex":0,"groupLabel":"News Report 1","answer":"The Department of Agriculture banned eggs from Mexico in 2012.","start":89.15,"end":94.2,"wordCount":10},{"id":"g1-s11","groupIndex":0,"groupLabel":"News Report 1","answer":"This was due to the risk of bird flu.","start":94.2,"end":97.32,"wordCount":9},{"id":"g1-s12","groupIndex":0,"groupLabel":"News Report 1","answer":"Officials said most people arriving at international borders with eggs are truthful about their purchases.","start":97.99,"end":105.25,"wordCount":15},{"id":"g1-s13","groupIndex":0,"groupLabel":"News Report 1","answer":"They simply don't know bringing eggs is not allowed.","start":105.38,"end":109.18,"wordCount":9},{"id":"g1-s14","groupIndex":0,"groupLabel":"News Report 1","answer":"“Generally, the items are declared during the first inspection.","start":109.84,"end":113.97,"wordCount":9},{"id":"g1-s16","groupIndex":0,"groupLabel":"News Report 1","answer":"Even so, there have been a very small number of cases recently when authorities discovered eggs during further inspections.","start":121.91,"end":130.83,"wordCount":19},{"id":"g2-s11","groupIndex":1,"groupLabel":"News Report 2","answer":"They said it has the right to implement any rules it wants.","start":242.6,"end":246.3,"wordCount":12},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"The skin was found at a construction site, and the government wrote to residents to warn them.","start":309.48,"end":315.5,"wordCount":17},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"They were told to observe and, if possible, photograph the animal.","start":316.0,"end":320.37,"wordCount":11},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"If it was moving, watch where it went.","start":320.44,"end":322.94,"wordCount":8},{"id":"g3-s5","groupIndex":2,"groupLabel":"News Report 3","answer":"It was recommended not to make contact with the animal.","start":323.3,"end":327.19,"wordCount":10},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The type of snake was determined to be one of the world's largest snake species.","start":327.92,"end":333.34,"wordCount":15},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"It is not poisonous but can still attack and kill its victims.","start":333.6,"end":338.03,"wordCount":12},{"id":"g3-s8","groupIndex":2,"groupLabel":"News Report 3","answer":"This type of snake is classified as a threat to humans, especially small children as well as pets.","start":338.59,"end":345.89,"wordCount":18},{"id":"g3-s9","groupIndex":2,"groupLabel":"News Report 3","answer":"They may carry viruses that are fatal to native snakes, which do not have resistance.","start":346.13,"end":351.74,"wordCount":15},{"id":"g3-s10","groupIndex":2,"groupLabel":"News Report 3","answer":"If officers found the snake, they would employ a licensed snake catcher to catch it and transport it to a specialist animal doctor, the government said.","start":352.05,"end":361.94,"wordCount":26},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"She won a TV competition and became a millionaire overnight.","start":482.81,"end":487.36,"wordCount":10},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"She went on a TV show where they quiz on general knowledge and she won first prize.","start":493.18,"end":499.29,"wordCount":17},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"Then why were you saying “poor Hannah”?","start":520.68,"end":523.58,"wordCount":7},{"id":"g4-s22","groupIndex":3,"groupLabel":"Conversation 1","answer":"Well, it turns out that she's spent it all already.","start":523.58,"end":527.48,"wordCount":10},{"id":"g4-s25","groupIndex":3,"groupLabel":"Conversation 1","answer":"And then she bought her husband a ridiculously expensive sports car.","start":539.49,"end":544.42,"wordCount":11},{"id":"g4-s28","groupIndex":3,"groupLabel":"Conversation 1","answer":"Because that's what matters, isn't it?","start":547.19,"end":549.05,"wordCount":6},{"id":"g4-s29","groupIndex":3,"groupLabel":"Conversation 1","answer":"I know for a fact Hannah isn't.","start":549.24,"end":551.76,"wordCount":7},{"id":"g4-s30","groupIndex":3,"groupLabel":"Conversation 1","answer":"You see, she was planning to quit the job she hates and retire early.","start":551.76,"end":556.66,"wordCount":14},{"id":"g4-s31","groupIndex":3,"groupLabel":"Conversation 1","answer":"But now that she ran out of money, she can't.","start":556.66,"end":559.59,"wordCount":10},{"id":"g4-s32","groupIndex":3,"groupLabel":"Conversation 1","answer":"Basically, she miscalculated how fast she was burning through the money, and she's now full of regret.","start":559.89,"end":567.36,"wordCount":17},{"id":"g4-s33","groupIndex":3,"groupLabel":"Conversation 1","answer":"Why don't they sell that flashy new car?","start":567.36,"end":570.26,"wordCount":8},{"id":"g4-s34","groupIndex":3,"groupLabel":"Conversation 1","answer":"She wants to, but her husband refuses to get rid of it.","start":570.26,"end":573.9,"wordCount":12},{"id":"g4-s35","groupIndex":3,"groupLabel":"Conversation 1","answer":"He says the car is the best thing that has ever happened to him, and if she sells it, he will divorce her.","start":573.9,"end":580.11,"wordCount":23},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"Yeah, the classrooms would probably smell like paint, making the air in the school all stuffy.","start":725.51,"end":731.73,"wordCount":16},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"What about our local school then?","start":731.88,"end":734.07,"wordCount":6},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"They have a wonderful arts program that would really challenge Jake in terms of creativity and imagination.","start":734.07,"end":740.3,"wordCount":17},{"id":"g5-s14","groupIndex":4,"groupLabel":"Conversation 2","answer":"Being practically next door, one of us could take him to school every day before going to work.","start":740.54,"end":746.26,"wordCount":18},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Not to mention the overwhelming amount of homework they assign, which would lead to a lot of pressure for Jake and me.","start":751.5,"end":759.11,"wordCount":22},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"What if we send him to the place near your mother's house?","start":759.2,"end":762.36,"wordCount":12},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"While this approach is beneficial when you have the time and the decision is important, it is problematic when time is crucial.","start":913.11,"end":921.42,"wordCount":22},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Analytical decision-makers struggle with deadlines and a sense of urgency with decisions.","start":921.71,"end":927.57,"wordCount":13},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"In situations where you need more timely action, decisions based on some information and instinct may work better.","start":927.8,"end":935.96,"wordCount":18},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"The desire to be right is a major driver of analytical decision-making.","start":936.86,"end":941.53,"wordCount":13},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Leaders who use this style don't want to make mistakes.","start":941.79,"end":945.56,"wordCount":10},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"Inflexibility causes you to ignore or avoid listening to the thoughts and ideas of others.","start":952.3,"end":958.77,"wordCount":15},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"You only want to utilize hard data or facts.","start":958.95,"end":962.85,"wordCount":9},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"Despite its restrictions, analytical decision-making does have several key strengths.","start":963.45,"end":968.84,"wordCount":11},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"By relying on facts and data, you minimize your potential for a wrong decision.","start":969.0,"end":974.16,"wordCount":14},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"You also get away from the habit of making guesses or following instincts.","start":974.32,"end":978.99,"wordCount":13},{"id":"g7-s1","groupIndex":6,"groupLabel":"Passage 2","answer":"What is the secret to living past 100?","start":1063.76,"end":1067.05,"wordCount":8},{"id":"g7-s2","groupIndex":6,"groupLabel":"Passage 2","answer":"Playing the piano is among the things the world's oldest person believes has contributed to her long life.","start":1067.35,"end":1074.32,"wordCount":18},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"That means she's been alive longer than any other living individual.","start":1081.6,"end":1086.34,"wordCount":11},{"id":"g7-s6","groupIndex":6,"groupLabel":"Passage 2","answer":"She has lived there ever since.","start":1098.8,"end":1100.81,"wordCount":6},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"The 115-year-old is active on social media, regularly sharing aspects of her life.","start":1101.4,"end":1108.49,"wordCount":15},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"She also shares some of her secrets to living so long.","start":1108.96,"end":1112.5,"wordCount":11},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"These include playing the piano from a young age.","start":1113.2,"end":1116.36,"wordCount":9},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"Unfortunately, she had to give up the practice seven years ago at 108.","start":1116.48,"end":1122.45,"wordCount":13},{"id":"g7-s11","groupIndex":6,"groupLabel":"Passage 2","answer":"Her other secrets for living a long life?","start":1123.08,"end":1125.89,"wordCount":8},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"She led an active lifestyle until her later years but has never followed a specific diet.","start":1125.99,"end":1132.22,"wordCount":16},{"id":"g7-s14","groupIndex":6,"groupLabel":"Passage 2","answer":"“I have always eaten little, but everything, and I have never followed any plan.”","start":1138.69,"end":1144.57,"wordCount":14},{"id":"g7-s15","groupIndex":6,"groupLabel":"Passage 2","answer":"But she does eat yogurt every day, which she said has “an infinite number of positive properties” for the body.","start":1145.01,"end":1152.21,"wordCount":20},{"id":"g7-s16","groupIndex":6,"groupLabel":"Passage 2","answer":"She has also said that the secret to a long life is “knowing how to choose” what to forget.","start":1152.65,"end":1158.46,"wordCount":19},{"id":"g7-s17","groupIndex":6,"groupLabel":"Passage 2","answer":"“Life would be impossible if we remembered everything,” she said.","start":1158.69,"end":1163.04,"wordCount":10},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"This study gathered that students had a clearer vision of the blackboard, and were able to focus more attention on the instructor.","start":1281.62,"end":1288.89,"wordCount":22},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"By sitting front and center, students were able to hear better too.","start":1289.29,"end":1293.92,"wordCount":12},{"id":"g8-s17","groupIndex":7,"groupLabel":"Passage 3","answer":"But when you sit in the front row, you may be called on more by your teacher, mainly due to the fact that you are easier to see.","start":1307.25,"end":1315.49,"wordCount":28},{"id":"g8-s18","groupIndex":7,"groupLabel":"Passage 3","answer":"So, for students who are not prepared and for those who are extremely shy, the attention could cause some unwanted stress.","start":1315.53,"end":1324.0,"wordCount":21}],"manualOnly":false},"2026-06-set1":{"clips":[{"id":"g1-s2","groupIndex":0,"groupLabel":"News Report 1","answer":"This led to a string of unexpected deliveries, and maybe a starring role in an advertisement campaign.","start":313.36,"end":321.28,"wordCount":17},{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"Keith Stonehouse said the food piled up quickly at his home Saturday night after he let his son use his cell phone to play a game before bed.","start":321.82,"end":331.44,"wordCount":28},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"He said the youngster instead used his father's online food ordering account to order food from one restaurant after another.","start":331.66,"end":340.62,"wordCount":20},{"id":"g1-s6","groupIndex":0,"groupLabel":"News Report 1","answer":"The company also is considering using the family in an online promotional campaign.","start":351.63,"end":358.36,"wordCount":13},{"id":"g1-s7","groupIndex":0,"groupLabel":"News Report 1","answer":"Most of the food went into the family's refrigerators.","start":358.73,"end":362.5,"wordCount":9},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"They also invited some neighbors over to eat some of it.","start":362.65,"end":366.13,"wordCount":11},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"The father is planning to change his password.","start":366.52,"end":369.44,"wordCount":8},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"After public feeding times, they were more likely to search for food and less likely to be inactive.","start":436.98,"end":443.3,"wordCount":18},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Some animal species have been born and raised in zoos, and so have likely become used to the presence of humans.","start":462.21,"end":469.36,"wordCount":21},{"id":"g3-s1","groupIndex":2,"groupLabel":"News Report 3","answer":"Denver is suspending its popular electric bike incentive program.","start":536.49,"end":541.32,"wordCount":9},{"id":"g3-s2","groupIndex":2,"groupLabel":"News Report 3","answer":"The program was launched in April.","start":541.5,"end":544.01,"wordCount":6},{"id":"g3-s3","groupIndex":2,"groupLabel":"News Report 3","answer":"It allowed Denver residents to apply for $400 in government funds before buying an electric bike from a participating shop.","start":544.29,"end":553.99,"wordCount":20},{"id":"g3-s4","groupIndex":2,"groupLabel":"News Report 3","answer":"Residents who met certain income qualifications could qualify for $1,200.","start":554.27,"end":561.57,"wordCount":11},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"The city then changed the program to limit the number of applications each month.","start":568.28,"end":573.42,"wordCount":14},{"id":"g3-s7","groupIndex":2,"groupLabel":"News Report 3","answer":"On Monday, the city announced the pause.","start":573.63,"end":576.85,"wordCount":7},{"id":"g3-s12","groupIndex":2,"groupLabel":"News Report 3","answer":"The city expects to resume the program early next year.","start":612.02,"end":616.64,"wordCount":10},{"id":"g3-s13","groupIndex":2,"groupLabel":"News Report 3","answer":"It also plans design changes to make participation easier and increase access to the program.","start":616.82,"end":624.13,"wordCount":15},{"id":"g4-s1","groupIndex":3,"groupLabel":"Conversation 1","answer":"Hey, Mike, what do you think of the museum you visited today?","start":726.89,"end":730.63,"wordCount":12},{"id":"g4-s5","groupIndex":3,"groupLabel":"Conversation 1","answer":"They have loads of stuff there on display.","start":734.52,"end":737.08,"wordCount":8},{"id":"g4-s6","groupIndex":3,"groupLabel":"Conversation 1","answer":"The primitive tools early humans used tell a lot about their life, but my favorite is the coin collection.","start":737.43,"end":744.57,"wordCount":19},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"They have some coins that are over 2,000 years old.","start":744.57,"end":748.15,"wordCount":11},{"id":"g4-s9","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yeah, what did you do today?","start":749.46,"end":751.68,"wordCount":6},{"id":"g4-s11","groupIndex":3,"groupLabel":"Conversation 1","answer":"The streets are narrow but beautiful with plenty of charm.","start":755.27,"end":759.23,"wordCount":10},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"We saw the Trevi Fountain, which is in all the guidebooks.","start":759.23,"end":762.7,"wordCount":11},{"id":"g4-s14","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's very pretty, but it was overcrowded with tourists.","start":763.97,"end":767.97,"wordCount":9},{"id":"g4-s16","groupIndex":3,"groupLabel":"Conversation 1","answer":"It is August, after all, the busiest month of the year.","start":770.86,"end":774.37,"wordCount":11},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, it's like the whole world is here on holiday, including us.","start":774.37,"end":778.83,"wordCount":12},{"id":"g4-s20","groupIndex":3,"groupLabel":"Conversation 1","answer":"I was thinking of doing what you did today—wandering the old streets and taking pictures.","start":782.25,"end":787.76,"wordCount":16},{"id":"g4-s21","groupIndex":3,"groupLabel":"Conversation 1","answer":"I was also thinking of visiting the square with the Spanish steps.","start":787.82,"end":791.88,"wordCount":12},{"id":"g4-s24","groupIndex":3,"groupLabel":"Conversation 1","answer":"It's a square where on one side, there are some very wide steps with flowers that go up to a church.","start":794.08,"end":800.96,"wordCount":21},{"id":"g4-s27","groupIndex":3,"groupLabel":"Conversation 1","answer":"I was also thinking of seeing that tomorrow.","start":805.62,"end":808.15,"wordCount":8},{"id":"g4-s31","groupIndex":3,"groupLabel":"Conversation 1","answer":"I spent the whole day today pretty much alone.","start":813.41,"end":816.29,"wordCount":9},{"id":"g4-s32","groupIndex":3,"groupLabel":"Conversation 1","answer":"Doing tourist stuff with others would be a welcome change.","start":816.29,"end":819.63,"wordCount":10},{"id":"g4-s33","groupIndex":3,"groupLabel":"Conversation 1","answer":"Let me ask her first, but I'm sure she'll be up for it.","start":819.63,"end":823.09,"wordCount":13},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"So, for example, certain reports that I create at the end of the month may be used by a team in another department.","start":960.91,"end":968.65,"wordCount":23},{"id":"g5-s15","groupIndex":4,"groupLabel":"Conversation 2","answer":"And in that respect, it's also important to learn about the business to see the big picture.","start":969.6,"end":975.16,"wordCount":17},{"id":"g5-s16","groupIndex":4,"groupLabel":"Conversation 2","answer":"You mean like knowing about the history of the company?","start":975.25,"end":978.59,"wordCount":10},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"Kind of, but more like knowing the details of the products and services that the company exists to deliver.","start":978.59,"end":985.64,"wordCount":19},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"Learning about the business will give you a chance to understand how your role fits into the bigger picture.","start":985.85,"end":991.89,"wordCount":19},{"id":"g5-s20","groupIndex":4,"groupLabel":"Conversation 2","answer":"I'm feeling a bit uneasy about meeting my boss as well.","start":993.06,"end":996.78,"wordCount":11},{"id":"g6-s3","groupIndex":5,"groupLabel":"Passage 1","answer":"However, research indicates that this is not actually the case.","start":1143.43,"end":1148.49,"wordCount":10},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"What consumers really think or feel often contradicts what they say.","start":1148.92,"end":1153.85,"wordCount":11},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"A big reason is that they are driven by unconscious urges, the biggest of which is emotion.","start":1154.1,"end":1160.71,"wordCount":17},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"Emotion is what really drives the purchasing behaviors and also decision-making in general.","start":1160.9,"end":1167.41,"wordCount":14},{"id":"g6-s7","groupIndex":5,"groupLabel":"Passage 1","answer":"Good marketers keep in mind this important fact all the time.","start":1167.96,"end":1172.34,"wordCount":11},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"And examples of emotion-based campaigns are everywhere.","start":1172.63,"end":1176.41,"wordCount":8},{"id":"g6-s9","groupIndex":5,"groupLabel":"Passage 1","answer":"Think for a moment, what is actually being sold in most marketing campaigns?","start":1176.84,"end":1181.69,"wordCount":13},{"id":"g6-s10","groupIndex":5,"groupLabel":"Passage 1","answer":"Luxury goods target our feelings of self-worth, acceptance, and status in the world.","start":1182.03,"end":1188.27,"wordCount":14},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"Communication devices excite us by offering a connection to friends, family, and a broader network of people.","start":1188.74,"end":1196.27,"wordCount":17},{"id":"g6-s12","groupIndex":5,"groupLabel":"Passage 1","answer":"And many other products, such as rings, target emotions related to love and relationships.","start":1196.55,"end":1203.19,"wordCount":14},{"id":"g6-s13","groupIndex":5,"groupLabel":"Passage 1","answer":"As marketers, we should focus on the features of the product, but we must also sell the lifestyle and the feeling.","start":1203.68,"end":1212.04,"wordCount":21},{"id":"g6-s14","groupIndex":5,"groupLabel":"Passage 1","answer":"The key is to highlight the emotional response a consumer will have by using the product.","start":1212.44,"end":1218.43,"wordCount":16},{"id":"g6-s15","groupIndex":5,"groupLabel":"Passage 1","answer":"To achieve the highest emotional response, we should target our consumer through many different senses.","start":1218.87,"end":1225.5,"wordCount":15},{"id":"g6-s16","groupIndex":5,"groupLabel":"Passage 1","answer":"A lot of what drives consumers is subconscious behavior.","start":1225.7,"end":1229.89,"wordCount":9},{"id":"g6-s17","groupIndex":5,"groupLabel":"Passage 1","answer":"But this isn't a bad thing.","start":1230.37,"end":1232.36,"wordCount":6},{"id":"g6-s18","groupIndex":5,"groupLabel":"Passage 1","answer":"There's nothing manipulative about helping consumers achieve desired states of emotion.","start":1232.45,"end":1238.58,"wordCount":11},{"id":"g7-s1","groupIndex":6,"groupLabel":"Passage 2","answer":"Americans are consuming and breathing in a lot of plastic.","start":1325.92,"end":1330.05,"wordCount":10},{"id":"g7-s3","groupIndex":6,"groupLabel":"Passage 2","answer":"However, scientists believe the true number is probably much higher because for some likely sources of microplastics, there was no strong data available.","start":1341.09,"end":1350.9,"wordCount":23},{"id":"g7-s4","groupIndex":6,"groupLabel":"Passage 2","answer":"Microplastics get into food and air in several ways.","start":1351.38,"end":1355.66,"wordCount":9},{"id":"g7-s7","groupIndex":6,"groupLabel":"Passage 2","answer":"The particles float through the air until people breathe them in.","start":1373.82,"end":1378.23,"wordCount":11},{"id":"g7-s8","groupIndex":6,"groupLabel":"Passage 2","answer":"They also settle on the food that people eat.","start":1378.38,"end":1381.29,"wordCount":9},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"Added sugars accounted for less, and salts, tap water and beer contributed minimal amounts.","start":1391.74,"end":1399.25,"wordCount":14},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"The included foods only make up about 15% of the average American diet.","start":1402.67,"end":1408.07,"wordCount":13},{"id":"g7-s13","groupIndex":6,"groupLabel":"Passage 2","answer":"It's not yet known how much plastic is contained in the remaining 85% of the typical diet.","start":1408.13,"end":1414.9,"wordCount":17},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"55% said they owned at least one pet.","start":1505.66,"end":1509.84,"wordCount":8},{"id":"g8-s4","groupIndex":7,"groupLabel":"Passage 3","answer":"Dogs were the most common pet, followed by cats.","start":1510.13,"end":1513.74,"wordCount":9},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"But whatever the type of animal, the vast majority of owners said their pets boosted their mental and physical health.","start":1513.96,"end":1521.55,"wordCount":20},{"id":"g8-s7","groupIndex":7,"groupLabel":"Passage 3","answer":"Roughly 80% said their pets reduced stress, and almost three quarters said their pets provided a sense of purpose.","start":1529.2,"end":1537.88,"wordCount":19},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"However, people did report a few disadvantages to pet ownership.","start":1538.25,"end":1542.99,"wordCount":10},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"These included difficulty traveling and financial strains.","start":1543.28,"end":1547.35,"wordCount":7},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"Still, plenty of research has shown that just about anyone can benefit from their pet since animals can lower stress, reduce symptoms of depression and anxiety, and encourage physical activity.","start":1554.46,"end":1567.69,"wordCount":30},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"The new poll suggests that pet ownership may be especially beneficial for older adults, given how common loneliness and social isolation are within this age group.","start":1568.19,"end":1579.89,"wordCount":26},{"id":"g8-s13","groupIndex":7,"groupLabel":"Passage 3","answer":"Human social support comes with a host of health benefits: less stress, lower rates of long-term disease, and more.","start":1580.78,"end":1589.63,"wordCount":20},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"And research shows that interacting with pets can bring many of the same benefits.","start":1589.84,"end":1595.29,"wordCount":14}],"manualOnly":false},"2026-06-set2":{"clips":[{"id":"g1-s3","groupIndex":0,"groupLabel":"News Report 1","answer":"She is now putting it on the market, having lived in it through the Second World War and the invention of television.","start":60.0,"end":67.09,"wordCount":22},{"id":"g1-s4","groupIndex":0,"groupLabel":"News Report 1","answer":"Her family bought the house for 200 pounds in 1921.","start":67.9,"end":72.31,"wordCount":10},{"id":"g1-s8","groupIndex":0,"groupLabel":"News Report 1","answer":"Except for some changes in the toilet and wash area, much of the house remains the same.","start":95.93,"end":101.29,"wordCount":17},{"id":"g1-s9","groupIndex":0,"groupLabel":"News Report 1","answer":"Mrs Gifford is selling the house and moving to a nursing home in nearby Glastonbury because of her health.","start":101.61,"end":108.2,"wordCount":19},{"id":"g2-s4","groupIndex":1,"groupLabel":"News Report 2","answer":"To survive, the man collected rainwater with a cloth.","start":184.32,"end":188.05,"wordCount":9},{"id":"g2-s5","groupIndex":1,"groupLabel":"News Report 2","answer":"He had to constantly remove water from the boat to prevent it from sinking.","start":188.31,"end":192.73,"wordCount":14},{"id":"g2-s6","groupIndex":1,"groupLabel":"News Report 2","answer":"He also tried to light a fire to send a distress signal without success.","start":193.16,"end":198.19,"wordCount":14},{"id":"g2-s7","groupIndex":1,"groupLabel":"News Report 2","answer":"Finally, a plane passed by and he signaled with a mirror.","start":199.23,"end":203.33,"wordCount":11},{"id":"g2-s8","groupIndex":1,"groupLabel":"News Report 2","answer":"He said the navy told him that he was spotted when the plane passed again.","start":203.53,"end":208.32,"wordCount":15},{"id":"g2-s9","groupIndex":1,"groupLabel":"News Report 2","answer":"The sailboat was abandoned at sea when the man was picked up by a nearby merchant ship.","start":208.97,"end":214.17,"wordCount":17},{"id":"g2-s10","groupIndex":1,"groupLabel":"News Report 2","answer":"He was found in good health but had lost weight.","start":214.48,"end":217.87,"wordCount":10},{"id":"g3-s6","groupIndex":2,"groupLabel":"News Report 3","answer":"\"We know that there are impacts and it's heartbreaking and difficult work, but in order for the district to stay out of debt, it's a step that needs to be taken,\" he said.","start":320.66,"end":331.03,"wordCount":33},{"id":"g4-s3","groupIndex":3,"groupLabel":"Conversation 1","answer":"How may I help you today?","start":454.28,"end":455.87,"wordCount":6},{"id":"g4-s7","groupIndex":3,"groupLabel":"Conversation 1","answer":"But I can't get the computer to accept my card payment.","start":466.14,"end":469.2,"wordCount":11},{"id":"g4-s8","groupIndex":3,"groupLabel":"Conversation 1","answer":"I've tried three times, but it just doesn't want to take it.","start":469.41,"end":473.12,"wordCount":12},{"id":"g4-s10","groupIndex":3,"groupLabel":"Conversation 1","answer":"I can book it and take the payment over the phone if that's not a problem for you.","start":474.73,"end":479.12,"wordCount":18},{"id":"g4-s12","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'm not very good with computers.","start":480.78,"end":482.77,"wordCount":6},{"id":"g4-s13","groupIndex":3,"groupLabel":"Conversation 1","answer":"My husband usually does all of these things, but he is in Italy on a business trip until next Thursday.","start":483.02,"end":489.86,"wordCount":20},{"id":"g4-s17","groupIndex":3,"groupLabel":"Conversation 1","answer":"Yes, that's the one and I will need two tickets, please, not too close to the front.","start":503.18,"end":508.98,"wordCount":17},{"id":"g4-s18","groupIndex":3,"groupLabel":"Conversation 1","answer":"Actually, all the tickets at the front are already sold out anyway, but I can offer you two upstairs near the middle.","start":508.98,"end":516.59,"wordCount":22},{"id":"g4-s19","groupIndex":3,"groupLabel":"Conversation 1","answer":"I assume that you don't want to be too high up.","start":516.67,"end":519.38,"wordCount":11},{"id":"g4-s23","groupIndex":3,"groupLabel":"Conversation 1","answer":"I'll reserve those for you now.","start":527.81,"end":529.85,"wordCount":6},{"id":"g5-s9","groupIndex":4,"groupLabel":"Conversation 2","answer":"I had a friend who was, and he sometimes played them all day and into the night.","start":662.12,"end":667.24,"wordCount":17},{"id":"g5-s10","groupIndex":4,"groupLabel":"Conversation 2","answer":"No, my problem was I was spending too much time on social media, messaging friends, and commenting on other people's posts.","start":667.42,"end":676.12,"wordCount":21},{"id":"g5-s11","groupIndex":4,"groupLabel":"Conversation 2","answer":"I do all of that too, as well as shopping online, and paying for everything with my phone.","start":676.47,"end":682.52,"wordCount":18},{"id":"g5-s12","groupIndex":4,"groupLabel":"Conversation 2","answer":"That is really why I don't see how anyone could live without a mobile phone.","start":682.85,"end":687.53,"wordCount":15},{"id":"g5-s13","groupIndex":4,"groupLabel":"Conversation 2","answer":"How do you buy things or communicate with your friends?","start":687.74,"end":691.37,"wordCount":10},{"id":"g5-s17","groupIndex":4,"groupLabel":"Conversation 2","answer":"But my friends and family don't live in this city, so we can't see each other often.","start":702.49,"end":707.75,"wordCount":17},{"id":"g5-s18","groupIndex":4,"groupLabel":"Conversation 2","answer":"And I don't have any choice but to chat with them online.","start":707.75,"end":710.82,"wordCount":12},{"id":"g6-s4","groupIndex":5,"groupLabel":"Passage 1","answer":"Since then, it has gone up and down, and has been going steadily down since November.","start":864.03,"end":870.81,"wordCount":16},{"id":"g6-s5","groupIndex":5,"groupLabel":"Passage 1","answer":"The gap in wage gains between people who switched jobs and those who stayed in their jobs is now closing.","start":871.31,"end":878.16,"wordCount":20},{"id":"g6-s6","groupIndex":5,"groupLabel":"Passage 1","answer":"On average, people who changed jobs have almost always gotten better pay raises than those who stayed, but in the past the difference was usually around one percentage point.","start":878.74,"end":891.54,"wordCount":29},{"id":"g6-s8","groupIndex":5,"groupLabel":"Passage 1","answer":"But now wage growth is slowing down for everyone, and job switchers are getting smaller wage bumps in their new jobs.","start":898.13,"end":906.3,"wordCount":21},{"id":"g6-s11","groupIndex":5,"groupLabel":"Passage 1","answer":"The labor market is likely cooling, because even a shortage of workers isn't overcoming the historic imbalance between employers and employees in the US: the volume of income that workers take home as a proportion of what the US economy produces is still falling.","start":925.51,"end":945.19,"wordCount":44},{"id":"g7-s9","groupIndex":6,"groupLabel":"Passage 2","answer":"This could be one reason why they gained more weight.","start":1093.98,"end":1097.1,"wordCount":10},{"id":"g7-s10","groupIndex":6,"groupLabel":"Passage 2","answer":"Highly processed food tends to be softer, which makes it easier to chew and swallow.","start":1097.62,"end":1103.57,"wordCount":15},{"id":"g7-s12","groupIndex":6,"groupLabel":"Passage 2","answer":"By the time the brain gets that signal, you've already overeaten.","start":1115.61,"end":1120.24,"wordCount":11},{"id":"g8-s2","groupIndex":7,"groupLabel":"Passage 3","answer":"This is generally attributed to backward thinking and conservative values, but new research shows that such differences could be linked to differences in the preferences of males and females.","start":1200.77,"end":1214.23,"wordCount":29},{"id":"g8-s3","groupIndex":7,"groupLabel":"Passage 3","answer":"The new study looked at how men and women were dividing work at home and why they divided it that way.","start":1214.91,"end":1221.57,"wordCount":21},{"id":"g8-s4","groupIndex":7,"groupLabel":"Passage 3","answer":"In general, both men and women took more responsibility for tasks they liked.","start":1221.74,"end":1227.64,"wordCount":13},{"id":"g8-s5","groupIndex":7,"groupLabel":"Passage 3","answer":"For example, men liked yard care and home maintenance more than women.","start":1228.23,"end":1233.65,"wordCount":12},{"id":"g8-s6","groupIndex":7,"groupLabel":"Passage 3","answer":"They leaned toward wanting primary responsibility for such tasks.","start":1233.9,"end":1238.43,"wordCount":9},{"id":"g8-s8","groupIndex":7,"groupLabel":"Passage 3","answer":"The researchers added that there was not a single childcare task that men liked more than women.","start":1248.9,"end":1255.38,"wordCount":17},{"id":"g8-s9","groupIndex":7,"groupLabel":"Passage 3","answer":"Keep in mind, however, that as with any research on group differences, there were large within-group differences.","start":1255.68,"end":1263.21,"wordCount":18},{"id":"g8-s11","groupIndex":7,"groupLabel":"Passage 3","answer":"The authors noted that previous research revealed gender differences in attitudes towards family and career.","start":1274.93,"end":1282.81,"wordCount":15},{"id":"g8-s12","groupIndex":7,"groupLabel":"Passage 3","answer":"These differences appear as early as six years old: girls that age already show more interest in helping and caring for others than boys do, and they already exhibit a greater orientation toward family versus career.","start":1282.93,"end":1299.26,"wordCount":36},{"id":"g8-s14","groupIndex":7,"groupLabel":"Passage 3","answer":"How do people generally account for differences between men and women in the amount of time spent on housework?","start":1308.1,"end":1315.41,"wordCount":19}],"manualOnly":false},"2015-06-set1":{"clips":[],"manualOnly":true},"2015-06-set2":{"clips":[],"manualOnly":true},"2015-12-set2":{"clips":[],"manualOnly":true},"2015-12-set3":{"clips":[],"manualOnly":true}}});window.CET4_OPENING?.progress(3,3);
